action.command:
python3 -c "
import json
with open('/workspace/contracts/openapi.contract.json') as f:
    spec = json.load(f)

for path, methods in sorted(spec.get('paths', {}).items()):
    for method, op in methods.items():
        print(f'=== {method.upper()} {path} ({op.get(\"operationId\")}) ===')
        if 'parameters' in op:
            print('  Params:', [p.get('name') for p in op['parameters']])
        if 'requestBody' in op:
            content = op['requestBody'].get('content', {})
            for ctype, schema_obj in content.items():
                print('  RequestBody:', ctype, json.dumps(schema_obj.get('schema', {})))
        responses = op.get('responses', {})
        for code, resp in responses.items():
            print(f'  Response {code}:', resp.get('description', ''))
            content = resp.get('content', {})
            for ctype, schema_obj in content.items():
                print(f'    Body {ctype}:', json.dumps(schema_obj.get('schema', {})))
"

