package auth

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"errors"
	"net/http"
	"strings"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"golang.org/x/crypto/bcrypt"
	"lab-transport/internal/db"
	"lab-transport/internal/models"
)

type contextKey string

const (
	UserContextKey       contextKey = "auth_user"
	ActiveRoleContextKey contextKey = "auth_active_role"
	SessionContextKey    contextKey = "auth_session_token"
)

type AuthenticatedUser struct {
	ID                 string
	Username           string
	FullName           string
	Email              string
	Phone              string
	Roles              []string
	ActiveRole         string
	Qualifications     []string
	Certifications     []models.Certification
	Active             bool
	AssignedLocationID string
	Available          bool
	CapacityUnits      int
}

type AuthService struct {
	db *db.DB
}

func NewAuthService(database *db.DB) *AuthService {
	return &AuthService{db: database}
}

func GenerateSessionToken() (string, error) {
	bytes := make([]byte, 32)
	if _, err := rand.Read(bytes); err != nil {
		return "", err
	}
	return hex.EncodeToString(bytes), nil
}

func (s *AuthService) Authenticate(ctx context.Context, username, password string) (*AuthenticatedUser, string, error) {
	var user AuthenticatedUser
	var passwordHash string
	var rolesJSON, qualJSON, certJSON []byte
	var assignedLoc *string

	query := `
		SELECT id, username, password_hash, full_name, email, phone, roles, qualifications, certifications, active, assigned_location_id, available, capacity_units
		FROM users
		WHERE username = $1
	`
	err := s.db.Pool.QueryRow(ctx, query, username).Scan(
		&user.ID,
		&user.Username,
		&passwordHash,
		&user.FullName,
		&user.Email,
		&user.Phone,
		&rolesJSON,
		&qualJSON,
		&certJSON,
		&user.Active,
		&assignedLoc,
		&user.Available,
		&user.CapacityUnits,
	)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, "", errors.New("invalid_credentials")
		}
		return nil, "", err
	}

	if !user.Active {
		return nil, "", errors.New("invalid_credentials")
	}

	if err := bcrypt.CompareHashAndPassword([]byte(passwordHash), []byte(password)); err != nil {
		return nil, "", errors.New("invalid_credentials")
	}

	if assignedLoc != nil {
		user.AssignedLocationID = *assignedLoc
	}

	// Parse roles
	user.Roles = parseStringArray(rolesJSON)
	user.Qualifications = parseStringArray(qualJSON)
	user.Certifications = parseCertifications(certJSON)

	if len(user.Roles) == 0 {
		return nil, "", errors.New("role_not_held")
	}

	activeRole := user.Roles[0]
	// Prefer administrator or dispatcher as default active role if present
	for _, r := range user.Roles {
		if r == "administrator" {
			activeRole = "administrator"
			break
		}
	}
	user.ActiveRole = activeRole

	token, err := GenerateSessionToken()
	if err != nil {
		return nil, "", err
	}

	expiresAt := time.Now().Add(24 * time.Hour)
	_, err = s.db.Pool.Exec(ctx, `
		INSERT INTO sessions (token, user_id, active_role, expires_at)
		VALUES ($1, $2, $3, $4)
	`, token, user.ID, activeRole, expiresAt)
	if err != nil {
		return nil, "", err
	}

	return &user, token, nil
}

func (s *AuthService) SelectActiveRole(ctx context.Context, token, role string) (*AuthenticatedUser, error) {
	user, err := s.ValidateSession(ctx, token)
	if err != nil {
		return nil, err
	}

	hasRole := false
	for _, r := range user.Roles {
		if r == role {
			hasRole = true
			break
		}
	}
	if !hasRole {
		return nil, errors.New("role_not_held")
	}

	_, err = s.db.Pool.Exec(ctx, `
		UPDATE sessions
		SET active_role = $1
		WHERE token = $2
	`, role, token)
	if err != nil {
		return nil, err
	}

	user.ActiveRole = role
	return user, nil
}

func (s *AuthService) ValidateSession(ctx context.Context, token string) (*AuthenticatedUser, error) {
	if token == "" {
		return nil, errors.New("unauthorized")
	}

	var user AuthenticatedUser
	var rolesJSON, qualJSON, certJSON []byte
	var activeRole string
	var expiresAt time.Time
	var assignedLoc *string

	query := `
		SELECT u.id, u.username, u.full_name, u.email, u.phone, u.roles, u.qualifications, u.certifications, u.active, u.assigned_location_id, u.available, u.capacity_units, s.active_role, s.expires_at
		FROM sessions s
		JOIN users u ON s.user_id = u.id
		WHERE s.token = $1
	`
	err := s.db.Pool.QueryRow(ctx, query, token).Scan(
		&user.ID,
		&user.Username,
		&user.FullName,
		&user.Email,
		&user.Phone,
		&rolesJSON,
		&qualJSON,
		&certJSON,
		&user.Active,
		&assignedLoc,
		&user.Available,
		&user.CapacityUnits,
		&activeRole,
		&expiresAt,
	)
	if err != nil {
		return nil, errors.New("unauthorized")
	}

	if time.Now().After(expiresAt) {
		_ = s.db.Pool.Exec(ctx, "DELETE FROM sessions WHERE token = $1", token)
		return nil, errors.New("unauthorized")
	}

	if !user.Active {
		return nil, errors.New("unauthorized")
	}

	if assignedLoc != nil {
		user.AssignedLocationID = *assignedLoc
	}

	user.Roles = parseStringArray(rolesJSON)
	user.Qualifications = parseStringArray(qualJSON)
	user.Certifications = parseCertifications(certJSON)
	user.ActiveRole = activeRole

	return &user, nil
}

func (s *AuthService) Middleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
