package services

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"golang.org/x/crypto/bcrypt"
	"lab-transport/internal/db"
	"lab-transport/internal/models"
)

type UserService struct {
	db     *db.DB
	audit  *AuditService
	events *EventService
}

func NewUserService(database *db.DB, audit *AuditService, events *EventService) *UserService {
	return &UserService{
		db:     database,
		audit:  audit,
		events: events,
	}
}

type CreateUserInput struct {
	Username           string                 `json:"username"`
	InitialPassword    string                 `json:"initialPassword"`
	Email              string                 `json:"email"`
	FullName           string                 `json:"fullName"`
	Phone              string                 `json:"phone"`
	Roles              []string               `json:"roles"`
	Qualifications     []string               `json:"qualifications"`
	Certifications     []models.Certification `json:"certifications"`
	Active             bool                   `json:"active"`
	AssignedLocationId string                 `json:"assignedLocationId"`
}

func (s *UserService) CreateUser(ctx context.Context, actorID, actorRole string, in CreateUserInput) (*models.User, error) {
	if in.Username == "" || in.InitialPassword == "" || len(in.Roles) == 0 {
		return nil, errors.New("missing_required_fields")
	}

	hashedPassword, err := bcrypt.GenerateFromPassword([]byte(in.InitialPassword), bcrypt.DefaultCost)
	if err != nil {
		return nil, err
	}

	userID := uuid.New().String()
	rolesJSON, _ := json.Marshal(in.Roles)
	if in.Qualifications == nil {
		in.Qualifications = []string{}
	}
	qualJSON, _ := json.Marshal(in.Qualifications)
	if in.Certifications == nil {
		in.Certifications = []models.Certification{}
	}
	certJSON, _ := json.Marshal(in.Certifications)

	var assignedLoc *string
	if in.AssignedLocationId != "" {
		assignedLoc = &in.AssignedLocationId
	}

	query := `
		INSERT INTO users (id, username, password_hash, email, full_name, phone, roles, qualifications, certifications, active, assigned_location_id, available, capacity_units)
		VALUES ($1, $2, $3, $4, $5, $6, $7::jsonb, $8::jsonb, $9::jsonb, $10, $11, true, 10)
	`
	_, err = s.db.Pool.Exec(ctx, query,
		userID, in.Username, string(hashedPassword), in.Email, in.FullName, in.Phone, rolesJSON, qualJSON, certJSON, in.Active, assignedLoc,
	)
	if err != nil {
		if stringsContains(err.Error(), "duplicate") || stringsContains(err.Error(), "unique") {
			return nil, errors.New("user_already_exists")
		}
		return nil, err
	}

	user := &models.User{
		UserId:             userID,
		Username:           in.Username,
		Email:              in.Email,
		FullName:           in.FullName,
		Phone:              in.Phone,
		Roles:              in.Roles,
		Qualifications:     in.Qualifications,
		Certifications:     in.Certifications,
		Active:             in.Active,
		AssignedLocationId: in.AssignedLocationId,
		Available:          true,
		CapacityUnits:      10,
	}

	_, _ = s.audit.Log(ctx, actorID, actorRole, "create_user", "user", userID, true, map[string]interface{}{
		"username": in.Username,
		"roles":    in.Roles,
	})
	_, _ = s.events.Broadcast(ctx, "user_created", "user", userID, map[string]interface{}{
		"userId":   userID,
		"username": in.Username,
	})

	return user, nil
}

type UpdateUserAccessInput struct {
	UserId             string                 `json:"userId"`
	Roles              []string               `json:"roles"`
	Qualifications     []string               `json:"qualifications"`
	Certifications     []models.Certification `json:"certifications"`
	Active             bool                   `json:"active"`
	AssignedLocationId string                 `json:"assignedLocationId"`
}

func (s *UserService) UpdateUserAccess(ctx context.Context, actorID, actorRole string, in UpdateUserAccessInput) (*models.User, error) {
	if in.UserId == "" || len(in.Roles) == 0 {
		return nil, errors.New("missing_required_fields")
	}

	rolesJSON, _ := json.Marshal(in.Roles)
	if in.Qualifications == nil {
		in.Qualifications = []string{}
	}
	qualJSON, _ := json.Marshal(in.Qualifications)
	if in.Certifications == nil {
		in.Certifications = []models.Certification{}
	}
	certJSON, _ := json.Marshal(in.Certifications)

	var assignedLoc *string
	if in.AssignedLocationId != "" {
		assignedLoc = &in.AssignedLocationId
	}

	query := `
		UPDATE users
		SET roles = $1::jsonb, qualifications = $2::jsonb, certifications = $3::jsonb, active = $4, assigned_location_id = $5, updated_at = NOW()
		WHERE id = $6
		RETURNING username, email, full_name, phone, available, capacity_units
	`
	var user models.User
	user.UserId = in.UserId
	user.Roles = in.Roles
	user.Qualifications = in.Qualifications
	user.Certifications = in.Certifications
	user.Active = in.Active
	user.AssignedLocationId = in.AssignedLocationId

	err := s.db.Pool.QueryRow(ctx, query,
		rolesJSON, qualJSON, certJSON, in.Active, assignedLoc, in.UserId,
	).Scan(&user.Username, &user.Email, &user.FullName, &user.Phone, &user.Available, &user.CapacityUnits)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, errors.New("user_not_found")
		}
		return nil, err
	}

	_, _ = s.audit.Log(ctx, actorID, actorRole, "update_user_access", "user", in.UserId, true, map[string]interface{}{
		"roles":  in.Roles,
		"active": in.Active,
	})
	_, _ = s.events.Broadcast(ctx, "user_updated", "user", in.UserId, map[string]interface{}{
		"userId": in.UserId,
		"roles":  in.Roles,
	})

	return &user, nil
}

func (s *UserService) GetUser(ctx context.Context, userID string) (*models.User, error) {
	var user models.User
	var rolesJSON, qualJSON, certJSON []byte
	var assignedLoc *string

	query := `
		SELECT id, username, email, full_name, phone, roles, qualifications, certifications, active, assigned_location_id, available, capacity_units
		FROM users
		WHERE id = $1
	`
	err := s.db.Pool.QueryRow(ctx, query, userID).Scan(
		&user.UserId, &user.Username, &user.Email, &user.FullName, &user.Phone, &rolesJSON, &qualJSON, &certJSON,
		&user.Active, &assignedLoc, &user.Available, &user.CapacityUnits,
	)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, errors.New("user_not_found")
		}
		return nil, err
	}

	if assignedLoc != nil {
		user.AssignedLocationId = *assignedLoc
	}
	user.Roles = parseStringList(rolesJSON)
	user.Qualifications = parseStringList(qualJSON)
	user.Certifications = parseCertificationList(certJSON)

	return &user, nil
}

func (s *UserService) SetWorkerAvailability(ctx context.Context, actorID, actorRole, workerID string, available bool, capacityUnits int) (*models.OperationsWorker, error) {
	query := `
		UPDATE users
		SET available = $1, capacity_units = $2, updated_at = NOW()
		WHERE id = $3
		RETURNING full_name, roles
	`
	var fullName string
	var rolesJSON []byte
	err := s.db.Pool.QueryRow(ctx, query, available, capacityUnits, workerID).Scan(&fullName, &rolesJSON)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, errors.New("worker_not_found")
		}
		return nil, err
	}

