package services

import (
	"context"
	"encoding/json"
	"errors"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"lab-transport/internal/db"
	"lab-transport/internal/models"
	"lab-transport/internal/routing"
)

type LocationService struct {
	db      *db.DB
	routing *routing.ServiceabilityEngine
	audit   *AuditService
	events  *EventService
}

func NewLocationService(database *db.DB, rEngine *routing.ServiceabilityEngine, audit *AuditService, events *EventService) *LocationService {
	return &LocationService{
		db:      database,
		routing: rEngine,
		audit:   audit,
		events:  events,
	}
}

type CreateLocationInput struct {
	Name            string            `json:"name"`
	Coordinate      models.Coordinate `json:"coordinate"`
	CoverageKm      float64           `json:"coverageKm"`
	HandlingMinutes int               `json:"handlingMinutes"`
	Active          bool              `json:"active"`
	Functions       []string          `json:"functions"`
}

func (s *LocationService) CreateLocation(ctx context.Context, actorID, actorRole string, in CreateLocationInput) (*models.Location, error) {
	if in.Name == "" || len(in.Functions) == 0 {
		return nil, errors.New("missing_required_fields")
	}

	coverage := in.CoverageKm
	if coverage <= 0 {
		coverage = 5.0
	}

	funcState := models.LocationFunctionStates{}
	for _, f := range in.Functions {
		switch f {
		case "collection_point":
			funcState.CollectionPoint = true
		case "transfer_point":
			funcState.TransferPoint = true
		case "hub":
			funcState.Hub = true
		case "laboratory":
			funcState.Laboratory = true
		}
	}

	funcBytes, _ := json.Marshal(funcState)
	locID := uuid.New().String()

	query := `
		INSERT INTO locations (id, name, latitude, longitude, coverage_km, handling_minutes, active, functions, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units)
		VALUES ($1, $2, $3, $4, $5, $6, $7, $8::jsonb, 200, 0, 100, 0)
	`
	_, err := s.db.Pool.Exec(ctx, query,
		locID, in.Name, in.Coordinate.Latitude, in.Coordinate.Longitude, coverage, in.HandlingMinutes, in.Active, funcBytes,
	)
	if err != nil {
		return nil, err
	}

	_ = s.routing.RecomputeSnapshot(ctx)

	loc := &models.Location{
		LocationId:      locID,
		Name:            in.Name,
		Coordinate:      in.Coordinate,
		CoverageKm:      coverage,
		HandlingMinutes: in.HandlingMinutes,
		Active:          in.Active,
		Functions:       funcState,
	}

	_, _ = s.audit.Log(ctx, actorID, actorRole, "create_location", "location", locID, true, map[string]interface{}{
		"name":   in.Name,
		"active": in.Active,
	})
	_, _ = s.events.Broadcast(ctx, "location_created", "location", locID, map[string]interface{}{
		"locationId": locID,
		"name":       in.Name,
	})

	return loc, nil
}

type UpdateLocationInput struct {
	LocationId      string            `json:"locationId"`
	Name            string            `json:"name"`
	Coordinate      models.Coordinate `json:"coordinate"`
	CoverageKm      float64           `json:"coverageKm"`
	HandlingMinutes int               `json:"handlingMinutes"`
	Functions       []string          `json:"functions"`
}

func (s *LocationService) UpdateLocation(ctx context.Context, actorID, actorRole string, in UpdateLocationInput) (*models.Location, error) {
	if in.LocationId == "" || in.Name == "" {
		return nil, errors.New("missing_required_fields")
	}

	coverage := in.CoverageKm
	if coverage <= 0 {
		coverage = 5.0
	}

	funcState := models.LocationFunctionStates{}
	for _, f := range in.Functions {
		switch f {
		case "collection_point":
			funcState.CollectionPoint = true
		case "transfer_point":
			funcState.TransferPoint = true
		case "hub":
			funcState.Hub = true
		case "laboratory":
			funcState.Laboratory = true
		}
	}
	funcBytes, _ := json.Marshal(funcState)

	query := `
		UPDATE locations
		SET name = $1, latitude = $2, longitude = $3, coverage_km = $4, handling_minutes = $5, functions = $6::jsonb, updated_at = NOW()
		WHERE id = $7
		RETURNING active
	`
	var active bool
	err := s.db.Pool.QueryRow(ctx, query,
		in.Name, in.Coordinate.Latitude, in.Coordinate.Longitude, coverage, in.HandlingMinutes, funcBytes, in.LocationId,
	).Scan(&active)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, errors.New("location_not_found")
		}
		return nil, err
	}

	_ = s.routing.RecomputeSnapshot(ctx)

	loc := &models.Location{
		LocationId:      in.LocationId,
		Name:            in.Name,
		Coordinate:      in.Coordinate,
		CoverageKm:      coverage,
		HandlingMinutes: in.HandlingMinutes,
		Active:          active,
		Functions:       funcState,
	}

	_, _ = s.audit.Log(ctx, actorID, actorRole, "update_location", "location", in.LocationId, true, map[string]interface{}{
		"name": in.Name,
	})
	_, _ = s.events.Broadcast(ctx, "location_updated", "location", in.LocationId, map[string]interface{}{
		"locationId": in.LocationId,
	})

	return loc, nil
}

func (s *LocationService) SetLocationStatus(ctx context.Context, actorID, actorRole, locationID string, active bool) (*models.Location, error) {
	query := `
		UPDATE locations
		SET active = $1, updated_at = NOW()
		WHERE id = $2
		RETURNING name, latitude, longitude, coverage_km, handling_minutes, functions
	`
	var loc models.Location
	loc.LocationId = locationID
	loc.Active = active

	var funcBytes []byte
	err := s.db.Pool.QueryRow(ctx, query, active, locationID).Scan(
		&loc.Name, &loc.Coordinate.Latitude, &loc.Coordinate.Longitude, &loc.CoverageKm, &loc.HandlingMinutes, &funcBytes,
	)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, errors.New("location_not_found")
		}
		return nil, err
	}

	_ = json.Unmarshal(funcBytes, &loc.Functions)
	_ = s.routing.RecomputeSnapshot(ctx)

	_, _ = s.audit.Log(ctx, actorID, actorRole, "set_location_status", "location", locationID, true, map[string]interface{}{
		"active": active,
	})
	_, _ = s.events.Broadcast(ctx, "location_status_updated", "location", locationID, map[string]interface{}{
		"locationId": locationID,
		"active":     active,
	})

	return &loc, nil
}

func (s *LocationService) SetLocationFunctionStatus(ctx context.Context, actorID, actorRole, locationID, fn string, active bool) (*models.Location, error) {
	var funcBytes []byte
	var loc models.Location
	loc.LocationId = locationID

	err := s.db.Pool.QueryRow(ctx, "SELECT name, latitude, longitude, coverage_km, handling_minutes, active, functions FROM locations WHERE id = $1", locationID).Scan(
		&loc.Name, &loc.Coordinate.Latitude, &loc.Coordinate.Longitude, &loc.CoverageKm, &loc.HandlingMinutes, &loc.Active, &funcBytes,
	)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, errors.New("location_not_found")
		}
		return nil, err
	}

	_ = json.Unmarshal(funcBytes, &loc.Functions)
	switch fn {
	case "collection_point":
		loc.Functions.CollectionPoint = active
	case "transfer_point":
		loc.Functions.TransferPoint = active
	case "hub":
		loc.Functions.Hub = active
	case "laboratory":
		loc.Functions.Laboratory = active
	}

	updatedBytes, _ := json.Marshal(loc.Functions)
	_, err = s.db.Pool.Exec(ctx, "UPDATE locations SET functions = $1::jsonb, updated_at = NOW() WHERE id = $2", updatedBytes, locationID)
	if err != nil {
		return nil, err
	}

	_ = s.routing.RecomputeSnapshot(ctx)

	_, _ = s.audit.Log(ctx, actorID, actorRole, "set_location_function_status", "location", locationID, true, map[string]interface{}{
		"function": fn,
		"active":   active,
	})
	_, _ = s.events.Broadcast(ctx, "location_function_updated", "location", locationID, map[string]interface{}{
		"locationId": locationID,
		"function":   fn,
		"active":     active,
	})

	return &loc, nil
}

type CreateConnectionInput struct {
	FromLocationId string  `json:"fromLocationId"`
	ToLocationId   string  `json:"toLocationId"`
	TravelMinutes  int     `json:"travelMinutes"`
	CostUnits      float64 `json:"costUnits"`
	Cooled         bool    `json:"cooled"`
	Active         bool    `json:"active"`
}

func (s *LocationService) CreateConnection(ctx context.Context, actorID, actorRole string, in CreateConnectionInput) (*models.OperationsConnection, error) {
	if in.FromLocationId == "" || in.ToLocationId == "" || in.TravelMinutes <= 0 {
		return nil, errors.New("missing_required_fields")
	}

	connID := uuid.New().String()
	query := `
		INSERT INTO connections (id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units)
		VALUES ($1, $2, $3, $4, $5, $6, $7, 50, 0, 25, 0)
	`
	_, err := s.db.Pool.Exec(ctx, query,
		connID, in.FromLocationId, in.ToLocationId, in.TravelMinutes, in.CostUnits, in.Cooled, in.Active,
	)
	if err != nil {
		return nil, err
	}

	_ = s.routing.RecomputeSnapshot(ctx)

	conn := &models.OperationsConnection{
		ID:             connID,
		ConnectionId:   connID,
		FromLocationId: in.FromLocationId,
		ToLocationId:   in.ToLocationId,
		TravelMinutes:  in.TravelMinutes,
		CostUnits:      in.CostUnits,
		Cooled:         in.Cooled,
		Active:         in.Active,
		Capacity: &models.Capacity{
			CapacityUnits:        50,
			ReservedUnits:        0,
			AvailableUnits:       50,
			CooledCapacityUnits:  25,
			CooledReservedUnits:  0,
			CooledAvailableUnits: 25,
		},
	}

	_, _ = s.audit.Log(ctx, actorID, actorRole, "create_connection", "connection", connID, true, map[string]interface{}{
		"fromLocationId": in.FromLocationId,
		"toLocationId":   in.ToLocationId,
		"travelMinutes":  in.TravelMinutes,
	})
	_, _ = s.events.Broadcast(ctx, "connection_created", "connection", connID, map[string]interface{}{
		"connectionId": connID,
	})

	return conn, nil
}

func (s *LocationService) SetConnectionStatus(ctx context.Context, actorID, actorRole, connectionID string, active bool) (*models.OperationsConnection, error) {
	query := `
		UPDATE connections
		SET active = $1, updated_at = NOW()
		WHERE id = $2
		RETURNING from_location_id, to_location_id, travel_minutes, cost_units, cooled, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
	`
	var conn models.OperationsConnection
	conn.ID = connectionID
	conn.ConnectionId = connectionID
	conn.Active = active
	conn.Capacity = &models.Capacity{}

	err := s.db.Pool.QueryRow(ctx, query, active, connectionID).Scan(
		&conn.FromLocationId, &conn.ToLocationId, &conn.TravelMinutes, &conn.CostUnits, &conn.Cooled,
		&conn.Capacity.CapacityUnits, &conn.Capacity.ReservedUnits, &conn.Capacity.CooledCapacityUnits, &conn.Capacity.CooledReservedUnits,
	)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, errors.New("connection_not_found")
		}
		return nil, err
	}

	conn.Capacity.AvailableUnits = conn.Capacity.CapacityUnits - conn.Capacity.ReservedUnits
	conn.Capacity.CooledAvailableUnits = conn.Capacity.CooledCapacityUnits - conn.Capacity.CooledReservedUnits

	_ = s.routing.RecomputeSnapshot(ctx)

	_, _ = s.audit.Log(ctx, actorID, actorRole, "set_connection_status", "connection", connectionID, true, map[string]interface{}{
		"active": active,
	})
	_, _ = s.events.Broadcast(ctx, "connection_status_updated", "connection", connectionID, map[string]interface{}{
		"connectionId": connectionID,
		"active":       active,
	})

	return &conn, nil
}

func (s *LocationService) ConfigureCapacity(ctx context.Context, actorID, actorRole, resourceID string, capacityUnits, cooledCapacityUnits int) (*models.Capacity, error) {
	if capacityUnits < 0 || cooledCapacityUnits < 0 {
		return nil, errors.New("invalid_capacity")
	}

	// Try locations first
	queryLoc := `
		UPDATE locations
		SET capacity_units = $1, cooled_capacity_units = $2, updated_at = NOW()
		WHERE id = $3
		RETURNING reserved_units, cooled_reserved_units
	`
	var resUnits, cooledResUnits int
	err := s.db.Pool.QueryRow(ctx, queryLoc, capacityUnits, cooledCapacityUnits, resourceID).Scan(&resUnits, &cooledResUnits)
	if err == nil {
		_ = s.routing.RecomputeSnapshot(ctx)
		cap := &models.Capacity{
			CapacityUnits:        capacityUnits,
			ReservedUnits:        resUnits,
			AvailableUnits:       capacityUnits - resUnits,
			CooledCapacityUnits:  cooledCapacityUnits,
			CooledReservedUnits:  cooledResUnits,
			CooledAvailableUnits: cooledCapacityUnits - cooledResUnits,
		}
		_, _ = s.audit.Log(ctx, actorID, actorRole, "configure_capacity", "location", resourceID, true, map[string]interface{}{
			"capacityUnits":       capacityUnits,
			"cooledCapacityUnits": cooledCapacityUnits,
		})
		_, _ = s.events.Broadcast(ctx, "capacity_configured", "location", resourceID, map[string]interface{}{
			"resourceId": resourceID,
		})
		return cap, nil
	}

	// Try connections
	queryConn := `
		UPDATE connections
		SET capacity_units = $1, cooled_capacity_units = $2, updated_at = NOW()
		WHERE id = $3
		RETURNING reserved_units, cooled_reserved_units
	`
	err = s.db.Pool.QueryRow(ctx, queryConn, capacityUnits, cooledCapacityUnits, resourceID).Scan(&resUnits, &cooledResUnits)
	if err == nil {
		_ = s.routing.RecomputeSnapshot(ctx)
		cap := &models.Capacity{
			CapacityUnits:        capacityUnits,
			ReservedUnits:        resUnits,
			AvailableUnits:       capacityUnits - resUnits,
			CooledCapacityUnits:  cooledCapacityUnits,
			CooledReservedUnits:  cooledResUnits,
			CooledAvailableUnits: cooledCapacityUnits - cooledResUnits,
		}
		_, _ = s.audit.Log(ctx, actorID, actorRole, "configure_capacity", "connection", resourceID, true, map[string]interface{}{
			"capacityUnits":       capacityUnits,
			"cooledCapacityUnits": cooledCapacityUnits,
		})
		_, _ = s.events.Broadcast(ctx, "capacity_configured", "connection", resourceID, map[string]interface{}{
			"resourceId": resourceID,
		})
		return cap, nil
	}

	return nil, errors.New("resource_not_found")
}

func (s *LocationService) ConfigureLaboratoryAcceptance(ctx context.Context, actorID, actorRole, labID, sampleTypeID string, accepts bool) error {
	var sampleBytes []byte
	err := s.db.Pool.QueryRow(ctx, "SELECT accepted_sample_type_ids FROM locations WHERE id = $1", labID).Scan(&sampleBytes)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return errors.New("laboratory_not_found")
		}
		return err
	}

	var acceptedIDs []string
	_ = json.Unmarshal(sampleBytes, &acceptedIDs)

	var newIDs []string
	for _, id := range acceptedIDs {
		if id != sampleTypeID {
			newIDs = append(newIDs, id)
		}
	}
	if accepts {
		newIDs = append(newIDs, sampleTypeID)
	}

	newBytes, _ := json.Marshal(newIDs)
	_, err = s.db.Pool.Exec(ctx, "UPDATE locations SET accepted_sample_type_ids = $1::jsonb, updated_at = NOW() WHERE id = $2", newBytes, labID)
	if err != nil {
		return err
	}

	_ = s.routing.RecomputeSnapshot(ctx)

	_, _ = s.audit.Log(ctx, actorID, actorRole, "configure_laboratory_acceptance", "laboratory", labID, true, map[string]interface{}{
		"sampleTypeId": sampleTypeID,
		"accepts":      accepts,
	})
	_, _ = s.events.Broadcast(ctx, "laboratory_acceptance_updated", "laboratory", labID, map[string]interface{}{
		"laboratoryId": labID,
		"sampleTypeId": sampleTypeID,
		"accepts":      accepts,
	})

	return nil
}

// Global suppress unused warning helper
var _ = time.Now

