func (s *LocationService) ConfigureCapacity(ctx context.Context, actorID, actorRole, resourceID string, capacityUnits, cooledCapacityUnits int) (*models.Capacity, error) {
	if capacityUnits < 0 || cooledCapacityUnits < 0 {
		return nil, errors.New("invalid_capacity")
	}

	// Try locations first
	queryLoc := `
		UPDATE locations
		SET capacity_units = $1, cooled_capacity_units = $2, updated_at = NOW()
		WHERE id = $3
		RETURNING reserved_units, cooled_reserved_units
	`
	var resUnits, cooledResUnits int
	err := s.db.Pool.QueryRow(ctx, queryLoc, capacityUnits, cooledCapacityUnits, resourceID).Scan(&resUnits, &cooledResUnits)
	if err == nil {
		_ = s.routing.RecomputeSnapshot(ctx)
		cap := &models.Capacity{
			CapacityUnits:        capacityUnits,
			ReservedUnits:        resUnits,
			AvailableUnits:       capacityUnits - resUnits,
			CooledCapacityUnits:  cooledCapacityUnits,
			CooledReservedUnits:  cooledResUnits,
			CooledAvailableUnits: cooledCapacityUnits - cooledResUnits,
		}
		_, _ = s.audit.Log(ctx, actorID, actorRole, "configure_capacity", "location", resourceID, true, map[string]interface{}{
			"capacityUnits":       capacityUnits,
			"cooledCapacityUnits": cooledCapacityUnits,
		})
		_, _ = s.events.Broadcast(ctx, "capacity_configured", "location", resourceID, map[string]interface{}{
			"resourceId": resourceID,
		})
		return cap, nil
	}

	// Try connections
	queryConn := `
		UPDATE connections
		SET capacity_units = $1, cooled_capacity_units = $2, updated_at = NOW()
		WHERE id = $3
		RETURNING reserved_units, cooled_reserved_units
	`
	err = s.db.Pool.QueryRow(ctx, queryConn, capacityUnits, cooledCapacityUnits, resourceID).Scan(&resUnits, &cooledResUnits)
	if err == nil {
		_ = s.routing.RecomputeSnapshot(ctx)
		cap := &models.Capacity{
			CapacityUnits:        capacityUnits,
			ReservedUnits:        resUnits,
			AvailableUnits:       capacityUnits - resUnits,
			CooledCapacityUnits:  cooledCapacityUnits,
			CooledReservedUnits:  cooledResUnits,
			CooledAvailableUnits: cooledCapacityUnits - cooledResUnits,
		}
		_, _ = s.audit.Log(ctx, actorID, actorRole, "configure_capacity", "connection", resourceID, true, map[string]interface{}{
			"capacityUnits":       capacityUnits,
			"cooledCapacityUnits": cooledCapacityUnits,
		})
		_, _ = s.events.Broadcast(ctx, "capacity_configured", "connection", resourceID, map[string]interface{}{
			"resourceId": resourceID,
		})
		return cap, nil
	}

	return nil, errors.New("resource_not_found")
}

func (s *LocationService) ConfigureLaboratoryAcceptance(ctx context.Context, actorID, actorRole, labID, sampleTypeID string, accepts bool) error {
	var sampleBytes []byte
	err := s.db.Pool.QueryRow(ctx, "SELECT accepted_sample_type_ids FROM locations WHERE id = $1", labID).Scan(&sampleBytes)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return errors.New("laboratory_not_found")
		}
		return err
	}

	var acceptedIDs []string
	_ = json.Unmarshal(sampleBytes, &acceptedIDs)

	var newIDs []string
	for _, id := range acceptedIDs {
		if id != sampleTypeID {
			newIDs = append(newIDs, id)
		}
	}
	if accepts {
		newIDs = append(newIDs, sampleTypeID)
	}

	newBytes, _ := json.Marshal(newIDs)
	_, err = s.db.Pool.Exec(ctx, "UPDATE locations SET accepted_sample_type_ids = $1::jsonb, updated_at = NOW() WHERE id = $2", newBytes, labID)
	if err != nil {
		return err
	}

	_ = s.routing.RecomputeSnapshot(ctx)

	_, _ = s.audit.Log(ctx, actorID, actorRole, "configure_laboratory_acceptance", "laboratory", labID, true, map[string]interface{}{
		"sampleTypeId": sampleTypeID,
		"accepts":      accepts,
	})
	_, _ = s.events.Broadcast(ctx, "laboratory_acceptance_updated", "laboratory", labID, map[string]interface{}{
		"laboratoryId": labID,
		"sampleTypeId": sampleTypeID,
		"accepts":      accepts,
	})

	return nil
}

