		sampleID, reqID, in.RequesterId, in.SampleTypeId, now, actorID, journeyID, routeResult.TargetLaboratoryID, in.Origin.Latitude, in.Origin.Longitude, now,
	)
	if err != nil {
		return nil, err
	}

	sampleIDsJSON, _ := json.Marshal([]string{sampleID})
	_, _ = s.db.Pool.Exec(ctx, `
		INSERT INTO journeys (id, plan_version, route_mode, status, estimated_delivery_at, total_cost_units, capacity_used, capacity_available, replan_status, sample_ids)
		VALUES ($1, 1, 'direct', 'active', $2, $3, 1, 10, 'not_required', $4::jsonb)
	`, journeyID, routeResult.EstimatedDelivery, routeResult.TotalCostUnits, sampleIDsJSON)

	// Transport legs
	var firstTransportAssignID string
	for i, leg := range routeResult.Legs {
