		"sampleId": sampleID,
		"holderId": actorID,
	})

	return s.GetSampleLifecycle(ctx, sampleID)
}

func (s *SampleService) CollectAndSealSample(
	ctx context.Context,
	actorID, actorRole string,
	sampleID, assignmentID string,
	collectedAt time.Time,
	containerType string,
	observedTemp float64,
) (*models.SampleLifecycle, error) {
	// Verify assignment
	var workerID *string
	var sampleTypeID string
	err := s.db.Pool.QueryRow(ctx, `
		SELECT a.worker_id, s.sample_type_id
		FROM assignments a
		JOIN samples s ON a.sample_id = s.id
		WHERE a.id = $1 AND a.sample_id = $2
	`, assignmentID, sampleID).Scan(&workerID, &sampleTypeID)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, errors.New("assignment_or_sample_not_found")
		}
		return nil, err
	}

	if actorRole != "administrator" && (workerID == nil || *workerID != actorID) {
		return nil, errors.New("forbidden")
	}

	st, _ := s.GetSampleType(ctx, sampleTypeID)
	tempCompliant := true
	if st != nil {
		if observedTemp < st.TemperatureMinC || observedTemp > st.TemperatureMaxC {
			tempCompliant = false
		}
	}

	sampleStatus := "sealed"
	var excJSON []byte
	if !tempCompliant {
		sampleStatus = "exception"
		excJSON, _ = json.Marshal(map[string]interface{}{
			"reason":      "temperature_out_of_range",
			"observed":    observedTemp,
			"expectedMin": st.TemperatureMinC,
			"expectedMax": st.TemperatureMaxC,
			"occurredAt":  collectedAt,
		})
	}

	querySample := `
		UPDATE samples
		SET sealed = true, sealed_at = $1, current_holder_id = $2, status = $3, exception_details = $4::jsonb, updated_at = NOW()
		WHERE id = $5
	`
	_, err = s.db.Pool.Exec(ctx, querySample, collectedAt, actorID, sampleStatus, excJSON, sampleID)
	if err != nil {
		return nil, err
	}

	// Complete collection assignment
	_, _ = s.db.Pool.Exec(ctx, `
		UPDATE assignments SET status = 'completed', updated_at = NOW() WHERE id = $1
	`, assignmentID)

	// Record checkpoint
	chkID := uuid.New().String()
	_, _ = s.db.Pool.Exec(ctx, `
		INSERT INTO checkpoints (id, sample_id, assignment_id, worker_id, container_type, observed_temperature_c, compliant, recorded_at)
		VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
	`, chkID, sampleID, assignmentID, actorID, containerType, observedTemp, tempCompliant, collectedAt)

	// Offer next assignment
	var nextAssignID string
	_ = s.db.Pool.QueryRow(ctx, `
		SELECT id FROM assignments
		WHERE sample_id = $1 AND status = 'offered' AND id != $2
		ORDER BY sequence ASC LIMIT 1
	`, sampleID, assignmentID).Scan(&nextAssignID)

	if nextAssignID != "" {
		go func() {
			ctxBg, cancel := context.WithTimeout(context.Background(), 10*time.Second)
			defer cancel()
			_, _ = s.fairness.OfferAssignment(ctxBg, nextAssignID)
		}()
	}

	_, _ = s.audit.Log(ctx, actorID, actorRole, "collect_and_seal_sample", "sample", sampleID, true, map[string]interface{}{
		"collectedAt":   collectedAt,
		"containerType": containerType,
		"observedTemp":  observedTemp,
		"compliant":     tempCompliant,
	})
	_, _ = s.events.Broadcast(ctx, "sample_sealed", "sample", sampleID, map[string]interface{}{
		"sampleId": sampleID,
		"holderId": actorID,
	})

	return s.GetSampleLifecycle(ctx, sampleID)
}

func (s *SampleService) InitiateHandoff(
	ctx context.Context,
	actorID, actorRole string,
	sampleID, fromAssignID, toAssignID, receiverID string,
	initiatedAt time.Time,
) (*models.SampleLifecycle, error) {
	// Verify sender currently holds sample
	var currentHolder *string
	err := s.db.Pool.QueryRow(ctx, "SELECT current_holder_id FROM samples WHERE id = $1", sampleID).Scan(&currentHolder)
	if err != nil {
		return nil, errors.New("sample_not_found")
	}

	if actorRole != "administrator" && (currentHolder == nil || *currentHolder != actorID) {
		return nil, errors.New("sender_not_current_holder")
	}

	handoffID := uuid.New().String()
	query := `
		INSERT INTO handoffs (id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, sender_confirmed, sender_confirmed_at, status)
		VALUES ($1, $2, $3, $4, $5, $6, true, $7, 'pending')
	`
	_, err = s.db.Pool.Exec(ctx, query,
		handoffID, sampleID, fromAssignID, toAssignID, actorID, receiverID, initiatedAt,
	)
	if err != nil {
		return nil, err
	}

	_, _ = s.audit.Log(ctx, actorID, actorRole, "initiate_handoff", "handoff", handoffID, true, map[string]interface{}{
		"sampleId":   sampleID,
		"receiverId": receiverID,
	})
	_, _ = s.events.Broadcast(ctx, "handoff_initiated", "handoff", handoffID, map[string]interface{}{
		"handoffId":  handoffID,
		"sampleId":   sampleID,
		"senderId":   actorID,
		"receiverId": receiverID,
	})

	return s.GetSampleLifecycle(ctx, sampleID)
}

func (s *SampleService) ConfirmHandoff(
	ctx context.Context,
	actorID, actorRole string,
	handoffID string,
	confirmationSide string,
	confirmedAt time.Time,
) (*models.SampleLifecycle, error) {
	var sampleID, senderID, receiverID, fromAssignID, toAssignID string
	var senderConf, receiverConf bool
	var status string

	query := `
		SELECT sample_id, sender_id, receiver_id, from_assignment_id, to_assignment_id, sender_confirmed, receiver_confirmed, status
		FROM handoffs
		WHERE id = $1
	`
	err := s.db.Pool.QueryRow(ctx, query, handoffID).Scan(
		&sampleID, &senderID, &receiverID, &fromAssignID, &toAssignID, &senderConf, &receiverConf, &status,
	)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, errors.New("handoff_not_found")
		}
		return nil, err
	}

	if status == "completed" {
		// Idempotent completion return
		return s.GetSampleLifecycle(ctx, sampleID)
	}

	if confirmationSide == "sender" {
		if actorRole != "administrator" && senderID != actorID {
			return nil, errors.New("forbidden")
		}
		senderConf = true
		_, _ = s.db.Pool.Exec(ctx, "UPDATE handoffs SET sender_confirmed = true, sender_confirmed_at = $1, updated_at = NOW() WHERE id = $2", confirmedAt, handoffID)
	} else if confirmationSide == "receiver" {
		if actorRole != "administrator" && receiverID != actorID {
			return nil, errors.New("forbidden")
		}
		receiverConf = true
		_, _ = s.db.Pool.Exec(ctx, "UPDATE handoffs SET receiver_confirmed = true, receiver_confirmed_at = $1, updated_at = NOW() WHERE id = $2", confirmedAt, handoffID)
	}

	if senderConf && receiverConf {
		// Complete transfer of custody
		_, _ = s.db.Pool.Exec(ctx, "UPDATE handoffs SET status = 'completed', updated_at = NOW() WHERE id = $1", handoffID)
		_, _ = s.db.Pool.Exec(ctx, "UPDATE samples SET current_holder_id = $1, updated_at = NOW() WHERE id = $2", receiverID, sampleID)
		if fromAssignID != "" {
			_, _ = s.db.Pool.Exec(ctx, "UPDATE assignments SET status = 'completed', updated_at = NOW() WHERE id = $1", fromAssignID)
		}
		if toAssignID != "" {
			_, _ = s.db.Pool.Exec(ctx, "UPDATE assignments SET status = 'in_transit', updated_at = NOW() WHERE id = $1", toAssignID)
		}

		_, _ = s.audit.Log(ctx, actorID, actorRole, "complete_handoff", "handoff", handoffID, true, map[string]interface{}{
			"sampleId":   sampleID,
			"newHolderId": receiverID,
		})
		_, _ = s.events.Broadcast(ctx, "custody_transferred", "sample", sampleID, map[string]interface{}{
			"sampleId":    sampleID,
			"currentHolderId": receiverID,
		})
	}

	return s.GetSampleLifecycle(ctx, sampleID)
}

func (s *SampleService) RecordHandlingCheckpoint(
	ctx context.Context,
	actorID, actorRole string,
	sampleID, assignmentID, locationID, containerType string,
	observedTemp float64,
	recordedAt time.Time,
) (*models.SampleLifecycle, error) {
	// Verify caller holds custody
	var currentHolder *string
	var sampleTypeID string
	err := s.db.Pool.QueryRow(ctx, "SELECT current_holder_id, sample_type_id FROM samples WHERE id = $1", sampleID).Scan(&currentHolder, &sampleTypeID)
	if err != nil {
		return nil, errors.New("sample_not_found")
	}

	if actorRole != "administrator" && (currentHolder == nil || *currentHolder != actorID) {
		return nil, errors.New("forbidden_not_current_holder")
	}

	st, _ := s.GetSampleType(ctx, sampleTypeID)
	compliant := true
	if st != nil {
		if observedTemp < st.TemperatureMinC || observedTemp > st.TemperatureMaxC {
			compliant = false
		}
	}

	chkID := uuid.New().String()
	var locID *string
	if locationID != "" {
		locID = &locationID
	}

	_, err = s.db.Pool.Exec(ctx, `
		INSERT INTO checkpoints (id, sample_id, assignment_id, worker_id, location_id, container_type, observed_temperature_c, compliant, recorded_at)
		VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
	`, chkID, sampleID, assignmentID, actorID, locID, containerType, observedTemp, compliant, recordedAt)
	if err != nil {
		return nil, err
	}

	if !compliant {
		excJSON, _ := json.Marshal(map[string]interface{}{
			"reason":      "temperature_out_of_range",
			"observed":    observedTemp,
			"expectedMin": st.TemperatureMinC,
			"expectedMax": st.TemperatureMaxC,
			"occurredAt":  recordedAt,
		})
		_, _ = s.db.Pool.Exec(ctx, `
			UPDATE samples SET status = 'exception', exception_details = $1::jsonb, updated_at = NOW() WHERE id = $2
		`, excJSON, sampleID)

		_, _ = s.audit.Log(ctx, actorID, actorRole, "handling_checkpoint_violation", "sample", sampleID, false, map[string]interface{}{
			"observedTemp": observedTemp,
			"containerType": containerType,
		})
	} else {
		_, _ = s.audit.Log(ctx, actorID, actorRole, "record_handling_checkpoint", "sample", sampleID, true, map[string]interface{}{
			"observedTemp": observedTemp,
			"containerType": containerType,
		})
	}

	return s.GetSampleLifecycle(ctx, sampleID)
}

func (s *SampleService) ConfirmLaboratoryReceipt(
	ctx context.Context,
	actorID, actorRole string,
	sampleID, labID string,
	receivedAt time.Time,
) (*models.SampleLifecycle, error) {
	query := `
		UPDATE samples
		SET status = 'received', received_laboratory_id = $1, received_at = $2, current_holder_id = $3, updated_at = NOW()
		WHERE id = $4
		RETURNING active_journey_id
	`
	var journeyID *string
	err := s.db.Pool.QueryRow(ctx, query, labID, receivedAt, actorID, sampleID).Scan(&journeyID)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, errors.New("sample_not_found")
		}
		return nil, err
	}

	if journeyID != nil {
		_, _ = s.db.Pool.Exec(ctx, "UPDATE journeys SET status = 'completed', updated_at = NOW() WHERE id = $1", *journeyID)
		_, _ = s.db.Pool.Exec(ctx, "UPDATE assignments SET status = 'completed', updated_at = NOW() WHERE journey_id = $1", *journeyID)
	}

	_, _ = s.audit.Log(ctx, actorID, actorRole, "confirm_laboratory_receipt", "sample", sampleID, true, map[string]interface{}{
		"laboratoryId": labID,
		"receivedAt":   receivedAt,
	})
	_, _ = s.events.Broadcast(ctx, "sample_received", "sample", sampleID, map[string]interface{}{
		"sampleId":     sampleID,
		"laboratoryId": labID,
	})

	return s.GetSampleLifecycle(ctx, sampleID)
}

func (s *SampleService) RecordLaboratoryException(
	ctx context.Context,
	actorID, actorRole string,
	sampleID, labID, reason string,
	observedAt time.Time,
) (*models.SampleLifecycle, error) {
	excJSON, _ := json.Marshal(map[string]interface{}{
		"laboratoryId": labID,
		"reason":       reason,
		"observedAt":   observedAt,
	})

	query := `
		UPDATE samples
		SET status = 'exception', exception_details = $1::jsonb, updated_at = NOW()
		WHERE id = $2
	`
	res, err := s.db.Pool.Exec(ctx, query, excJSON, sampleID)
	if err != nil {
		return nil, err
	}
	if res.RowsAffected() == 0 {
		return nil, errors.New("sample_not_found")
	}

	_, _ = s.audit.Log(ctx, actorID, actorRole, "record_laboratory_exception", "sample", sampleID, false, map[string]interface{}{
		"laboratoryId": labID,
		"reason":       reason,
	})
	_, _ = s.events.Broadcast(ctx, "laboratory_exception_recorded", "sample", sampleID, map[string]interface{}{
		"sampleId": sampleID,
		"reason":   reason,
	})

	return s.GetSampleLifecycle(ctx, sampleID)
}

func (s *SampleService) GetSampleLifecycle(ctx context.Context, sampleID string) (*models.SampleLifecycle, error) {
	var lc models.SampleLifecycle
	lc.SampleId = sampleID
	var holderID, activeJourney, recLab *string
	var excJSON []byte
	var lat, lng *float64
	var recAt *time.Time

	query := `
		SELECT status, sealed, current_holder_id, active_journey_id, received_laboratory_id, exception_details, latest_lat, latest_lng, location_recorded_at
		FROM samples
		WHERE id = $1
	`
	err := s.db.Pool.QueryRow(ctx, query, sampleID).Scan(
		&lc.Status, &lc.Sealed, &holderID, &activeJourney, &recLab, &excJSON, &lat, &lng, &recAt,
	)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, errors.New("sample_not_found")
		}
		return nil, err
	}

	if holderID != nil {
		lc.CurrentHolderId = *holderID
	}
	if activeJourney != nil {
		lc.ActiveJourneyId = *activeJourney
	}
	if recLab != nil {
		lc.ReceivedLaboratoryId = *recLab
	}
	if len(excJSON) > 0 {
		_ = json.Unmarshal(excJSON, &lc.Exception)
	}

	lc.LocationStale = true
	if lat != nil && lng != nil && recAt != nil {
		lc.LatestLocation = &models.Coordinate{Latitude: *lat, Longitude: *lng}
		lc.LocationRecordedAt = recAt
		if time.Since(*recAt) < 15*time.Minute {
			lc.LocationStale = false
		}
	}

	// Completed legs
	lc.CompletedLegIds = make([]string, 0)
	legRows, _ := s.db.Pool.Query(ctx, `
		SELECT id FROM assignments WHERE sample_id = $1 AND status = 'completed'
	`, sampleID)
	if legRows != nil {
		for legRows.Next() {
			var lid string
			_ = legRows.Scan(&lid)
			lc.CompletedLegIds = append(lc.CompletedLegIds, lid)
		}
		legRows.Close()
	}

	lc.ActiveReplacementPlanIds = make([]string, 0)

	// Check pending handoff
	var pHandID string
	var sID, rID string
	err = s.db.Pool.QueryRow(ctx, `
		SELECT id, sender_id, receiver_id FROM handoffs WHERE sample_id = $1 AND status = 'pending' LIMIT 1
	`, sampleID).Scan(&pHandID, &sID, &rID)
	if err == nil {
		lc.PendingHandoffId = pHandID
		lc.PendingHandoff = map[string]interface{}{
			"handoffId":  pHandID,
			"senderId":   sID,
			"receiverId": rID,
		}
	}

	// Timeline
	lc.Timeline = s.getSampleTimeline(ctx, sampleID)

	return &lc, nil
}

func (s *SampleService) GetSampleState(ctx context.Context, sampleID string) (*models.SampleState, error) {
	var ss models.SampleState
	ss.SampleId = sampleID

	var incompJSON []byte
	var actJourney, targetLab *string
	var lat, lng *float64
	var recAt *time.Time

	query := `
		SELECT s.request_id, s.requester_id, r.origin_lat, r.origin_lng, r.origin_type, r.requested_at, r.delivery_deadline,
		       s.sample_type_id, r.container_type, r.temperature_min_c, r.temperature_max_c, r.incompatible_sample_types,
		       r.serviceability, s.status, s.active_journey_id, s.target_laboratory_id, s.latest_lat, s.latest_lng, s.location_recorded_at
		FROM samples s
		JOIN requests r ON s.request_id = r.id
		WHERE s.id = $1
	`
	err := s.db.Pool.QueryRow(ctx, query, sampleID).Scan(
		&ss.RequestId, &ss.RequesterId, &ss.Origin.Latitude, &ss.Origin.Longitude, &ss.OriginType, &ss.RequestedAt, &ss.DeliveryDeadline,
		&ss.SampleTypeId, &ss.ContainerType, &ss.TemperatureMinC, &ss.TemperatureMaxC, &incompJSON,
		&ss.Serviceability, &ss.State.Status, &actJourney, &targetLab, &lat, &lng, &recAt,
	)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, errors.New("sample_not_found")
		}
		return nil, err
	}

	if actJourney != nil {
		ss.ActiveJourneyId = *actJourney
	}
	if targetLab != nil {
		ss.TargetLaboratoryId = *targetLab
	}
	ss.IncompatibleSampleTypes = parseStringList(incompJSON)

	ss.LocationStale = true
	if lat != nil && lng != nil && recAt != nil {
		ss.LatestLocation = &models.Coordinate{Latitude: *lat, Longitude: *lng}
		ss.LocationRecordedAt = recAt
		if time.Since(*recAt) < 15*time.Minute {
			ss.LocationStale = false
		}
	}

	// Active assignment IDs
	ss.ActiveAssignmentIds = make([]string, 0)
	aRows, _ := s.db.Pool.Query(ctx, `
		SELECT id FROM assignments WHERE sample_id = $1 AND status IN ('offered', 'accepted', 'in_transit', 'in_progress', 'at_pickup', 'picked_up', 'arrived')
	`, sampleID)
	if aRows != nil {
		for aRows.Next() {
			var aid string
			_ = aRows.Scan(&aid)
			ss.ActiveAssignmentIds = append(ss.ActiveAssignmentIds, aid)
		}
		aRows.Close()
	}

	ss.Timeline = s.getSampleTimeline(ctx, sampleID)

	return &ss, nil
}

func (s *SampleService) getSampleTimeline(ctx context.Context, sampleID string) []models.TimelineEntry {
	entries := make([]models.TimelineEntry, 0)
	rows, err := s.db.Pool.Query(ctx, `
		SELECT id, action, actor_id, role, entity_type, entity_id, success, occurred_at, details
		FROM audit_entries
		WHERE entity_id = $1 OR (details->>'sampleId') = $1
		ORDER BY occurred_at ASC, id ASC
	`, sampleID)
	if err != nil {
		return entries
	}
	defer rows.Close()

	for rows.Next() {
		var e models.TimelineEntry
		var detJSON []byte
		if err := rows.Scan(&e.EventId, &e.Action, &e.ActorId, &e.Role, &e.EntityType, &e.EntityId, &e.Success, &e.OccurredAt, &detJSON); err == nil {
			e.Details = make(map[string]interface{})
			_ = json.Unmarshal(detJSON, &e.Details)
			entries = append(entries, e)
		}
	}

	return entries
}

