package services

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"lab-transport/internal/db"
	"lab-transport/internal/models"
	"lab-transport/internal/routing"
)

type JourneyService struct {
	db       *db.DB
	routing  *routing.ServiceabilityEngine
	fairness *FairnessEngine
	audit    *AuditService
	events   *EventService
}

func NewJourneyService(
	database *db.DB,
	rEngine *routing.ServiceabilityEngine,
	fEngine *FairnessEngine,
	audit *AuditService,
	events *EventService,
) *JourneyService {
	return &JourneyService{
		db:       database,
		routing:  rEngine,
		fairness: fEngine,
		audit:    audit,
		events:   events,
	}
}

func (s *JourneyService) GetJourneyPlan(ctx context.Context, actorID, actorRole, journeyID string) (interface{}, error) {
	var jp models.JourneyPlan
	jp.JourneyId = journeyID

	var parentID *string
	var sampleIDsJSON []byte
	var estDelivery *time.Time

	query := `
		SELECT parent_journey_id, plan_version, route_mode, status, estimated_delivery_at, total_cost_units, capacity_used, capacity_available, replan_status, sample_ids
		FROM journeys
		WHERE id = $1
	`
	err := s.db.Pool.QueryRow(ctx, query, journeyID).Scan(
		&parentID, &jp.PlanVersion, &jp.RouteMode, &jp.Status, &estDelivery, &jp.TotalCostUnits, &jp.CapacityUsed, &jp.CapacityAvailable, &jp.ReplanStatus, &sampleIDsJSON,
	)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, errors.New("journey_not_found")
		}
		return nil, err
	}

	if parentID != nil {
		jp.ParentJourneyId = *parentID
	}
	jp.EstimatedDeliveryAt = estDelivery
	jp.SampleIds = parseStringList(sampleIDsJSON)

	// Fetch stops
	jp.OrderedStops = make([]models.JourneyStop, 0)
	stopRows, err := s.db.Pool.Query(ctx, `
		SELECT id, location_id, stop_type, sequence, estimated_at, dwell_minutes, completed_at, latitude, longitude
		FROM journey_stops
		WHERE journey_id = $1
		ORDER BY sequence ASC
	`, journeyID)
	if err == nil {
		for stopRows.Next() {
			var st models.JourneyStop
			var compAt *time.Time
			var lat, lng float64
			if err := stopRows.Scan(&st.StopId, &st.LocationId, &st.StopType, &st.Sequence, &st.EstimatedAt, &st.DwellMinutes, &compAt, &lat, &lng); err == nil {
				st.LocationIdSnake = st.LocationId
				st.StopTypeSnake = st.StopType
				est := st.EstimatedAt
				st.EstimatedAtSnake = &est
				st.CompletedAt = compAt
				st.Coordinate = &models.Coordinate{Latitude: lat, Longitude: lng}
				jp.OrderedStops = append(jp.OrderedStops, st)
			}
		}
		stopRows.Close()
	}

	// Fetch legs/assignments
	jp.Legs = make([]models.JourneyLeg, 0)
	jp.AssignedWorkerIds = make([]string, 0)
	jp.CollectionAssignmentIds = make([]string, 0)
	jp.NodeAssignmentIds = make([]string, 0)
	jp.LaboratoryAssignmentIds = make([]string, 0)

	assignRows, err := s.db.Pool.Query(ctx, `
		SELECT id, kind, sequence, status, from_location_id, to_location_id, worker_id, sample_id
		FROM assignments
		WHERE journey_id = $1
		ORDER BY sequence ASC
	`, journeyID)
	if err == nil {
		for assignRows.Next() {
			var aid, kind, status string
			var seq int
			var fromLoc, toLoc, wID, sID *string
			if err := assignRows.Scan(&aid, &kind, &seq, &status, &fromLoc, &toLoc, &wID, &sID); err == nil {
				leg := models.JourneyLeg{
					AssignmentId:      aid,
					AssignmentIdSnake: aid,
					Sequence:          seq,
					Status:            status,
				}
				if fromLoc != nil {
					leg.FromLocationId = *fromLoc
					leg.FromLocationIdSnake = *fromLoc
				}
				if toLoc != nil {
					leg.ToLocationId = *toLoc
					leg.ToLocationIdSnake = *toLoc
				}
				if wID != nil {
					leg.WorkerId = *wID
					leg.WorkerIdSnake = *wID
					jp.AssignedWorkerIds = append(jp.AssignedWorkerIds, *wID)
				}
				if sID != nil {
					leg.SampleId = *sID
				}
				jp.Legs = append(jp.Legs, leg)

				switch kind {
				case "collection":
					jp.CollectionAssignmentId = aid
					jp.CollectionAssignmentIds = append(jp.CollectionAssignmentIds, aid)
				case "node":
					jp.NodeAssignmentIds = append(jp.NodeAssignmentIds, aid)
				case "laboratory":
					jp.LaboratoryAssignmentIds = append(jp.LaboratoryAssignmentIds, aid)
				case "transport":
					if jp.FirstTransportAssignmentId == "" {
						jp.FirstTransportAssignmentId = aid
					} else {
						jp.FinalTransportAssignmentId = aid
					}
				}
			}
		}
		assignRows.Close()
	}

	// Tailor response based on actorRole
	if actorRole == "requester" {
		var reqLegs []map[string]interface{}
		for _, leg := range jp.Legs {
			reqLegs = append(reqLegs, map[string]interface{}{
				"sequence": leg.Sequence,
				"status":   leg.Status,
			})
		}
		return &models.RequesterJourneyPlan{
			JourneyId:           jp.JourneyId,
			ParentJourneyId:     jp.ParentJourneyId,
			PlanVersion:         jp.PlanVersion,
			RouteMode:           jp.RouteMode,
			Status:              jp.Status,
			EstimatedDeliveryAt: jp.EstimatedDeliveryAt,
			TotalCostUnits:      jp.TotalCostUnits,
			SampleIds:           jp.SampleIds,
			OrderedStops:        jp.OrderedStops,
			Legs:                reqLegs,
		}, nil
	}

	if actorRole == "collection_professional" || actorRole == "delivery_partner" || actorRole == "node_handler" || actorRole == "laboratory_team" {
		var assignedLegs []models.JourneyLeg
		var assignIDs []string
		for _, leg := range jp.Legs {
			if leg.WorkerId == actorID || actorRole == "administrator" || actorRole == "dispatcher" {
				assignedLegs = append(assignedLegs, leg)
				assignIDs = append(assignIDs, leg.AssignmentId)
			}
		}
		return &models.WorkerJourneyPlan{
			JourneyId:               jp.JourneyId,
			ParentJourneyId:         jp.ParentJourneyId,
			PlanVersion:             jp.PlanVersion,
			RouteMode:               jp.RouteMode,
			Status:                  jp.Status,
			EstimatedDeliveryAt:     jp.EstimatedDeliveryAt,
			Scope:                   "assigned_legs",
			AssignmentIds:           assignIDs,
			SampleIds:               jp.SampleIds,
			Legs:                    assignedLegs,
			OrderedStops:            jp.OrderedStops,
			CollectionAssignmentIds: jp.CollectionAssignmentIds,
			NodeAssignmentIds:       jp.NodeAssignmentIds,
			LaboratoryAssignmentIds: jp.LaboratoryAssignmentIds,
			AssignedWorkerIds:       jp.AssignedWorkerIds,
		}, nil
	}

	return &jp, nil
}

func (s *JourneyService) AcceptAssignment(ctx context.Context, actorID, actorRole, assignmentID string) error {
	var workerID *string
	var status string
	err := s.db.Pool.QueryRow(ctx, "SELECT worker_id, status FROM assignments WHERE id = $1", assignmentID).Scan(&workerID, &status)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return errors.New("assignment_not_found")
		}
		return err
	}

	if actorRole != "administrator" && (workerID == nil || *workerID != actorID) {
		return errors.New("forbidden")
	}

	_, err = s.db.Pool.Exec(ctx, "UPDATE assignments SET status = 'accepted', updated_at = NOW() WHERE id = $1", assignmentID)
	if err != nil {
		return err
	}

	_, _ = s.audit.Log(ctx, actorID, actorRole, "accept_assignment", "assignment", assignmentID, true, map[string]interface{}{
		"assignmentId": assignmentID,
	})
	_, _ = s.events.Broadcast(ctx, "assignment_accepted", "assignment", assignmentID, map[string]interface{}{
		"assignmentId": assignmentID,
		"workerId":     actorID,
	})

	return nil
}

func (s *JourneyService) DeclineAssignment(ctx context.Context, actorID, actorRole, assignmentID, reason string, declinedAt time.Time) error {
	return s.fairness.HandleDecline(ctx, assignmentID, actorID, reason)
}

func (s *JourneyService) UpdateAssignmentProgress(ctx context.Context, actorID, actorRole, assignmentID, status string, occurredAt time.Time) error {
	var workerID *string
	err := s.db.Pool.QueryRow(ctx, "SELECT worker_id FROM assignments WHERE id = $1", assignmentID).Scan(&workerID)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return errors.New("assignment_not_found")
		}
		return err
	}

	if actorRole != "administrator" && actorRole != "dispatcher" && (workerID == nil || *workerID != actorID) {
		return errors.New("forbidden")
	}

	_, err = s.db.Pool.Exec(ctx, "UPDATE assignments SET status = $1, updated_at = NOW() WHERE id = $2", status, assignmentID)
	if err != nil {
		return err
	}

	_, _ = s.audit.Log(ctx, actorID, actorRole, "update_assignment_progress", "assignment", assignmentID, true, map[string]interface{}{
		"status":     status,
		"occurredAt": occurredAt,
	})
	_, _ = s.events.Broadcast(ctx, "assignment_progress_updated", "assignment", assignmentID, map[string]interface{}{
		"assignmentId": assignmentID,
		"status":       status,
		"occurredAt":   occurredAt,
	})

	return nil
}

func (s *JourneyService) EditActivePlan(
	ctx context.Context,
	actorID, actorRole, journeyID string,
	expectedPlanVersion int,
	changeType string,
	changes map[string]interface{},
) (interface{}, error) {
	var currVersion int
	err := s.db.Pool.QueryRow(ctx, "SELECT plan_version FROM journeys WHERE id = $1", journeyID).Scan(&currVersion)
	if err != nil {
		return nil, errors.New("journey_not_found")
	}
	if currVersion != expectedPlanVersion {
		return nil, errors.New("state_snapshot_changed")
	}

	newVersion := currVersion + 1
	_, err = s.db.Pool.Exec(ctx, "UPDATE journeys SET plan_version = $1, updated_at = NOW() WHERE id = $2", newVersion, journeyID)
	if err != nil {
		return nil, err
	}

	_, _ = s.audit.Log(ctx, actorID, actorRole, "edit_active_plan", "journey", journeyID, true, map[string]interface{}{
		"changeType": changeType,
		"newVersion": newVersion,
		"changes":    changes,
	})
	_, _ = s.events.Broadcast(ctx, "journey_plan_edited", "journey", journeyID, map[string]interface{}{
		"journeyId":   journeyID,
		"planVersion": newVersion,
	})

	return s.GetJourneyPlan(ctx, actorID, actorRole, journeyID)
}

func (s *JourneyService) RerouteJourney(
	ctx context.Context,
	actorID, actorRole, journeyID string,
	expectedPlanVersion int,
	reason string,
) (interface{}, error) {
	var currVersion int
	var sampleIDsJSON []byte
	err := s.db.Pool.QueryRow(ctx, "SELECT plan_version, sample_ids FROM journeys WHERE id = $1", journeyID).Scan(&currVersion, &sampleIDsJSON)
	if err != nil {
		return nil, errors.New("journey_not_found")
	}
	if currVersion != expectedPlanVersion {
		return nil, errors.New("state_snapshot_changed")
	}

	newVersion := currVersion + 1
	_, err = s.db.Pool.Exec(ctx, `
		UPDATE journeys
		SET plan_version = $1, replan_status = 'replaced', updated_at = NOW()
		WHERE id = $2
	`, newVersion, journeyID)
	if err != nil {
		return nil, err
	}

	_, _ = s.audit.Log(ctx, actorID, actorRole, "reroute_journey", "journey", journeyID, true, map[string]interface{}{
		"reason":     reason,
		"newVersion": newVersion,
	})
	_, _ = s.events.Broadcast(ctx, "journey_rerouted", "journey", journeyID, map[string]interface{}{
		"journeyId":   journeyID,
		"planVersion": newVersion,
	})

	return s.GetJourneyPlan(ctx, actorID, actorRole, journeyID)
}

func (s *JourneyService) CancelJourney(
	ctx context.Context,
	actorID, actorRole, journeyID string,
	expectedPlanVersion int,
	reason string,
) (interface{}, error) {
	var currVersion int
	err := s.db.Pool.QueryRow(ctx, "SELECT plan_version FROM journeys WHERE id = $1", journeyID).Scan(&currVersion)
	if err != nil {
		return nil, errors.New("journey_not_found")
	}
	if currVersion != expectedPlanVersion {
		return nil, errors.New("state_snapshot_changed")
	}

	newVersion := currVersion + 1
	_, err = s.db.Pool.Exec(ctx, `
		UPDATE journeys
		SET status = 'cancelled', plan_version = $1, updated_at = NOW()
		WHERE id = $2
	`, newVersion, journeyID)
	if err != nil {
		return nil, err
	}

	_, _ = s.db.Pool.Exec(ctx, `
		UPDATE assignments
		SET status = 'cancelled', updated_at = NOW()
		WHERE journey_id = $1 AND status NOT IN ('completed')
	`, journeyID)

	_, _ = s.audit.Log(ctx, actorID, actorRole, "cancel_journey", "journey", journeyID, true, map[string]interface{}{
		"reason":     reason,
		"newVersion": newVersion,
	})
	_, _ = s.events.Broadcast(ctx, "journey_cancelled", "journey", journeyID, map[string]interface{}{
		"journeyId": journeyID,
	})

	return s.GetJourneyPlan(ctx, actorID, actorRole, journeyID)
}

func (s *JourneyService) MergeJourneys(
	ctx context.Context,
	actorID, actorRole, targetJourneyID string,
	expectedPlanVersion int,
	sourceJourneyIDs []string,
) (interface{}, error) {
	var currVersion int
	var targetSampleIDsJSON []byte
	err := s.db.Pool.QueryRow(ctx, "SELECT plan_version, sample_ids FROM journeys WHERE id = $1", targetJourneyID).Scan(&currVersion, &targetSampleIDsJSON)
	if err != nil {
		return nil, errors.New("target_journey_not_found")
	}
	if currVersion != expectedPlanVersion {
		return nil, errors.New("state_snapshot_changed")
	}

	targetSamples := parseStringList(targetSampleIDsJSON)
	allSamples := append([]string{}, targetSamples...)

	for _, srcID := range sourceJourneyIDs {
		var srcSampleJSON []byte
		err := s.db.Pool.QueryRow(ctx, "SELECT sample_ids FROM journeys WHERE id = $1", srcID).Scan(&srcSampleJSON)
		if err == nil {
			srcSamples := parseStringList(srcSampleJSON)
			allSamples = append(allSamples, srcSamples...)
			// Mark source journey as merged
			_, _ = s.db.Pool.Exec(ctx, "UPDATE journeys SET status = 'merged', updated_at = NOW() WHERE id = $1", srcID)
		}
	}

	// Check sample type incompatibilities across allSamples
	typeRows, err := s.db.Pool.Query(ctx, `
		SELECT s.id, st.id, st.name, st.batching_allowed, st.incompatible_sample_types
		FROM samples s
		JOIN sample_types st ON s.sample_type_id = st.id
		WHERE s.id = ANY($1)
	`, allSamples)
	if err == nil {
		var sampleTypeIDs []string
		var incompMap = make(map[string][]string)
		for typeRows.Next() {
			var sid, stid, stname string
			var batchAllowed bool
			var incompJSON []byte
			if err := typeRows.Scan(&sid, &stid, &stname, &batchAllowed, &incompJSON); err == nil {
				if !batchAllowed {
					typeRows.Close()
					return nil, errors.New("incompatible_batch_pulse_not_allowed")
				}
				sampleTypeIDs = append(sampleTypeIDs, stid)
				incompMap[stid] = parseStringList(incompJSON)
			}
		}
		typeRows.Close()

		for _, stid := range sampleTypeIDs {
			incomps := incompMap[stid]
			for _, other := range sampleTypeIDs {
				for _, inc := range incomps {
					if inc == other {
						return nil, errors.New("incompatible_sample_types_in_batch")
					}
				}
			}
		}
	}

	newVersion := currVersion + 1
	allSamplesJSON, _ := json.Marshal(allSamples)
	_, _ = s.db.Pool.Exec(ctx, `
		UPDATE journeys
		SET plan_version = $1, route_mode = 'batched', capacity_used = $2, sample_ids = $3::jsonb, updated_at = NOW()
		WHERE id = $4
	`, newVersion, len(allSamples), allSamplesJSON, targetJourneyID)

	_, _ = s.audit.Log(ctx, actorID, actorRole, "merge_journeys", "journey", targetJourneyID, true, map[string]interface{}{
		"sourceJourneyIds": sourceJourneyIDs,
		"newVersion":       newVersion,
	})
	_, _ = s.events.Broadcast(ctx, "journeys_merged", "journey", targetJourneyID, map[string]interface{}{
		"targetJourneyId": targetJourneyID,
	})

	return s.GetJourneyPlan(ctx, actorID, actorRole, targetJourneyID)
}

func (s *JourneyService) SplitJourney(
	ctx context.Context,
	actorID, actorRole, journeyID string,
	expectedPlanVersion int,
	sampleIDs []string,
) (interface{}, error) {
	var currVersion int
	var currSampleIDsJSON []byte
	err := s.db.Pool.QueryRow(ctx, "SELECT plan_version, sample_ids FROM journeys WHERE id = $1", journeyID).Scan(&currVersion, &currSampleIDsJSON)
	if err != nil {
		return nil, errors.New("journey_not_found")
	}
	if currVersion != expectedPlanVersion {
		return nil, errors.New("state_snapshot_changed")
	}

	currSamples := parseStringList(currSampleIDsJSON)
	remainingSamples := make([]string, 0)
	splitMap := make(map[string]bool)
	for _, id := range sampleIDs {
		splitMap[id] = true
	}
	for _, id := range currSamples {
		if !splitMap[id] {
			remainingSamples = append(remainingSamples, id)
		}
	}

	newSubJourneyID := uuid.New().String()
	splitSamplesJSON, _ := json.Marshal(sampleIDs)
	_, _ = s.db.Pool.Exec(ctx, `
		INSERT INTO journeys (id, parent_journey_id, plan_version, route_mode, status, capacity_used, capacity_available, sample_ids)
		VALUES ($1, $2, 1, 'direct', 'active', $3, 10, $4::jsonb)
	`, newSubJourneyID, journeyID, len(sampleIDs), splitSamplesJSON)

	newVersion := currVersion + 1
	remJSON, _ := json.Marshal(remainingSamples)
	_, _ = s.db.Pool.Exec(ctx, `
		UPDATE journeys
		SET plan_version = $1, capacity_used = $2, sample_ids = $3::jsonb, updated_at = NOW()
		WHERE id = $4
	`, newVersion, len(remainingSamples), remJSON, journeyID)

	_, _ = s.audit.Log(ctx, actorID, actorRole, "split_journey", "journey", journeyID, true, map[string]interface{}{
		"splitSampleIds":  sampleIDs,
		"newSubJourneyId": newSubJourneyID,
		"newVersion":      newVersion,
	})
	_, _ = s.events.Broadcast(ctx, "journey_split", "journey", journeyID, map[string]interface{}{
		"journeyId":       journeyID,
		"newSubJourneyId": newSubJourneyID,
	})

	return s.GetJourneyPlan(ctx, actorID, actorRole, journeyID)
}

func (s *JourneyService) ReportDisruption(
	ctx context.Context,
	actorID, actorRole, resourceType, resourceID, reason string,
	occurredAt time.Time,
) error {
	switch resourceType {
	case "location", "node", "laboratory":
		_, _ = s.db.Pool.Exec(ctx, "UPDATE locations SET active = false, updated_at = NOW() WHERE id = $1", resourceID)
	case "connection", "route":
		_, _ = s.db.Pool.Exec(ctx, "UPDATE connections SET active = false, updated_at = NOW() WHERE id = $1", resourceID)
	case "worker":
		_, _ = s.db.Pool.Exec(ctx, "UPDATE users SET available = false, updated_at = NOW() WHERE id = $1", resourceID)
	}

	_ = s.routing.RecomputeSnapshot(ctx)

	_, _ = s.audit.Log(ctx, actorID, actorRole, "report_disruption", resourceType, resourceID, true, map[string]interface{}{
		"reason":     reason,
		"occurredAt": occurredAt,
	})
	_, _ = s.events.Broadcast(ctx, "network_disruption_reported", resourceType, resourceID, map[string]interface{}{
		"resourceType": resourceType,
		"resourceId":   resourceID,
		"reason":       reason,
	})

	return nil
}

func (s *JourneyService) ListRoleWork(ctx context.Context, actorID, activeRole, statusFilter string) (*models.RoleWork, error) {
	work := &models.RoleWork{
		Pending:    make([]interface{}, 0),
		InProgress: make([]interface{}, 0),
		Completed:  make([]interface{}, 0),
	}

	if activeRole == "requester" {
		rows, err := s.db.Pool.Query(ctx, `
			SELECT s.id, s.request_id, s.status, r.serviceability, r.requested_at, r.delivery_deadline, r.earliest_collection_at, r.latest_collection_at, s.active_journey_id, s.target_laboratory_id, s.current_holder_id, s.location_recorded_at
			FROM samples s
			JOIN requests r ON s.request_id = r.id
			WHERE s.requester_id = $1
			ORDER BY s.created_at DESC
		`, actorID)
		if err != nil {
			return work, nil
		}
		defer rows.Close()

		for rows.Next() {
			var sw models.SampleWorkItem
			sw.Kind = "sample"
			var reqAt, delDead, earlCol, lateCol, recAt *time.Time
			var actJour, tarLab, curHold *string

			if err := rows.Scan(
				&sw.SampleId, &sw.RequestId, &sw.Status, &sw.Serviceability, &reqAt, &delDead, &earlCol, &lateCol, &actJour, &tarLab, &curHold, &recAt,
			); err == nil {
				sw.SampleIdSnake = sw.SampleId
				sw.RequestedAt = reqAt
				sw.DeliveryDeadline = delDead
				sw.EarliestCollectionAt = earlCol
				sw.LatestCollectionAt = lateCol
				if actJour != nil {
					sw.JourneyId = *actJour
					sw.ActiveJourneyId = *actJour
				}
				if tarLab != nil {
					sw.LaboratoryId = *tarLab
				}
				if curHold != nil {
					sw.CurrentHolderId = *curHold
				}
				sw.RequesterId = actorID
				sw.LocationRecordedAt = recAt
				sw.LocationStale = true
				if recAt != nil && time.Since(*recAt) < 15*time.Minute {
					sw.LocationStale = false
				}
				sw.History = s.getHistoryTimeline(ctx, sw.SampleId)

				switch sw.Status {
				case "requested", "serviceable":
					work.Pending = append(work.Pending, sw)
				case "collected", "sealed", "in_transit":
					work.InProgress = append(work.InProgress, sw)
				case "received", "delivered", "completed":
					work.Completed = append(work.Completed, sw)
				default:
					work.InProgress = append(work.InProgress, sw)
				}
			}
		}
		return work, nil
	}

	if activeRole == "dispatcher" || activeRole == "administrator" {
		rows, err := s.db.Pool.Query(ctx, `
			SELECT id, status, route_mode, plan_version, sample_ids, estimated_delivery_at
			FROM journeys
			ORDER BY created_at DESC
		`)
		if err != nil {
			return work, nil
		}
		defer rows.Close()

		for rows.Next() {
			var jw models.JourneyWorkItem
			jw.Kind = "journey"
			var sIDsJSON []byte
			var estDel *time.Time

			if err := rows.Scan(&jw.JourneyId, &jw.Status, &jw.RouteMode, &jw.PlanVersion, &sIDsJSON, &estDel); err == nil {
				jw.JourneyIdSnake = jw.JourneyId
				jw.SampleIds = parseStringList(sIDsJSON)
				jw.EstimatedDeliveryAt = estDel
				jw.AssignmentCount = len(jw.SampleIds)
				jw.History = s.getHistoryTimeline(ctx, jw.JourneyId)

				switch jw.Status {
				case "pending", "active":
					work.InProgress = append(work.InProgress, jw)
				case "completed", "cancelled", "merged":
					work.Completed = append(work.Completed, jw)
				default:
					work.Pending = append(work.Pending, jw)
				}
			}
		}
		return work, nil
	}

	// Worker roles: collection_professional, delivery_partner, node_handler, laboratory_team
	assignRows, err := s.db.Pool.Query(ctx, `
		SELECT a.id, a.kind, a.sample_id, a.status, a.journey_id, a.from_location_id, a.to_location_id, a.sequence, a.offer_expires_at, a.node_id, a.laboratory_id
		FROM assignments a
		WHERE a.worker_id = $1 OR a.status = 'offered'
		ORDER BY a.created_at DESC
	`, actorID)
	if err != nil {
		return work, nil
	}
	defer assignRows.Close()

	for assignRows.Next() {
		var aw models.AssignmentWorkItem
		var jID, fromLoc, toLoc, nID, lID *string
		var offExp *time.Time

		if err := assignRows.Scan(
			&aw.AssignmentId, &aw.Kind, &aw.SampleId, &aw.Status, &jID, &fromLoc, &toLoc, &aw.Sequence, &offExp, &nID, &lID,
		); err == nil {
			aw.AssignmentIdSnake = aw.AssignmentId
			aw.SampleIdSnake = aw.SampleId
			if jID != nil {
				aw.JourneyId = *jID
			}
			if fromLoc != nil {
				aw.FromLocationId = *fromLoc
				aw.IncomingFromLocationId = *fromLoc
			}
			if toLoc != nil {
				aw.ToLocationId = *toLoc
				aw.OutgoingToLocationId = *toLoc
			}
			if nID != nil {
				aw.NodeId = *nID
			}
			if lID != nil {
				aw.LaboratoryId = *lID
			}
			aw.OfferExpiresAt = offExp
			aw.History = s.getHistoryTimeline(ctx, aw.AssignmentId)

			switch aw.Status {
			case "offered":
				work.Pending = append(work.Pending, aw)
			case "accepted", "in_transit", "in_progress", "at_pickup", "picked_up", "arrived":
				work.InProgress = append(work.InProgress, aw)
			case "completed", "declined", "cancelled":
				work.Completed = append(work.Completed, aw)
			default:
				work.InProgress = append(work.InProgress, aw)
			}
		}
	}

	return work, nil
}

func (s *JourneyService) getHistoryTimeline(ctx context.Context, entityID string) []models.TimelineEntry {
	entries := make([]models.TimelineEntry, 0)
	rows, err := s.db.Pool.Query(ctx, `
		SELECT id, action, actor_id, role, entity_type, entity_id, success, occurred_at, details
		FROM audit_entries
		WHERE entity_id = $1 OR (details->>'sampleId') = $1 OR (details->>'journeyId') = $1 OR (details->>'assignmentId') = $1
		ORDER BY occurred_at ASC, id ASC
	`, entityID)
	if err != nil {
		return entries
	}
	defer rows.Close()

	for rows.Next() {
		var e models.TimelineEntry
		var detJSON []byte
		if err := rows.Scan(&e.EventId, &e.Action, &e.ActorId, &e.Role, &e.EntityType, &e.EntityId, &e.Success, &e.OccurredAt, &detJSON); err == nil {
			e.Details = make(map[string]interface{})
			_ = json.Unmarshal(detJSON, &e.Details)
			entries = append(entries, e)
		}
	}
	return entries
}

