package services

import (
	"context"
	"encoding/json"
	"time"

	"lab-transport/internal/db"
	"lab-transport/internal/models"
	"lab-transport/internal/routing"
)

type OperationsService struct {
	db      *db.DB
	routing *routing.ServiceabilityEngine
}

func NewOperationsService(database *db.DB, rEngine *routing.ServiceabilityEngine) *OperationsService {
	return &OperationsService{
		db:      database,
		routing: rEngine,
	}
}

type OperationsFilter struct {
	SampleTypeId string `json:"sampleTypeId"`
}

func (s *OperationsService) GetOperationsState(ctx context.Context, f OperationsFilter) (*models.OperationsState, error) {
	state := &models.OperationsState{
		Samples:                   make([]models.OperationsSample, 0),
		Workers:                   make([]models.OperationsWorker, 0),
		Locations:                 make([]models.OperationsLocation, 0),
		Connections:               make([]models.OperationsConnection, 0),
		Routes:                    make([]map[string]interface{}, 0),
		Handoffs:                  make([]map[string]interface{}, 0),
		Delays:                    make([]map[string]interface{}, 0),
		Exceptions:                make([]map[string]interface{}, 0),
		AssignmentCountSpread:    0,
		IneligibleAssignmentCount: 0,
	}

	// 1. Samples
	sampleQuery := `
		SELECT s.id, s.status, s.request_id, r.origin_lat, r.origin_lng, r.delivery_deadline, s.current_holder_id, s.active_journey_id, s.latest_lat, s.latest_lng, s.location_recorded_at
		FROM samples s
		JOIN requests r ON s.request_id = r.id
	`
	var sampleArgs []interface{}
	if f.SampleTypeId != "" {
		sampleQuery += " WHERE s.sample_type_id = $1"
		sampleArgs = append(sampleArgs, f.SampleTypeId)
	}
	sampleRows, err := s.db.Pool.Query(ctx, sampleQuery, sampleArgs...)
	if err == nil {
		for sampleRows.Next() {
			var osamp models.OperationsSample
			var origLat, origLng, lat, lng *float64
			var delDead, recAt *time.Time
			var reqID, curHold, actJour *string

			if err := sampleRows.Scan(
				&osamp.SampleId, &osamp.Status, &reqID, &origLat, &origLng, &delDead, &curHold, &actJour, &lat, &lng, &recAt,
			); err == nil {
				osamp.SampleIdSnake = osamp.SampleId
				if reqID != nil {
					osamp.RequestId = *reqID
				}
				if origLat != nil && origLng != nil {
					osamp.Origin = &models.Coordinate{Latitude: *origLat, Longitude: *origLng}
