package services

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"sort"
	"time"

	"github.com/jackc/pgx/v5"
	"lab-transport/internal/db"
	"lab-transport/internal/models"
)

type FairnessEngine struct {
	db     *db.DB
	audit  *AuditService
	events *EventService
}

func NewFairnessEngine(database *db.DB, audit *AuditService, events *EventService) *FairnessEngine {
	return &FairnessEngine{
		db:     database,
		audit:  audit,
		events: events,
	}
}

type WorkerCandidate struct {
	ID                 string
	Username           string
	FullName           string
	CapacityUnits      int
	ActiveAssignments  int
	RecentAssignments  int
	HasPenalty         bool
	AssignedLocationID string
}

func (fe *FairnessEngine) OfferAssignment(ctx context.Context, assignmentID string) (string, error) {
	var kind string
	var sampleID string
	var fromLocID, toLocID, nodeID, labID *string
	var sampleTypeID string
	var qualReq *string
	var qualCollectorReq bool

	query := `
		SELECT a.kind, a.sample_id, a.from_location_id, a.to_location_id, a.node_id, a.laboratory_id, s.sample_type_id, st.required_qualification, st.qualified_collector_required
		FROM assignments a
		JOIN samples s ON a.sample_id = s.id
		JOIN sample_types st ON s.sample_type_id = st.id
		WHERE a.id = $1
	`
	err := fe.db.Pool.QueryRow(ctx, query, assignmentID).Scan(
		&kind, &sampleID, &fromLocID, &toLocID, &nodeID, &labID, &sampleTypeID, &qualReq, &qualCollectorReq,
	)
	if err != nil {
		return "", err
	}

	// Fetch candidate workers
	var requiredRole string
	switch kind {
	case "collection":
		requiredRole = "collection_professional"
	case "transport":
		requiredRole = "delivery_partner"
	case "node":
		requiredRole = "node_handler"
	case "laboratory":
		requiredRole = "laboratory_team"
	}

	userRows, err := fe.db.Pool.Query(ctx, `
		SELECT id, username, full_name, capacity_units, roles, qualifications, certifications, assigned_location_id
		FROM users
		WHERE active = true AND available = true
	`)
	if err != nil {
		return "", err
	}
	defer userRows.Close()

	var candidates []WorkerCandidate

	for userRows.Next() {
		var uid, uname, fname string
		var capUnits int
		var rolesJSON, qualJSON, certJSON []byte
		var assignedLoc *string

		if err := userRows.Scan(&uid, &uname, &fname, &capUnits, &rolesJSON, &qualJSON, &certJSON, &assignedLoc); err != nil {
			continue
		}

		roles := parseStringList(rolesJSON)
		hasRole := false
		for _, r := range roles {
			if r == requiredRole || r == "administrator" {
				hasRole = true
				break
			}
		}
		if !hasRole {
			continue
		}

		// Check location restrictions for node and lab
		if kind == "node" && nodeID != nil {
			if assignedLoc == nil || *assignedLoc != *nodeID {
				continue
			}
		}
		if kind == "laboratory" && labID != nil {
			if assignedLoc == nil || *assignedLoc != *labID {
				continue
			}
		}

		// Check qualifications for collection
		if kind == "collection" && qualCollectorReq && qualReq != nil && *qualReq != "" {
			quals := parseStringList(qualJSON)
			certs := parseCertificationList(certJSON)
			qualified := false
			for _, q := range quals {
				if q == *qualReq || q == "qualified_collector" {
					qualified = true
					break
				}
			}
			if !qualified {
				for _, c := range certs {
					if c.Active && (c.Code == *qualReq || c.Code == "qualified_collector") {
						qualified = true
						break
					}
				}
			}
			if !qualified {
				continue
			}
		}

		// Get active assignment count
		var activeCount int
		_ = fe.db.Pool.QueryRow(ctx, `
			SELECT COUNT(*) FROM assignments
			WHERE worker_id = $1 AND status IN ('offered', 'accepted', 'in_transit', 'in_progress', 'at_pickup', 'picked_up', 'arrived')
		`, uid).Scan(&activeCount)

		if activeCount >= capUnits {
			continue
		}

		// Check recent assignments in last 24h
		var recentCount int
		_ = fe.db.Pool.QueryRow(ctx, `
			SELECT COUNT(*) FROM assignments
			WHERE worker_id = $1 AND created_at >= NOW() - INTERVAL '24 hours'
		`, uid).Scan(&recentCount)

		// Check penalty
		var penaltyUntil time.Time
		hasPenalty := false
		err = fe.db.Pool.QueryRow(ctx, `
			SELECT penalty_until FROM worker_penalties WHERE worker_id = $1
		`, uid).Scan(&penaltyUntil)
		if err == nil && time.Now().Before(penaltyUntil) {
			hasPenalty = true
		}

		candidates = append(candidates, WorkerCandidate{
			ID:                uid,
			Username:          uname,
			FullName:          fname,
			CapacityUnits:     capUnits,
			ActiveAssignments: activeCount,
			RecentAssignments: recentCount,
			HasPenalty:        hasPenalty,
		})
	}

	if len(candidates) == 0 {
		// Flag as exception if qualified worker required
		if kind == "collection" && qualCollectorReq {
			excJSON, _ := json.Marshal(map[string]interface{}{
				"reason":    "no_qualified_worker_available",
				"details":   "No qualified collection professional available for sample",
				"createdAt": time.Now().UTC(),
			})
			_, _ = fe.db.Pool.Exec(ctx, `
				UPDATE samples SET status = 'exception', exception_details = $1::jsonb, updated_at = NOW() WHERE id = $2
			`, excJSON, sampleID)
			_, _ = fe.audit.Log(ctx, "system", "system", "worker_shortage_exception", "sample", sampleID, false, map[string]interface{}{
				"reason": "no_qualified_worker_available",
			})
		}
		return "", errors.New("no_worker_available")
	}

	// Sort candidates fairly
	sort.Slice(candidates, func(i, j int) bool {
		if candidates[i].HasPenalty != candidates[j].HasPenalty {
			return !candidates[i].HasPenalty
		}
		if candidates[i].ActiveAssignments != candidates[j].ActiveAssignments {
			return candidates[i].ActiveAssignments < candidates[j].ActiveAssignments
		}
		return candidates[i].RecentAssignments < candidates[j].RecentAssignments
	})

	selected := candidates[0]
	offerExpiry := time.Now().UTC().Add(5 * time.Minute)

	_, err = fe.db.Pool.Exec(ctx, `
		UPDATE assignments
		SET worker_id = $1, status = 'offered', offer_expires_at = $2, updated_at = NOW()
		WHERE id = $3
	`, selected.ID, offerExpiry, assignmentID)
	if err != nil {
		return "", err
	}

	_, _ = fe.audit.Log(ctx, "system", "system", "offer_assignment", "assignment", assignmentID, true, map[string]interface{}{
		"workerId":       selected.ID,
		"offerExpiresAt": offerExpiry,
	})
	_, _ = fe.events.Broadcast(ctx, "assignment_offered", "assignment", assignmentID, map[string]interface{}{
		"assignmentId":   assignmentID,
		"workerId":       selected.ID,
		"offerExpiresAt": offerExpiry,
	})

	return selected.ID, nil
}

func (fe *FairnessEngine) HandleDecline(ctx context.Context, assignmentID, workerID, reason string) error {
	now := time.Now().UTC()
	penaltyDuration := 10 * time.Minute

	// Increment penalty
	_, _ = fe.db.Pool.Exec(ctx, `
		INSERT INTO worker_penalties (worker_id, decline_count, penalty_until)
		VALUES ($1, 1, $2)
		ON CONFLICT (worker_id) DO UPDATE SET
			decline_count = worker_penalties.decline_count + 1,
			penalty_until = EXCLUDED.penalty_until
	`, workerID, now.Add(penaltyDuration))

	_, err := fe.db.Pool.Exec(ctx, `
		UPDATE assignments
		SET status = 'declined', declined_by = $1, declined_at = $2, updated_at = NOW()
		WHERE id = $3 AND worker_id = $1
	`, workerID, now, assignmentID)
	if err != nil {
		return err
	}

	_, _ = fe.audit.Log(ctx, workerID, "worker", "decline_assignment", "assignment", assignmentID, true, map[string]interface{}{
		"reason": reason,
	})

	// Re-offer to next eligible worker
	go func() {
		ctxBg, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()
		_, _ = fe.OfferAssignment(ctxBg, assignmentID)
	}()

	return nil
}

