	err := s.db.Pool.QueryRow(ctx, "SELECT plan_version FROM journeys WHERE id = $1", journeyID).Scan(&currVersion)
	if err != nil {
		return nil, errors.New("journey_not_found")
	}
	if currVersion != expectedPlanVersion {
		return nil, errors.New("state_snapshot_changed")
	}

	newVersion := currVersion + 1
	_, err = s.db.Pool.Exec(ctx, "UPDATE journeys SET plan_version = $1, updated_at = NOW() WHERE id = $2", newVersion, journeyID)
	if err != nil {
		return nil, err
	}

	_, _ = s.audit.Log(ctx, actorID, actorRole, "edit_active_plan", "journey", journeyID, true, map[string]interface{}{
		"changeType": changeType,
		"newVersion": newVersion,
		"changes":    changes,
	})
	_, _ = s.events.Broadcast(ctx, "journey_plan_edited", "journey", journeyID, map[string]interface{}{
