package services

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"golang.org/x/crypto/bcrypt"
	"lab-transport/internal/db"
	"lab-transport/internal/models"
)

type UserService struct {
	db     *db.DB
	audit  *AuditService
	events *EventService
}

func NewUserService(database *db.DB, audit *AuditService, events *EventService) *UserService {
	return &UserService{
		db:     database,
		audit:  audit,
		events: events,
	}
}

type CreateUserInput struct {
	Username           string                 `json:"username"`
	InitialPassword    string                 `json:"initialPassword"`
	Email              string                 `json:"email"`
	FullName           string                 `json:"fullName"`
	Phone              string                 `json:"phone"`
	Roles              []string               `json:"roles"`
	Qualifications     []string               `json:"qualifications"`
	Certifications     []models.Certification `json:"certifications"`
	Active             bool                   `json:"active"`
	AssignedLocationId string                 `json:"assignedLocationId"`
}

func (s *UserService) CreateUser(ctx context.Context, actorID, actorRole string, in CreateUserInput) (*models.User, error) {
	if in.Username == "" || in.InitialPassword == "" || len(in.Roles) == 0 {
		return nil, errors.New("missing_required_fields")
	}

	hashedPassword, err := bcrypt.GenerateFromPassword([]byte(in.InitialPassword), bcrypt.DefaultCost)
	if err != nil {
		return nil, err
	}

	userID := uuid.New().String()
	rolesJSON, _ := json.Marshal(in.Roles)
	if in.Qualifications == nil {
		in.Qualifications = []string{}
	}
	qualJSON, _ := json.Marshal(in.Qualifications)
	if in.Certifications == nil {
		in.Certifications = []models.Certification{}
	}
	certJSON, _ := json.Marshal(in.Certifications)

	var assignedLoc *string
	if in.AssignedLocationId != "" {
		assignedLoc = &in.AssignedLocationId
	}

	query := `
		INSERT INTO users (id, username, password_hash, email, full_name, phone, roles, qualifications, certifications, active, assigned_location_id, available, capacity_units)
		VALUES ($1, $2, $3, $4, $5, $6, $7::jsonb, $8::jsonb, $9::jsonb, $10, $11, true, 10)
	`
	_, err = s.db.Pool.Exec(ctx, query,
		userID, in.Username, string(hashedPassword), in.Email, in.FullName, in.Phone, rolesJSON, qualJSON, certJSON, in.Active, assignedLoc,
	)
	if err != nil {
		if stringsContains(err.Error(), "duplicate") || stringsContains(err.Error(), "unique") {
			return nil, errors.New("user_already_exists")
		}
		return nil, err
	}

	user := &models.User{
		UserId:             userID,
