// Create Collection Request
func (h *APIHandler) CreateCollectionRequest(w http.ResponseWriter, r *http.Request) {
	u := auth.GetUser(r.Context())
	if u == nil {
		respondError(w, http.StatusUnauthorized, "unauthorized", "Authentication required")
		return
	}

	bodyBytes, err := io.ReadAll(r.Body)
	if err != nil {
		respondError(w, http.StatusBadRequest, "invalid_body", "Failed to read body")
		return
	}

	var in struct {
		services.CreateCollectionRequestInput
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := json.Unmarshal(bodyBytes, &in); err != nil {
		respondError(w, http.StatusBadRequest, "invalid_json", "Invalid request body")
		return
	}

	if in.IdempotencyKey != "" {
		if status, respBody, ok := h.checkIdempotency(r.Context(), "create_collection_request", in.IdempotencyKey, bodyBytes); ok {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(status)
			_, _ = w.Write(respBody)
			return
		}
	}

	sampleState, err := h.sampleSvc.CreateCollectionRequest(r.Context(), u.ID, u.ActiveRole, in.CreateCollectionRequestInput)
	if err != nil {
		respondError(w, http.StatusUnprocessableEntity, "unserviceable_request", err.Error())
		return
	}

	h.saveIdempotency(r.Context(), "create_collection_request", in.IdempotencyKey, bodyBytes, http.StatusCreated, sampleState)
	respondJSON(w, http.StatusCreated, sampleState)
}

