	if err := json.Unmarshal(bodyBytes, &req); err != nil {
		respondError(w, http.StatusBadRequest, "invalid_json", "Invalid request body")
		return
	}

	if req.IdempotencyKey != "" {
		if status, respBody, ok := h.checkIdempotency(r.Context(), "split_journey", req.IdempotencyKey, bodyBytes); ok {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(status)
			_, _ = w.Write(respBody)
			return
		}
	}

	plan, err := h.journeySvc.SplitJourney(r.Context(), u.ID, u.ActiveRole, req.JourneyId, req.ExpectedPlanVersion, req.SampleIds)
	if err != nil {
		if err.Error() == "state_snapshot_changed" {
			respondError(w, http.StatusConflict, "state_snapshot_changed", "Plan version conflict")
			return
		}
		respondError(w, http.StatusBadRequest, "invalid_data", err.Error())
		return
	}

	h.saveIdempotency(r.Context(), "split_journey", req.IdempotencyKey, bodyBytes, http.StatusOK, plan)
	respondJSON(w, http.StatusOK, plan)
}

// Report Disruption
func (h *APIHandler) ReportDisruption(w http.ResponseWriter, r *http.Request) {
	u := auth.GetUser(r.Context())
	if u == nil {
		respondError(w, http.StatusUnauthorized, "unauthorized", "Authentication required")
		return
	}

	bodyBytes, err := io.ReadAll(r.Body)
	if err != nil {
		respondError(w, http.StatusBadRequest, "invalid_body", "Failed to read body")
		return
	}

	var req struct {
		ResourceType   string    `json:"resourceType"`
		ResourceId     string    `json:"resourceId"`
		Reason         string    `json:"reason"`
		OccurredAt     time.Time `json:"occurredAt"`
		IdempotencyKey string    `json:"idempotencyKey"`
	}
	if err := json.Unmarshal(bodyBytes, &req); err != nil {
		respondError(w, http.StatusBadRequest, "invalid_json", "Invalid request body")
		return
	}

	if req.IdempotencyKey != "" {
		if status, respBody, ok := h.checkIdempotency(r.Context(), "report_disruption", req.IdempotencyKey, bodyBytes); ok {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(status)
			_, _ = w.Write(respBody)
			return
		}
	}

	err = h.journeySvc.ReportDisruption(r.Context(), u.ID, u.ActiveRole, req.ResourceType, req.ResourceId, req.Reason, req.OccurredAt)
	if err != nil {
		respondError(w, http.StatusBadRequest, "invalid_data", err.Error())
		return
	}

	respData := map[string]interface{}{
		"resourceType":       req.ResourceType,
		"resourceId":         req.ResourceId,
		"disruptionReported": true,
	}
	h.saveIdempotency(r.Context(), "report_disruption", req.IdempotencyKey, bodyBytes, http.StatusOK, respData)
	respondJSON(w, http.StatusOK, respData)
}

// List Role Work
func (h *APIHandler) ListRoleWork(w http.ResponseWriter, r *http.Request) {
	u := auth.GetUser(r.Context())
