func (h *APIHandler) EditActivePlan(w http.ResponseWriter, r *http.Request) {
	u := auth.GetUser(r.Context())
	if u == nil {
		respondError(w, http.StatusUnauthorized, "unauthorized", "Authentication required")
		return
	}

	bodyBytes, err := io.ReadAll(r.Body)
	if err != nil {
		respondError(w, http.StatusBadRequest, "invalid_body", "Failed to read body")
		return
	}

	var req struct {
		JourneyId           string                 `json:"journeyId"`
		ExpectedPlanVersion int                    `json:"expectedPlanVersion"`
		ChangeType          string                 `json:"changeType"`
		Changes             map[string]interface{} `json:"changes"`
		IdempotencyKey      string                 `json:"idempotencyKey"`
	}
	if err := json.Unmarshal(bodyBytes, &req); err != nil {
		respondError(w, http.StatusBadRequest, "invalid_json", "Invalid request body")
		return
	}

	if req.IdempotencyKey != "" {
		if status, respBody, ok := h.checkIdempotency(r.Context(), "edit_active_plan", req.IdempotencyKey, bodyBytes); ok {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(status)
			_, _ = w.Write(respBody)
			return
		}
	}

	plan, err := h.journeySvc.EditActivePlan(r.Context(), u.ID, u.ActiveRole, req.JourneyId, req.ExpectedPlanVersion, req.ChangeType, req.Changes)
