func (s *AuthService) SelectActiveRole(ctx context.Context, token, role string) (*AuthenticatedUser, error) {
	user, err := s.ValidateSession(ctx, token)
	if err != nil {
		return nil, err
	}

	hasRole := false
	for _, r := range user.Roles {
		if r == role {
			hasRole = true
			break
		}
	}
	if !hasRole {
		return nil, errors.New("role_not_held")
	}

	_, err = s.db.Pool.Exec(ctx, `
		UPDATE sessions
		SET active_role = $1
		WHERE token = $2
	`, role, token)
	if err != nil {
		return nil, err
	}

	user.ActiveRole = role
	return user, nil
}

func (s *AuthService) ValidateSession(ctx context.Context, token string) (*AuthenticatedUser, error) {
	if token == "" {
		return nil, errors.New("unauthorized")
	}

	var user AuthenticatedUser
	var rolesJSON, qualJSON, certJSON []byte
	var activeRole string
	var expiresAt time.Time
	var assignedLoc *string

	query := `
		SELECT u.id, u.username, u.full_name, u.email, u.phone, u.roles, u.qualifications, u.certifications, u.active, u.assigned_location_id, u.available, u.capacity_units, s.active_role, s.expires_at
		FROM sessions s
		JOIN users u ON s.user_id = u.id
		WHERE s.token = $1
	`
	err := s.db.Pool.QueryRow(ctx, query, token).Scan(
		&user.ID,
		&user.Username,
		&user.FullName,
		&user.Email,
		&user.Phone,
		&rolesJSON,
		&qualJSON,
		&certJSON,
		&user.Active,
		&assignedLoc,
		&user.Available,
		&user.CapacityUnits,
		&activeRole,
		&expiresAt,
	)
	if err != nil {
		return nil, errors.New("unauthorized")
	}

	if time.Now().After(expiresAt) {
		_, _ = s.db.Pool.Exec(ctx, "DELETE FROM sessions WHERE token = $1", token)
		return nil, errors.New("unauthorized")
	}

	if !user.Active {
		return nil, errors.New("unauthorized")
	}

	if assignedLoc != nil {
		user.AssignedLocationID = *assignedLoc
	}

	user.Roles = parseStringArray(rolesJSON)
	user.Qualifications = parseStringArray(qualJSON)
	user.Certifications = parseCertifications(certJSON)
	user.ActiveRole = activeRole

	return &user, nil
}

func (s *AuthService) EnsureInitialAdmin(ctx context.Context, username, password string) error {
	return s.db.EnsureAdmin(ctx, username, password)
}

func (s *AuthService) AuthMiddleware(next http.Handler) http.Handler {
	return s.Middleware(next)
}

func (s *AuthService) Middleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		authHeader := r.Header.Get("Authorization")
		if authHeader != "" {
			parts := strings.SplitN(authHeader, " ", 2)
			if len(parts) == 2 && strings.EqualFold(parts[0], "bearer") {
				token := strings.TrimSpace(parts[1])
				user, err := s.ValidateSession(r.Context(), token)
				if err == nil && user != nil {
					ctx := context.WithValue(r.Context(), UserContextKey, user)
					ctx = context.WithValue(ctx, ActiveRoleContextKey, user.ActiveRole)
					ctx = context.WithValue(ctx, SessionContextKey, token)
					r = r.WithContext(ctx)
				}
			}
		}
		next.ServeHTTP(w, r)
	})
}

func GetUser(ctx context.Context) *AuthenticatedUser {
	if val := ctx.Value(UserContextKey); val != nil {
		if u, ok := val.(*AuthenticatedUser); ok {
			return u
		}
	}
	return nil
}

func GetActiveRole(ctx context.Context) string {
	if val := ctx.Value(ActiveRoleContextKey); val != nil {
		if role, ok := val.(string); ok {
			return role
		}
	}
	return ""
}

func GetSessionToken(ctx context.Context) string {
	if val := ctx.Value(SessionContextKey); val != nil {
		if tok, ok := val.(string); ok {
			return tok
		}
	}
	return ""
}

func parseStringArray(data []byte) []string {
	if len(data) == 0 {
		return []string{}
	}
	var arr []string
	if err := json.Unmarshal(data, &arr); err != nil {
		return []string{}
	}
	return arr
}

func parseCertifications(data []byte) []models.Certification {
	if len(data) == 0 {
		return []models.Certification{}
	}
	var arr []models.Certification
	if err := json.Unmarshal(data, &arr); err != nil {
		return []models.Certification{}
	}
	return arr
}

