package main

import (
	"context"
	"log"
	"os"
	"time"

	"lab-transport/internal/config"
	"lab-transport/internal/db"
	"lab-transport/internal/routing"
)

func main() {
	cfg := config.LoadConfig()

	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	database, err := db.Connect(ctx, cfg.DatabaseURL)
	if err != nil {
		log.Fatalf("Failed to connect to database: %v", err)
	}
	defer database.Close()

	log.Println("Resetting database schema and seeds...")
	if err := database.Reset(ctx); err != nil {
		log.Fatalf("Failed to reset database: %v", err)
	}

	adminUser := os.Getenv("ADMIN_USERNAME")
	adminPass := os.Getenv("ADMIN_PASSWORD")
	if adminUser == "" {
		adminUser = "admin"
	}
	if adminPass == "" {
		adminPass = "Admin123!"
	}
	if err := database.EnsureAdmin(ctx, adminUser, adminPass); err != nil {
		log.Fatalf("Failed to ensure admin: %v", err)
	}

	// Recompute snapshot
	rEngine := routing.NewServiceabilityEngine(database)
	_ = rEngine.RecomputeSnapshot(ctx)

	log.Println("Database reset completed successfully.")
}

