	})

	return s.GetSampleLifecycle(ctx, sampleID)
}

func (s *SampleService) GetSampleLifecycle(ctx context.Context, sampleID string) (*models.SampleLifecycle, error) {
	var lc models.SampleLifecycle
	lc.SampleId = sampleID
	var holderID, activeJourney, recLab *string
	var excJSON []byte
	var lat, lng *float64
	var recAt *time.Time

	query := `
		SELECT status, sealed, current_holder_id, active_journey_id, received_laboratory_id, exception_details, latest_lat, latest_lng, location_recorded_at
		FROM samples
		WHERE id = $1
	`
	err := s.db.Pool.QueryRow(ctx, query, sampleID).Scan(
		&lc.Status, &lc.Sealed, &holderID, &activeJourney, &recLab, &excJSON, &lat, &lng, &recAt,
	)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, errors.New("sample_not_found")
		}
		return nil, err
	}

	if holderID != nil {
		lc.CurrentHolderId = *holderID
	}
	if activeJourney != nil {
		lc.ActiveJourneyId = *activeJourney
	}
	if recLab != nil {
		lc.ReceivedLaboratoryId = *recLab
	}
	if len(excJSON) > 0 {
		_ = json.Unmarshal(excJSON, &lc.Exception)
	}

	lc.LocationStale = true
	if lat != nil && lng != nil && recAt != nil {
		lc.LatestLocation = &models.Coordinate{Latitude: *lat, Longitude: *lng}
		lc.LocationRecordedAt = recAt
		if time.Since(*recAt) < 15*time.Minute {
			lc.LocationStale = false
		}
	}

	// Completed legs
	lc.CompletedLegIds = make([]string, 0)
	legRows, _ := s.db.Pool.Query(ctx, `
		SELECT id FROM assignments WHERE sample_id = $1 AND status = 'completed'
	`, sampleID)
	if legRows != nil {
		for legRows.Next() {
			var lid string
			_ = legRows.Scan(&lid)
			lc.CompletedLegIds = append(lc.CompletedLegIds, lid)
		}
		legRows.Close()
	}

	lc.ActiveReplacementPlanIds = make([]string, 0)

	// Check pending handoff
	var pHandID string
	var sID, rID string
	err = s.db.Pool.QueryRow(ctx, `
		SELECT id, sender_id, receiver_id FROM handoffs WHERE sample_id = $1 AND status = 'pending' LIMIT 1
	`, sampleID).Scan(&pHandID, &sID, &rID)
	if err == nil {
		lc.PendingHandoffId = pHandID
		lc.PendingHandoff = map[string]interface{}{
			"handoffId":  pHandID,
			"senderId":   sID,
			"receiverId": rID,
		}
	}

	// Timeline
	lc.Timeline = s.getSampleTimeline(ctx, sampleID)

	return &lc, nil
}

func (s *SampleService) GetSampleState(ctx context.Context, sampleID string) (*models.SampleState, error) {
	var ss models.SampleState
	ss.SampleId = sampleID

	var incompJSON []byte
	var actJourney, targetLab *string
	var lat, lng *float64
	var recAt *time.Time

	query := `
		SELECT s.request_id, s.requester_id, r.origin_lat, r.origin_lng, r.origin_type, r.requested_at, r.delivery_deadline,
		       s.sample_type_id, r.container_type, r.temperature_min_c, r.temperature_max_c, r.incompatible_sample_types,
		       r.serviceability, s.status, s.active_journey_id, s.target_laboratory_id, s.latest_lat, s.latest_lng, s.location_recorded_at
		FROM samples s
		JOIN requests r ON s.request_id = r.id
		WHERE s.id = $1
	`
	err := s.db.Pool.QueryRow(ctx, query, sampleID).Scan(
		&ss.RequestId, &ss.RequesterId, &ss.Origin.Latitude, &ss.Origin.Longitude, &ss.OriginType, &ss.RequestedAt, &ss.DeliveryDeadline,
		&ss.SampleTypeId, &ss.ContainerType, &ss.TemperatureMinC, &ss.TemperatureMaxC, &incompJSON,
		&ss.Serviceability, &ss.State.Status, &actJourney, &targetLab, &lat, &lng, &recAt,
	)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, errors.New("sample_not_found")
		}
		return nil, err
	}

	if actJourney != nil {
		ss.ActiveJourneyId = *actJourney
	}
	if targetLab != nil {
		ss.TargetLaboratoryId = *targetLab
	}
	ss.IncompatibleSampleTypes = parseStringList(incompJSON)

	ss.LocationStale = true
	if lat != nil && lng != nil && recAt != nil {
		ss.LatestLocation = &models.Coordinate{Latitude: *lat, Longitude: *lng}
		ss.LocationRecordedAt = recAt
		if time.Since(*recAt) < 15*time.Minute {
			ss.LocationStale = false
		}
	}

	// Active assignment IDs
	ss.ActiveAssignmentIds = make([]string, 0)
	aRows, _ := s.db.Pool.Query(ctx, `
		SELECT id FROM assignments WHERE sample_id = $1 AND status IN ('offered', 'accepted', 'in_transit', 'in_progress', 'at_pickup', 'picked_up', 'arrived')
	`, sampleID)
	if aRows != nil {
		for aRows.Next() {
			var aid string
			_ = aRows.Scan(&aid)
			ss.ActiveAssignmentIds = append(ss.ActiveAssignmentIds, aid)
		}
		aRows.Close()
	}

	ss.Timeline = s.getSampleTimeline(ctx, sampleID)

	return &ss, nil
}

func (s *SampleService) getSampleTimeline(ctx context.Context, sampleID string) []models.TimelineEntry {
	entries := make([]models.TimelineEntry, 0)
	rows, err := s.db.Pool.Query(ctx, `
		SELECT id, action, actor_id, role, entity_type, entity_id, success, occurred_at, details
		FROM audit_entries
		WHERE entity_id = $1 OR (details->>'sampleId') = $1
		ORDER BY occurred_at ASC, id ASC
	`, sampleID)
	if err != nil {
		return entries
	}
	defer rows.Close()

	for rows.Next() {
		var e models.TimelineEntry
		var detJSON []byte
		if err := rows.Scan(&e.EventId, &e.Action, &e.ActorId, &e.Role, &e.EntityType, &e.EntityId, &e.Success, &e.OccurredAt, &detJSON); err == nil {
			e.Details = make(map[string]interface{})
			_ = json.Unmarshal(detJSON, &e.Details)
			entries = append(entries, e)
		}
	}

	return entries
}

