	query := "SELECT id, name, latitude, longitude, coverage_km, handling_minutes, active, functions FROM locations WHERE 1=1"
	var args []interface{}
	argIdx := 1

	if activeQuery != "" {
		activeBool := activeQuery == "true"
		query += fmt.Sprintf(" AND active = $%d", argIdx)
		args = append(args, activeBool)
		argIdx++
	}

	rows, err := h.db.Pool.Query(r.Context(), query, args...)
	if err != nil {
		respondError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	defer rows.Close()

	var locs []models.Location
	for rows.Next() {
		var loc models.Location
		var funcBytes []byte
		if err := rows.Scan(&loc.LocationId, &loc.Name, &loc.Coordinate.Latitude, &loc.Coordinate.Longitude, &loc.CoverageKm, &loc.HandlingMinutes, &loc.Active, &funcBytes); err == nil {
			_ = json.Unmarshal(funcBytes, &loc.Functions)
			if fnQuery != "" {
				switch fnQuery {
				case "collection_point":
					if !loc.Functions.CollectionPoint {
						continue
					}
				case "transfer_point":
					if !loc.Functions.TransferPoint {
						continue
					}
				case "hub":
					if !loc.Functions.Hub {
						continue
					}
				case "laboratory":
					if !loc.Functions.Laboratory {
						continue
					}
