			w.WriteHeader(status)
			_, _ = w.Write(respBody)
			return
		}
	}

	plan, err := h.journeySvc.MergeJourneys(r.Context(), u.ID, u.ActiveRole, req.TargetJourneyId, req.ExpectedPlanVersion, req.SourceJourneyIds)
	if err != nil {
		if err.Error() == "state_snapshot_changed" {
			respondError(w, http.StatusConflict, "state_snapshot_changed", "Plan version conflict")
			return
		}
		respondError(w, http.StatusBadRequest, "invalid_data", err.Error())
		return
	}

	h.saveIdempotency(r.Context(), "merge_journeys", req.IdempotencyKey, bodyBytes, http.StatusOK, plan)
	respondJSON(w, http.StatusOK, plan)
}

// Split Journey
func (h *APIHandler) SplitJourney(w http.ResponseWriter, r *http.Request) {
	u := auth.GetUser(r.Context())
	if u == nil {
		respondError(w, http.StatusUnauthorized, "unauthorized", "Authentication required")
		return
	}

	bodyBytes, err := io.ReadAll(r.Body)
	if err != nil {
		respondError(w, http.StatusBadRequest, "invalid_body", "Failed to read body")
		return
	}

	var req struct {
		JourneyId           string   `json:"journeyId"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		SampleIds           []string `json:"sampleIds"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	if err := json.Unmarshal(bodyBytes, &req); err != nil {
		respondError(w, http.StatusBadRequest, "invalid_json", "Invalid request body")
		return
	}

	if req.IdempotencyKey != "" {
		if status, respBody, ok := h.checkIdempotency(r.Context(), "split_journey", req.IdempotencyKey, bodyBytes); ok {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(status)
			_, _ = w.Write(respBody)
			return
		}
	}

	plan, err := h.journeySvc.SplitJourney(r.Context(), u.ID, u.ActiveRole, req.JourneyId, req.ExpectedPlanVersion, req.SampleIds)
	if err != nil {
		if err.Error() == "state_snapshot_changed" {
			respondError(w, http.StatusConflict, "state_snapshot_changed", "Plan version conflict")
			return
		}
		respondError(w, http.StatusBadRequest, "invalid_data", err.Error())
		return
	}

	h.saveIdempotency(r.Context(), "split_journey", req.IdempotencyKey, bodyBytes, http.StatusOK, plan)
	respondJSON(w, http.StatusOK, plan)
}

// Report Disruption
func (h *APIHandler) ReportDisruption(w http.ResponseWriter, r *http.Request) {
	u := auth.GetUser(r.Context())
	if u == nil {
		respondError(w, http.StatusUnauthorized, "unauthorized", "Authentication required")
		return
	}

	bodyBytes, err := io.ReadAll(r.Body)
	if err != nil {
		respondError(w, http.StatusBadRequest, "invalid_body", "Failed to read body")
		return
	}

	var req struct {
		ResourceType   string    `json:"resourceType"`
		ResourceId     string    `json:"resourceId"`
		Reason         string    `json:"reason"`
		OccurredAt     time.Time `json:"occurredAt"`
		IdempotencyKey string    `json:"idempotencyKey"`
	}
	if err := json.Unmarshal(bodyBytes, &req); err != nil {
		respondError(w, http.StatusBadRequest, "invalid_json", "Invalid request body")
		return
	}

	if req.IdempotencyKey != "" {
		if status, respBody, ok := h.checkIdempotency(r.Context(), "report_disruption", req.IdempotencyKey, bodyBytes); ok {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(status)
			_, _ = w.Write(respBody)
			return
		}
	}

	err = h.journeySvc.ReportDisruption(r.Context(), u.ID, u.ActiveRole, req.ResourceType, req.ResourceId, req.Reason, req.OccurredAt)
	if err != nil {
		respondError(w, http.StatusBadRequest, "invalid_data", err.Error())
		return
	}

	respData := map[string]interface{}{
		"resourceType":       req.ResourceType,
		"resourceId":         req.ResourceId,
		"disruptionReported": true,
	}
	h.saveIdempotency(r.Context(), "report_disruption", req.IdempotencyKey, bodyBytes, http.StatusOK, respData)
	respondJSON(w, http.StatusOK, respData)
}

// List Role Work
func (h *APIHandler) ListRoleWork(w http.ResponseWriter, r *http.Request) {
	u := auth.GetUser(r.Context())
	if u == nil {
		respondError(w, http.StatusUnauthorized, "unauthorized", "Authentication required")
		return
	}

	var req struct {
		Role   string `json:"role"`
		Status string `json:"status"`
	}
	_ = json.NewDecoder(r.Body).Decode(&req)

	targetRole := u.ActiveRole
	if req.Role != "" {
		targetRole = req.Role
	}

	work, err := h.journeySvc.ListRoleWork(r.Context(), u.ID, targetRole, req.Status)
	if err != nil {
		respondError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}

	respondJSON(w, http.StatusOK, work)
}

// Read Operations State
func (h *APIHandler) ReadOperationsState(w http.ResponseWriter, r *http.Request) {
	u := auth.GetUser(r.Context())
	if u == nil {
		respondError(w, http.StatusUnauthorized, "unauthorized", "Authentication required")
		return
	}

	var req struct {
		Filters struct {
			SampleTypeId      string `json:"sampleTypeId"`
			SampleTypeIdSnake string `json:"sample_type_id"`
		} `json:"filters"`
	}
	_ = json.NewDecoder(r.Body).Decode(&req)

	stID := req.Filters.SampleTypeId
	if stID == "" {
		stID = req.Filters.SampleTypeIdSnake
	}

	opState, err := h.opSvc.GetOperationsState(r.Context(), services.OperationsFilter{
		SampleTypeId: stID,
	})
	if err != nil {
		respondError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}

	respondJSON(w, http.StatusOK, opState)
}

// Search Audit Trail
func (h *APIHandler) SearchAuditTrail(w http.ResponseWriter, r *http.Request) {
	u := auth.GetUser(r.Context())
	if u == nil {
		respondError(w, http.StatusUnauthorized, "unauthorized", "Authentication required")
		return
	}

	var req services.AuditFilter
	_ = json.NewDecoder(r.Body).Decode(&req)

	results, err := h.auditSvc.Search(r.Context(), req)
	if err != nil {
		respondError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}

	respondJSON(w, http.StatusOK, results)
}

// Realtime Events SSE
func (h *APIHandler) EventsSSE(w http.ResponseWriter, r *http.Request) {
	flusher, ok := w.(http.Flusher)
	if !ok {
		http.Error(w, "Streaming unsupported", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "text/event-stream")
	w.Header().Set("Cache-Control", "no-cache")
	w.Header().Set("Connection", "keep-alive")
	w.Header().Set("Access-Control-Allow-Origin", "*")

	ch, unsubscribe := h.eventSvc.Subscribe()
	defer unsubscribe()

	notify := r.Context().Done()
	for {
		select {
		case <-notify:
			return
		case event, ok := <-ch:
			if !ok {
				return
			}
			eventBytes, err := json.Marshal(event)
			if err == nil {
				_, _ = fmt.Fprintf(w, "event: %s\ndata: %s\n\n", event.Type, string(eventBytes))
				flusher.Flush()
			}
		}
	}
}

