	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		respondError(w, http.StatusBadRequest, "invalid_json", "Invalid request body")
		return
	}

	cap, err := h.locationSvc.ConfigureCapacity(r.Context(), u.ID, u.ActiveRole, req.ResourceId, req.CapacityUnits, req.CooledCapacityUnits)
