	authService *auth.AuthService
	auditSvc    *services.AuditService
	eventSvc    *services.EventService
	userSvc     *services.UserService
	locationSvc *services.LocationService
	sampleSvc   *services.SampleService
	journeySvc  *services.JourneyService
	opSvc       *services.OperationsService
	rEngine     *routing.ServiceabilityEngine
	fairness    *services.FairnessEngine
}

func NewAPIHandler(
	database *db.DB,
	authSvc *auth.AuthService,
	auditSvc *services.AuditService,
	eventSvc *services.EventService,
	userSvc *services.UserService,
	locSvc *services.LocationService,
	sampleSvc *services.SampleService,
	journeySvc *services.JourneyService,
	opSvc *services.OperationsService,
	rEngine *routing.ServiceabilityEngine,
	fairness *services.FairnessEngine,
) *APIHandler {
	return &APIHandler{
		db:          database,
		authService: authSvc,
		auditSvc:    auditSvc,
		eventSvc:    eventSvc,
		userSvc:     userSvc,
		locationSvc: locSvc,
		sampleSvc:   sampleSvc,
		journeySvc:  journeySvc,
		opSvc:       opSvc,
		rEngine:     rEngine,
		fairness:    fairness,
	}
}

func respondJSON(w http.ResponseWriter, status int, data interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(map[string]interface{}{
		"data": data,
	})
}

func respondError(w http.ResponseWriter, status int, code, errMessage string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(models.ErrorEnvelope{
		Error: errMessage,
		Code:  code,
	})
}

func (h *APIHandler) checkIdempotency(ctx context.Context, op, key string, bodyBytes []byte) (int, []byte, bool) {
	if key == "" {
		return 0, nil, false
	}
	hash := sha256.Sum256(bodyBytes)
	hashStr := hex.EncodeToString(hash[:])

	var status int
	var respJSON []byte
	err := h.db.Pool.QueryRow(ctx, "SELECT response_status, response_body FROM idempotency_keys WHERE key = $1 AND operation = $2", key, op).Scan(&status, &respJSON)
	if err == nil {
		return status, respJSON, true
	}
	_ = hashStr
	return 0, nil, false
}

func (h *APIHandler) saveIdempotency(ctx context.Context, op, key string, bodyBytes []byte, status int, respData interface{}) {
	if key == "" {
		return
	}
	hash := sha256.Sum256(bodyBytes)
	hashStr := hex.EncodeToString(hash[:])
	respBytes, _ := json.Marshal(map[string]interface{}{"data": respData})

	_, _ = h.db.Pool.Exec(ctx, `
		INSERT INTO idempotency_keys (key, operation, request_hash, response_status, response_body)
		VALUES ($1, $2, $3, $4, $5::jsonb)
		ON CONFLICT (key) DO NOTHING
	`, key, op, hashStr, status, respBytes)
}

func (h *APIHandler) ReadyHandler(w http.ResponseWriter, r *http.Request) {
	if err := h.db.Pool.Ping(r.Context()); err != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusServiceUnavailable)
		_ = json.NewEncoder(w).Encode(map[string]string{"status": "database_error"})
		return
	}

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	_ = json.NewEncoder(w).Encode(map[string]string{"status": "ready"})
}

// Authenticate User
func (h *APIHandler) AuthenticateUser(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		respondError(w, http.StatusBadRequest, "invalid_json", "Invalid request body")
		return
	}

	user, token, err := h.authService.Authenticate(r.Context(), req.Username, req.Password)
	if err != nil {
		if err.Error() == "invalid_credentials" {
			respondError(w, http.StatusUnauthorized, "invalid_credentials", "Invalid username or password")
			return
		}
		respondError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}

	_, _ = h.auditSvc.Log(r.Context(), user.ID, user.ActiveRole, "authenticate_user", "session", token, true, map[string]interface{}{
		"username": user.Username,
	})

	respondJSON(w, http.StatusOK, map[string]interface{}{
		"sessionToken": token,
		"userId":       user.ID,
		"roles":        user.Roles,
		"activeRole":   user.ActiveRole,
	})
}

// Select Active Role
func (h *APIHandler) SelectActiveRole(w http.ResponseWriter, r *http.Request) {
