// Get Connection
func (h *APIHandler) GetConnection(w http.ResponseWriter, r *http.Request) {
	connID := strings.TrimPrefix(r.URL.Path, "/api/get-connection/")
	if connID == "" {
		respondError(w, http.StatusBadRequest, "invalid_connection_id", "Missing connectionId")
		return
	}

	var conn models.OperationsConnection
	conn.ID = connID
	conn.ConnectionId = connID
	conn.Capacity = &models.Capacity{}

	err := h.db.Pool.QueryRow(r.Context(), `
		SELECT from_location_id, to_location_id, travel_minutes, cost_units, cooled, active, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
		FROM connections WHERE id = $1
	`, connID).Scan(
		&conn.FromLocationId, &conn.ToLocationId, &conn.TravelMinutes, &conn.CostUnits, &conn.Cooled, &conn.Active,
		&conn.Capacity.CapacityUnits, &conn.Capacity.ReservedUnits, &conn.Capacity.CooledCapacityUnits, &conn.Capacity.CooledReservedUnits,
	)
	if err != nil {
		respondError(w, http.StatusNotFound, "connection_not_found", "Connection not found")
		return
	}
	conn.Capacity.AvailableUnits = conn.Capacity.CapacityUnits - conn.Capacity.ReservedUnits
	conn.Capacity.CooledAvailableUnits = conn.Capacity.CooledCapacityUnits - conn.Capacity.CooledReservedUnits

	respondJSON(w, http.StatusOK, conn)
}

// List Connections
func (h *APIHandler) ListConnections(w http.ResponseWriter, r *http.Request) {
	activeQuery := r.URL.Query().Get("active")

	query := "SELECT id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units FROM connections WHERE 1=1"
	var args []interface{}
	if activeQuery != "" {
		activeBool := activeQuery == "true"
		query += " AND active = $1"
		args = append(args, activeBool)
	}

	rows, err := h.db.Pool.Query(r.Context(), query, args...)
	if err != nil {
		respondError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}
	defer rows.Close()

	var conns []models.OperationsConnection
	for rows.Next() {
		var conn models.OperationsConnection
		conn.Capacity = &models.Capacity{}
		if err := rows.Scan(
			&conn.ID, &conn.FromLocationId, &conn.ToLocationId, &conn.TravelMinutes, &conn.CostUnits, &conn.Cooled, &conn.Active,
			&conn.Capacity.CapacityUnits, &conn.Capacity.ReservedUnits, &conn.Capacity.CooledCapacityUnits, &conn.Capacity.CooledReservedUnits,
		); err == nil {
			conn.ConnectionId = conn.ID
			conn.Capacity.AvailableUnits = conn.Capacity.CapacityUnits - conn.Capacity.ReservedUnits
			conn.Capacity.CooledAvailableUnits = conn.Capacity.CooledCapacityUnits - conn.Capacity.CooledReservedUnits
			conns = append(conns, conn)
		}
	}

	respondJSON(w, http.StatusOK, conns)
}

