		return
	}

	if req.IdempotencyKey != "" {
		if status, respBody, ok := h.checkIdempotency(r.Context(), "cancel_journey", req.IdempotencyKey, bodyBytes); ok {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(status)
			_, _ = w.Write(respBody)
			return
		}
	}

	plan, err := h.journeySvc.CancelJourney(r.Context(), u.ID, u.ActiveRole, req.JourneyId, req.ExpectedPlanVersion, req.Reason)
	if err != nil {
		if err.Error() == "state_snapshot_changed" {
