			return
		}
		respondError(w, http.StatusBadRequest, "invalid_data", err.Error())
		return
	}

	h.saveIdempotency(r.Context(), "cancel_journey", req.IdempotencyKey, bodyBytes, http.StatusOK, plan)
	respondJSON(w, http.StatusOK, plan)
}

