	_ = json.NewDecoder(r.Body).Decode(&req)

	results, err := h.auditSvc.Search(r.Context(), req)
	if err != nil {
		respondError(w, http.StatusInternalServerError, "internal_error", err.Error())
		return
	}

	respondJSON(w, http.StatusOK, results)
}

// Realtime Events SSE
func (h *APIHandler) EventsSSE(w http.ResponseWriter, r *http.Request) {
	flusher, ok := w.(http.Flusher)
	if !ok {
		http.Error(w, "Streaming unsupported", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "text/event-stream")
	w.Header().Set("Cache-Control", "no-cache")
	w.Header().Set("Connection", "keep-alive")
	w.Header().Set("Access-Control-Allow-Origin", "*")

	ch, unsubscribe := h.eventSvc.Subscribe()
	defer unsubscribe()

	notify := r.Context().Done()
	for {
		select {
		case <-notify:
			return
		case event, ok := <-ch:
			if !ok {
				return
			}
			eventBytes, err := json.Marshal(event)
			if err == nil {
				_, _ = fmt.Fprintf(w, "event: %s\ndata: %s\n\n", event.Type, string(eventBytes))
				flusher.Flush()
			}
		}
	}
}

// Read Sample State
func (h *APIHandler) ReadSampleState(w http.ResponseWriter, r *http.Request) {
	u := auth.GetUser(r.Context())
	if u == nil {
		respondError(w, http.StatusUnauthorized, "unauthorized", "Authentication required")
		return
	}

	vars := mux.Vars(r)
	sampleID := vars["sampleId"]
	if sampleID == "" {
		sampleID = strings.TrimPrefix(r.URL.Path, "/api/read-sample-state/")
	}

	state, err := h.sampleSvc.GetSampleState(r.Context(), sampleID)
	if err != nil {
		respondError(w, http.StatusNotFound, "not_found", "Sample not found")
		return
	}

	if u.ActiveRole == "requester" && state.RequesterId != u.ID {
		respondError(w, http.StatusForbidden, "forbidden", "Access denied to sample")
		return
	}

	respondJSON(w, http.StatusOK, state)
}

// Read UI Bootstrap
func (h *APIHandler) ReadUIBootstrap(w http.ResponseWriter, r *http.Request) {
	u := auth.GetUser(r.Context())
	if u == nil {
		respondError(w, http.StatusUnauthorized, "unauthorized", "Authentication required")
		return
	}

	user, err := h.userSvc.GetUser(r.Context(), u.ID)
	if err != nil {
		respondError(w, http.StatusNotFound, "not_found", "User not found")
		return
	}

	activeRole := u.ActiveRole
	if activeRole == "" && len(user.Roles) > 0 {
		activeRole = user.Roles[0]
	}

	userData := map[string]interface{}{
		"userId":                user.UserId,
		"username":              user.Username,
		"roles":                 user.Roles,
		"activeRole":            activeRole,
		"roleSelectionRequired": len(user.Roles) > 1 && u.ActiveRole == "",
	}
	if user.FullName != "" {
		userData["fullName"] = user.FullName
	}

	respData := map[string]interface{}{
		"user":       userData,
		"serverTime": time.Now().UTC().Format(time.RFC3339),
	}

	if activeRole == "requester" {
		work, err := h.journeySvc.ListRoleWork(r.Context(), u.ID, activeRole)
		var requesterSamples []interface{}
		if err == nil && work != nil {
			requesterSamples = append(requesterSamples, work.Pending...)
			requesterSamples = append(requesterSamples, work.InProgress...)
			requesterSamples = append(requesterSamples, work.Completed...)
		}
		if requesterSamples == nil {
			requesterSamples = []interface{}{}
		}
		respData["requesterSamples"] = requesterSamples
	}

	if activeRole == "dispatcher" || activeRole == "administrator" {
		opState, err := h.opSvc.GetOperationsState(r.Context(), services.OperationsFilter{})
		if err == nil && opState != nil {
			respData["operations"] = opState
		}
	}

	respondJSON(w, http.StatusOK, respData)
}

