import React from 'react';
import { SampleStatusHistory } from '../types';

interface StatusTimelineProps {
  history?: SampleStatusHistory[];
}

export const StatusTimeline: React.FC<StatusTimelineProps> = ({ history = [] }) => {
  if (!history || history.length === 0) {
    return <p className="text-muted" style={{ fontStyle: 'italic', fontSize: '0.85rem' }}>No status history recorded yet.</p>;
  }

  // Ensure chronological order
  const sorted = [...history].sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime());

  return (
    <div className="timeline" role="region" aria-label="Status Timeline">
      {sorted.map((item, index) => (
        <div key={item.id || index} className="timeline-item">
          <div className="timeline-marker" />
          <div className="timeline-header">
            <span style={{ textTransform: 'capitalize', fontWeight: 600 }}>
              {item.toStatus || item.status}
            </span>
            <span className="timeline-time">
              {new Date(item.timestamp).toLocaleString()}
            </span>
          </div>
          <div className="timeline-body">
            {item.actorRole && (
              <div>
                <strong>Role:</strong> <span style={{ textTransform: 'capitalize' }}>{item.actorRole.replace(/_/g, ' ')}</span>
              </div>
            )}
            {item.notes && <div>{item.notes}</div>}
          </div>
        </div>
      ))}
    </div>
  );
};

