  // Form states for Create Request
  const [originType, setOriginType] = useState('home');
  const [originAddress, setOriginAddress] = useState('123 MG Road, Indiranagar, Bangalore');
  const [originLat, setOriginLat] = useState('12.9716');
  const [originLng, setOriginLng] = useState('77.5946');
  const [sampleTypeCode, setSampleTypeCode] = useState(sampleTypes[0]?.code || 'AMBER');
  const [windowStart, setWindowStart] = useState(() => new Date(Date.now() + 15 * 60 * 1000).toISOString().slice(0, 16));
  const [windowEnd, setWindowEnd] = useState(() => new Date(Date.now() + 120 * 60 * 1000).toISOString().slice(0, 16));
  const [deadline, setDeadline] = useState(() => new Date(Date.now() + 240 * 60 * 1000).toISOString().slice(0, 16));
  const [patientNotes, setPatientNotes] = useState('');
  const [formError, setFormError] = useState<string | null>(null);
  const [formSuccess, setFormSuccess] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  // Serviceability Dry Run state
  const [checkLat, setCheckLat] = useState('12.9716');
  const [checkLng, setCheckLng] = useState('77.5946');
  const [checkAddress, setCheckAddress] = useState('123 MG Road, Bangalore');
  const [checkType, setCheckType] = useState(sampleTypes[0]?.code || 'AMBER');
  const [checkWindowStart, setCheckWindowStart] = useState(() => new Date(Date.now() + 15 * 60 * 1000).toISOString().slice(0, 16));
  const [checkWindowEnd, setCheckWindowEnd] = useState(() => new Date(Date.now() + 120 * 60 * 1000).toISOString().slice(0, 16));
  const [checkDeadline, setCheckDeadline] = useState(() => new Date(Date.now() + 240 * 60 * 1000).toISOString().slice(0, 16));
  const [checkResult, setCheckResult] = useState<ServiceabilityResult | null>(null);
  const [checking, setChecking] = useState(false);
  const [checkError, setCheckError] = useState<string | null>(null);

  const fetchMySamples = async () => {
    setLoading(true);
    try {
      const res = await api.listWork();
      // listWork returns { pending: [], inProgress: [], completed: [] }
      const all: Sample[] = [];
      if (res.pending) all.push(...res.pending);
      if (res.inProgress) all.push(...res.inProgress);
      if (res.completed) all.push(...res.completed);
      setSamples(all);
    } catch (err: any) {
      console.error('Failed to fetch requests', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchMySamples();
  }, []);

  const handleCreateSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setFormError(null);
    setFormSuccess(null);
    setSubmitting(true);

    const lat = parseFloat(originLat);
    const lng = parseFloat(originLng);
    if (isNaN(lat) || isNaN(lng)) {
      setFormError('Invalid latitude or longitude coordinates');
      setSubmitting(false);
      return;
    }

    try {
      const res = await api.createRequest({
        originType,
        originLatitude: lat,
        originLongitude: lng,
        originAddress,
        sampleTypeCode,
        collectionWindowStart: new Date(windowStart).toISOString(),
        collectionWindowEnd: new Date(windowEnd).toISOString(),
        deliveryDeadline: new Date(deadline).toISOString(),
        patientNotes,
      });

      setFormSuccess(`Collection request created successfully! Tracking Number: ${res.sample?.trackingNumber || res.request?.id}`);
      fetchMySamples();
      setTimeout(() => {
        setActiveTab('requests');
      }, 1500);
    } catch (err: any) {
      setFormError(err.message || 'Failed to create collection request');
    } finally {
      setSubmitting(false);
    }
  };

  const handleServiceabilityCheck = async (e: React.FormEvent) => {
    e.preventDefault();
    setCheckError(null);
    setCheckResult(null);
    setChecking(true);

    const lat = parseFloat(checkLat);
    const lng = parseFloat(checkLng);
    if (isNaN(lat) || isNaN(lng)) {
      setCheckError('Invalid coordinates');
      setChecking(false);
      return;
    }

    try {
      const res = await api.checkServiceability({
        originLatitude: lat,
        originLongitude: lng,
        originAddress: checkAddress,
        sampleTypeCode: checkType,
        collectionWindowStart: new Date(checkWindowStart).toISOString(),
        collectionWindowEnd: new Date(checkWindowEnd).toISOString(),
        deliveryDeadline: new Date(checkDeadline).toISOString(),
      });
      setCheckResult(res);
    } catch (err: any) {
      setCheckError(err.message || 'Serviceability check failed');
    } finally {
      setChecking(false);
    }
  };

  return (
    <div role="region" aria-label="Requester Portal">
      <div className="tabs-nav" role="tablist">
        <button
          className={`tab-btn ${activeTab === 'requests' ? 'active' : ''}`}
          onClick={() => setActiveTab('requests')}
          role="tab"
          aria-selected={activeTab === 'requests'}
          aria-label="My Requests Tab"
        >
          My Requests & Samples ({samples.length})
        </button>
        <button
          className={`tab-btn ${activeTab === 'create' ? 'active' : ''}`}
          onClick={() => setActiveTab('create')}
          role="tab"
          aria-selected={activeTab === 'create'}
          aria-label="Create Request Tab"
        >
          + Create Collection Request
        </button>
        <button
          className={`tab-btn ${activeTab === 'check' ? 'active' : ''}`}
          onClick={() => setActiveTab('check')}
          role="tab"
          aria-selected={activeTab === 'check'}
          aria-label="Serviceability Check Tab"
        >
          🔍 Check Serviceability (Dry Run)
        </button>
      </div>

      {activeTab === 'requests' && (
        <div className="card">
          <div className="card-header">
            <h2 className="card-title">My Sample Requests</h2>
            <button className="btn btn-secondary btn-sm" onClick={fetchMySamples} aria-label="Refresh requests">
              Refresh
            </button>
          </div>

          {loading ? (
            <p>Loading your requests...</p>
          ) : samples.length === 0 ? (
            <p className="text-muted" style={{ padding: '1rem', fontStyle: 'italic' }}>
              No collection requests found. Click "+ Create Collection Request" to start.
            </p>
          ) : (
            <div className="table-container">
              <table className="data-table" aria-label="Requester Samples Table">
                <thead>
                  <tr>
                    <th>Tracking #</th>
                    <th>Sample Type</th>
                    <th>Status</th>
                    <th>Current Holder</th>
                    <th>Location & Freshness</th>
                    <th>Delivery Deadline</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {samples.map((s) => (
                    <tr key={s.id}>
                      <td>
                        <strong>{s.trackingNumber}</strong>
                        {s.isException && (
                          <span className="badge badge-exception" style={{ marginLeft: '0.5rem' }}>
                            ⚠️ Exception
                          </span>
                        )}
                      </td>
                      <td>{s.sampleTypeCode}</td>
                      <td>
                        <span className={`badge badge-${s.status}`}>{s.status}</span>
                      </td>
                      <td>{s.currentHolderName || 'Unassigned'}</td>
                      <td>
                        <div>
                          {s.currentLocationName || (s.currentLatitude ? `${s.currentLatitude.toFixed(3)}, ${s.currentLongitude?.toFixed(3)}` : 'N/A')}
                        </div>
                        {s.isLocationStale ? (
                          <span className="badge badge-stale" aria-label="Stale Location">⚠️ STALE</span>
                        ) : (
                          <span className="badge badge-received" style={{ fontSize: '0.7rem' }}>Fresh</span>
                        )}
                      </td>
                      <td>{new Date(s.deliveryDeadline).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', month: 'short', day: 'numeric' })}</td>
                      <td>
                        <button
                          className="btn btn-secondary btn-sm"
                          onClick={() => setSelectedSampleId(s.id)}
                          aria-label={`View details for sample ${s.trackingNumber}`}
                        >
                          View Details
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {activeTab === 'create' && (
        <div className="card">
          <div className="card-header">
            <h2 className="card-title">Create Collection Request</h2>
          </div>

          {formError && (
            <div className="alert alert-danger" role="alert" aria-live="assertive" aria-label="Validation Error">
              <span>{formError}</span>
            </div>
          )}

          {formSuccess && (
            <div className="alert alert-success" role="alert" aria-live="polite">
              <span>{formSuccess}</span>
            </div>
          )}

          <form onSubmit={handleCreateSubmit} aria-label="Create Collection Request Form">
            <div className="form-row">
              <div className="form-group">
                <label htmlFor="originType">Origin Type</label>
                <select
                  id="originType"
                  className="form-select"
                  value={originType}
                  onChange={(e) => setOriginType(e.target.value)}
                  aria-label="Origin Type"
                >
                  <option value="home">Patient Home</option>
                  <option value="clinic">Clinic</option>
                </select>
              </div>

              <div className="form-group">
                <label htmlFor="sampleTypeCode">Sample Type</label>
                <select
                  id="sampleTypeCode"
                  className="form-select"
                  value={sampleTypeCode}
                  onChange={(e) => setSampleTypeCode(e.target.value)}
                  aria-label="Sample Type"
                >
                  {sampleTypes.map((st) => (
                    <option key={st.id || st.code} value={st.code}>
                      {st.name} ({st.code}) - {st.requiredContainer}
                    </option>
                  ))}
                </select>
              </div>
            </div>

            <div className="form-group">
              <label htmlFor="originAddress">Origin Address</label>
              <input
                id="originAddress"
                type="text"
                className="form-input"
                value={originAddress}
                onChange={(e) => setOriginAddress(e.target.value)}
                required
                placeholder="Full pickup address"
                aria-label="Origin Address"
              />
            </div>

            <div className="form-row">
              <div className="form-group">
                <label htmlFor="originLat">Latitude</label>
                <input
                  id="originLat"
                  type="text"
                  className="form-input"
                  value={originLat}
                  onChange={(e) => setOriginLat(e.target.value)}
                  required
                  placeholder="e.g. 12.9716"
                  aria-label="Origin Latitude"
                />
              </div>

              <div className="form-group">
                <label htmlFor="originLng">Longitude</label>
                <input
                  id="originLng"
                  type="text"
                  className="form-input"
                  value={originLng}
                  onChange={(e) => setOriginLng(e.target.value)}
                  required
                  placeholder="e.g. 77.5946"
                  aria-label="Origin Longitude"
                />
              </div>
            </div>

            <div className="form-row">
              <div className="form-group">
                <label htmlFor="windowStart">Collection Window Start</label>
                <input
                  id="windowStart"
                  type="datetime-local"
                  className="form-input"
                  value={windowStart}
                  onChange={(e) => setWindowStart(e.target.value)}
                  required
                  aria-label="Collection Window Start"
                />
              </div>

              <div className="form-group">
                <label htmlFor="windowEnd">Collection Window End</label>
                <input
                  id="windowEnd"
                  type="datetime-local"
                  className="form-input"
                  value={windowEnd}
                  onChange={(e) => setWindowEnd(e.target.value)}
                  required
                  aria-label="Collection Window End"
                />
              </div>

              <div className="form-group">
                <label htmlFor="deadline">Delivery Deadline</label>
                <input
                  id="deadline"
                  type="datetime-local"
                  className="form-input"
                  value={deadline}
                  onChange={(e) => setDeadline(e.target.value)}
                  required
                  aria-label="Delivery Deadline"
                />
              </div>
            </div>

            <div className="form-group">
              <label htmlFor="patientNotes">Notes / Special Instructions</label>
              <textarea
                id="patientNotes"
                className="form-textarea"
                rows={2}
                value={patientNotes}
                onChange={(e) => setPatientNotes(e.target.value)}
                placeholder="Optional notes for the collector..."
                aria-label="Patient Notes"
              />
            </div>

            <button
              type="submit"
              className="btn btn-primary"
              disabled={submitting}
              aria-label="Submit Collection Request"
            >
              {submitting ? 'Submitting...' : 'Submit Collection Request'}
            </button>
          </form>
        </div>
      )}

      {activeTab === 'check' && (
        <div className="card">
          <div className="card-header">
            <h2 className="card-title">Serviceability Check (Dry Run)</h2>
          </div>
          <p className="text-muted" style={{ marginBottom: '1rem', fontSize: '0.875rem' }}>
            Dry run check only: tests network coverage, capacity, laboratory compatibility, and timing without reserving capacity or creating any requests.
          </p>

          {checkError && (
            <div className="alert alert-danger" role="alert" aria-live="assertive">
              <span>{checkError}</span>
            </div>
          )}

          <form onSubmit={handleServiceabilityCheck} aria-label="Serviceability Check Form">
            <div className="form-row">
              <div className="form-group">
                <label htmlFor="checkLat">Latitude</label>
                <input
                  id="checkLat"
                  type="text"
                  className="form-input"
                  value={checkLat}
                  onChange={(e) => setCheckLat(e.target.value)}
                  required
                  aria-label="Check Latitude"
                />
              </div>

              <div className="form-group">
                <label htmlFor="checkLng">Longitude</label>
                <input
                  id="checkLng"
                  type="text"
                  className="form-input"
                  value={checkLng}
                  onChange={(e) => setCheckLng(e.target.value)}
                  required
                  aria-label="Check Longitude"
                />
              </div>

              <div className="form-group">
                <label htmlFor="checkType">Sample Type</label>
                <select
                  id="checkType"
                  className="form-select"
                  value={checkType}
                  onChange={(e) => setCheckType(e.target.value)}
                  aria-label="Check Sample Type"
                >
                  {sampleTypes.map((st) => (
                    <option key={st.id || st.code} value={st.code}>
                      {st.name} ({st.code})
                    </option>
                  ))}
                </select>
              </div>
            </div>

            <div className="form-row">
              <div className="form-group">
                <label htmlFor="checkWindowStart">Window Start</label>
                <input
                  id="checkWindowStart"
                  type="datetime-local"
                  className="form-input"
                  value={checkWindowStart}
                  onChange={(e) => setCheckWindowStart(e.target.value)}
                  required
                  aria-label="Check Window Start"
                />
              </div>

              <div className="form-group">
                <label htmlFor="checkWindowEnd">Window End</label>
                <input
                  id="checkWindowEnd"
                  type="datetime-local"
                  className="form-input"
                  value={checkWindowEnd}
                  onChange={(e) => setCheckWindowEnd(e.target.value)}
                  required
                  aria-label="Check Window End"
                />
              </div>

              <div className="form-group">
                <label htmlFor="checkDeadline">Delivery Deadline</label>
                <input
                  id="checkDeadline"
                  type="datetime-local"
                  className="form-input"
                  value={checkDeadline}
                  onChange={(e) => setCheckDeadline(e.target.value)}
                  required
                  aria-label="Check Delivery Deadline"
                />
              </div>
            </div>

            <button
              type="submit"
              className="btn btn-primary"
              disabled={checking}
              aria-label="Check Serviceability"
            >
              {checking ? 'Checking...' : 'Check Serviceability'}
            </button>
          </form>

          {checkResult && (
            <div
              style={{ marginTop: '1.5rem', padding: '1rem', borderRadius: '8px', border: '1px solid #e2e8f0', backgroundColor: '#f8fafc' }}
              aria-label="Serviceability Result"
            >
              <h3 style={{ fontSize: '1rem', fontWeight: 600, marginBottom: '0.5rem' }}>
                Serviceability Result: {checkResult.isServiceable ? (
                  <span className="badge badge-received" style={{ fontSize: '0.85rem' }}>SERVICEABLE</span>
                ) : (
                  <span className="badge badge-exception" style={{ fontSize: '0.85rem' }}>UNSERVICEABLE</span>
                )}
              </h3>

              <p style={{ fontSize: '0.85rem', color: '#475569' }}>
                <strong>Calculation Version:</strong> {checkResult.serviceabilityVersion || 'v1.0.0'}
              </p>

              {checkResult.nearestCollectionNode && (
                <p style={{ fontSize: '0.85rem', color: '#475569' }}>
                  <strong>Nearest Collection Node:</strong> {checkResult.nearestCollectionNode.name} ({checkResult.nearestCollectionNode.code})
                </p>
              )}

              {checkResult.destinationLab && (
                <p style={{ fontSize: '0.85rem', color: '#475569' }}>
                  <strong>Destination Laboratory:</strong> {checkResult.destinationLab.name}
                </p>
              )}

              {checkResult.estimatedTransitMinutes !== undefined && (
                <p style={{ fontSize: '0.85rem', color: '#475569' }}>
                  <strong>Estimated Transit Time:</strong> {checkResult.estimatedTransitMinutes} minutes
                </p>
              )}

              {checkResult.reasons && checkResult.reasons.length > 0 && (
                <div style={{ marginTop: '0.5rem' }}>
                  <strong style={{ fontSize: '0.85rem', color: '#dc2626' }}>Reasons:</strong>
                  <ul style={{ paddingLeft: '1.25rem', fontSize: '0.85rem', color: '#dc2626' }}>
                    {checkResult.reasons.map((r, i) => (
                      <li key={i}>{r}</li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
          )}
        </div>
      )}

      {selectedSampleId && (
        <SampleDetailModal sampleId={selectedSampleId} onClose={() => setSelectedSampleId(null)} />
      )}
    </div>
  );
};

