import React, { useState, useEffect } from 'react';
import { api } from '../api';
import { SampleDetailModal } from './SampleDetailModal';

export const CollectorView: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'current' | 'past' | 'location'>('current');
  const [work, setWork] = useState<{ pending: any[]; inProgress: any[]; completed: any[] }>({
    pending: [],
    inProgress: [],
    completed: [],
  });
  const [loading, setLoading] = useState(true);
  const [actionError, setActionError] = useState<string | null>(null);
  const [actionSuccess, setActionSuccess] = useState<string | null>(null);
  const [selectedSampleId, setSelectedSampleId] = useState<string | null>(null);

  // Location form
  const [lat, setLat] = useState('12.9716');
  const [lng, setLng] = useState('77.5946');
  const [locSuccess, setLocSuccess] = useState<string | null>(null);

  // Collection & Seal modal/form state
  const [collectingLeg, setCollectingLeg] = useState<any | null>(null);
  const [sealNumber, setSealNumber] = useState('');
  const [container, setContainer] = useState('standard_tube');
  const [temp, setTemp] = useState('4.0');

  // Handoff state
  const [handoffLeg, setHandoffLeg] = useState<any | null>(null);
  const [handoffType, setHandoffType] = useState('worker_to_node');
  const [targetId, setTargetId] = useState('');

  // Checkpoint state
  const [checkpointSampleId, setCheckpointSampleId] = useState<string | null>(null);
  const [checkpointContainer, setCheckpointContainer] = useState('standard_tube');
  const [checkpointTemp, setCheckpointTemp] = useState('4.0');

  const fetchWork = async () => {
    setLoading(true);
    try {
      const res = await api.listWork();
      setWork({
        pending: res.pending || [],
        inProgress: res.inProgress || [],
        completed: res.completed || [],
      });
    } catch (err: any) {
      console.error('Failed to load collector work', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchWork();
  }, []);

  const handleAccept = async (legId: string) => {
    setActionError(null);
    setActionSuccess(null);
    try {
      await api.acceptAssignment(legId);
      setActionSuccess('Assignment accepted successfully!');
      fetchWork();
    } catch (err: any) {
      setActionError(err.message || 'Failed to accept assignment');
    }
  };

  const handleDecline = async (legId: string) => {
    setActionError(null);
    setActionSuccess(null);
    try {
      await api.declineAssignment(legId, 'Collector declined');
      setActionSuccess('Assignment declined');
      fetchWork();
    } catch (err: any) {
      setActionError(err.message || 'Failed to decline assignment');
    }
  };

  const handleRecordLocation = async (e: React.FormEvent) => {
    e.preventDefault();
    setLocSuccess(null);
    try {
      const parsedLat = parseFloat(lat);
      const parsedLng = parseFloat(lng);
      await api.recordWorkerLocation(parsedLat, parsedLng);
      setLocSuccess(`Location updated to ${parsedLat.toFixed(4)}, ${parsedLng.toFixed(4)}`);
    } catch (err: any) {
      setActionError(err.message || 'Failed to update location');
    }
  };

  const handleCollectSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!collectingLeg) return;
    setActionError(null);
    setActionSuccess(null);

    try {
      await api.recordCollection({
        legId: collectingLeg.id,
        sampleId: collectingLeg.sampleId || collectingLeg.sample?.id,
        sealNumber,
        observedContainer: container,
        observedTemperature: parseFloat(temp),
      });
      setActionSuccess('Sample collected and sealed successfully!');
      setCollectingLeg(null);
      setSealNumber('');
      fetchWork();
    } catch (err: any) {
      setActionError(err.message || 'Failed to record collection');
    }
  };

  const handleHandoffSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!handoffLeg) return;
    setActionError(null);
    try {
      await api.initiateHandoff({
        sampleId: handoffLeg.sampleId || handoffLeg.sample?.id,
        legId: handoffLeg.id,
        handoffType,
        targetLocationId: handoffType.includes('node') ? targetId : undefined,
        targetUserId: handoffType.includes('worker') ? targetId : undefined,
      });
      setActionSuccess('Handoff initiated successfully!');
      setHandoffLeg(null);
      fetchWork();
    } catch (err: any) {
      setActionError(err.message || 'Failed to initiate handoff');
    }
  };

  const handleCheckpointSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!checkpointSampleId) return;
    try {
      await api.recordHandlingCheckpoint({
        sampleId: checkpointSampleId,
        observedContainer: checkpointContainer,
        observedTemperature: parseFloat(checkpointTemp),
      });
      setActionSuccess('Handling checkpoint recorded');
      setCheckpointSampleId(null);
      fetchWork();
    } catch (err: any) {
      setActionError(err.message || 'Failed to record checkpoint');
    }
  };

  return (
    <div role="region" aria-label="Collector Portal">
      <div className="tabs-nav" role="tablist">
        <button
          className={`tab-btn ${activeTab === 'current' ? 'active' : ''}`}
          onClick={() => setActiveTab('current')}
          role="tab"
          aria-selected={activeTab === 'current'}
          aria-label="Current Work Tab"
        >
          Current Work ({work.pending.length + work.inProgress.length})
        </button>
        <button
          className={`tab-btn ${activeTab === 'past' ? 'active' : ''}`}
          onClick={() => setActiveTab('past')}
          role="tab"
          aria-selected={activeTab === 'past'}
          aria-label="Past Work Tab"
        >
          Past Work ({work.completed.length})
        </button>
        <button
          className={`tab-btn ${activeTab === 'location' ? 'active' : ''}`}
          onClick={() => setActiveTab('location')}
          role="tab"
          aria-selected={activeTab === 'location'}
          aria-label="Update Location Tab"
        >
          📍 Update Location
        </button>
      </div>

      {actionError && (
        <div className="alert alert-danger" role="alert" aria-live="assertive">
          <span>{actionError}</span>
        </div>
      )}
      {actionSuccess && (
        <div className="alert alert-success" role="alert" aria-live="polite">
          <span>{actionSuccess}</span>
        </div>
      )}

      {activeTab === 'current' && (
        <div>
          {/* Pending Offers Section */}
          <div className="card">
            <div className="card-header">
              <h2 className="card-title">Pending Offers ({work.pending.length})</h2>
              <button className="btn btn-secondary btn-sm" onClick={fetchWork}>Refresh</button>
            </div>
            {work.pending.length === 0 ? (
              <p className="text-muted" style={{ fontStyle: 'italic' }}>No pending offers.</p>
            ) : (
              <div className="table-container">
                <table className="data-table" aria-label="Offered Assignments Table">
                  <thead>
                    <tr>
                      <th>Leg Type</th>
                      <th>Pickup Location</th>
                      <th>Dropoff Location</th>
                      <th>Sample / Type</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {work.pending.map((item) => (
                      <tr key={item.id}>
                        <td><span className="badge badge-offered">{item.legType || 'collection'}</span></td>
                        <td>{item.fromAddress || item.fromLocationName || 'Origin'}</td>
                        <td>{item.toLocationName || item.toAddress || 'Destination'}</td>
                        <td>{item.sampleTypeCode || 'Sample'}</td>
                        <td>
                          <div style={{ display: 'flex', gap: '0.5rem' }}>
                            <button
                              className="btn btn-success btn-sm"
                              onClick={() => handleAccept(item.id)}
                              aria-label={`Accept assignment ${item.id}`}
                            >
                              Accept Assignment
                            </button>
                            <button
                              className="btn btn-danger btn-sm"
                              onClick={() => handleDecline(item.id)}
                              aria-label={`Decline assignment ${item.id}`}
                            >
                              Decline
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>

          {/* In Progress Section */}
          <div className="card">
            <div className="card-header">
              <h2 className="card-title">Active / In Progress Work ({work.inProgress.length})</h2>
            </div>
            {work.inProgress.length === 0 ? (
              <p className="text-muted" style={{ fontStyle: 'italic' }}>No active assignments in progress.</p>
            ) : (
              <div className="table-container">
                <table className="data-table" aria-label="Active Work Table">
                  <thead>
                    <tr>
                      <th>Leg #</th>
                      <th>Pickup Location</th>
                      <th>Dropoff Location</th>
                      <th>Status</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {work.inProgress.map((item) => (
                      <tr key={item.id}>
                        <td>Leg {item.legNumber || 1}</td>
                        <td>{item.fromAddress || item.fromLocationName || 'Origin'}</td>
                        <td>{item.toLocationName || item.toAddress || 'Destination'}</td>
                        <td><span className="badge badge-in_progress">{item.status}</span></td>
                        <td>
                          <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
                            <button
                              className="btn btn-primary btn-sm"
                              onClick={() => setCollectingLeg(item)}
                              aria-label="Collect and seal sample"
                            >
                              Collect & Seal
                            </button>
                            <button
                              className="btn btn-secondary btn-sm"
                              onClick={() => setHandoffLeg(item)}
                              aria-label="Initiate handoff"
                            >
                              Handoff
                            </button>
                            <button
                              className="btn btn-secondary btn-sm"
                              onClick={() => setCheckpointSampleId(item.sampleId || item.sample?.id)}
                              aria-label="Record checkpoint"
                            >
                              Checkpoint
                            </button>
                            {item.sampleId && (
                              <button
                                className="btn btn-secondary btn-sm"
                                onClick={() => setSelectedSampleId(item.sampleId)}
                                aria-label="View sample"
                              >
                                View
                              </button>
                            )}
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      )}

      {activeTab === 'past' && (
        <div className="card">
          <div className="card-header">
            <h2 className="card-title">Completed (Past) Work ({work.completed.length})</h2>
            <button className="btn btn-secondary btn-sm" onClick={fetchWork}>Refresh</button>
          </div>
          {work.completed.length === 0 ? (
            <p className="text-muted" style={{ fontStyle: 'italic' }}>No completed assignments.</p>
          ) : (
            <div className="table-container">
              <table className="data-table" aria-label="Completed Work Table">
                <thead>
                  <tr>
                    <th>Leg #</th>
                    <th>Pickup</th>
                    <th>Dropoff</th>
                    <th>Completed At</th>
                    <th>Status</th>
                  </tr>
                </thead>
                <tbody>
                  {work.completed.map((item) => (
                    <tr key={item.id}>
                      <td>Leg {item.legNumber}</td>
                      <td>{item.fromAddress || item.fromLocationName}</td>
                      <td>{item.toLocationName || item.toAddress}</td>
                      <td>{item.completedAt ? new Date(item.completedAt).toLocaleString() : 'Done'}</td>
                      <td><span className="badge badge-completed">{item.status}</span></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {activeTab === 'location' && (
        <div className="card">
          <div className="card-header">
            <h2 className="card-title">Record Worker Location</h2>
          </div>
          <p className="text-muted" style={{ marginBottom: '1rem', fontSize: '0.875rem' }}>
            Broadcast your current GPS coordinates to update the tracking system and prevent stale location flags.
          </p>
          {locSuccess && <div className="alert alert-success">{locSuccess}</div>}

          <form onSubmit={handleRecordLocation} aria-label="Record Location Form">
            <div className="form-row">
              <div className="form-group">
                <label htmlFor="workerLat">Latitude</label>
                <input
                  id="workerLat"
                  type="text"
                  className="form-input"
                  value={lat}
                  onChange={(e) => setLat(e.target.value)}
                  required
                  aria-label="Latitude"
                />
              </div>

              <div className="form-group">
                <label htmlFor="workerLng">Longitude</label>
                <input
                  id="workerLng"
                  type="text"
                  className="form-input"
                  value={lng}
                  onChange={(e) => setLng(e.target.value)}
                  required
                  aria-label="Longitude"
                />
              </div>
            </div>

            <button type="submit" className="btn btn-primary" aria-label="Record Location">
              Record Location
            </button>
          </form>
        </div>
      )}

      {/* Collect & Seal Modal */}
      {collectingLeg && (
        <div className="modal-overlay" role="dialog" aria-modal="true" aria-label="Collect and Seal Sample Modal">
          <div className="modal-content">
            <div className="card-header">
              <h2 className="card-title">Collect & Seal Sample</h2>
              <button className="btn btn-secondary btn-sm" onClick={() => setCollectingLeg(null)}>✕</button>
            </div>
            <form onSubmit={handleCollectSubmit} aria-label="Collect and Seal Form">
              <div className="form-group">
                <label htmlFor="sealNumber">Seal Number / Barcode</label>
                <input
                  id="sealNumber"
                  type="text"
                  className="form-input"
                  value={sealNumber}
                  onChange={(e) => setSealNumber(e.target.value)}
                  required
                  placeholder="e.g. SEAL-99823"
                  aria-label="Seal Number"
                />
              </div>

              <div className="form-row">
                <div className="form-group">
                  <label htmlFor="container">Observed Container</label>
                  <select
                    id="container"
                    className="form-select"
                    value={container}
                    onChange={(e) => setContainer(e.target.value)}
                    aria-label="Observed Container"
                  >
                    <option value="standard_tube">Standard Tube</option>
                    <option value="amber_tube">Amber Tube</option>
                    <option value="cryovial">Cryovial</option>
                    <option value="insulated_box">Insulated Box</option>
                  </select>
                </div>

                <div className="form-group">
                  <label htmlFor="temp">Observed Temperature (°C)</label>
                  <input
                    id="temp"
                    type="number"
                    step="0.1"
                    className="form-input"
                    value={temp}
                    onChange={(e) => setTemp(e.target.value)}
                    required
                    aria-label="Observed Temperature"
                  />
                </div>
              </div>

              <div style={{ display: 'flex', gap: '1rem', marginTop: '1rem' }}>
                <button type="submit" className="btn btn-primary" aria-label="Confirm Collection and Seal">
                  Confirm Collection & Seal
                </button>
                <button type="button" className="btn btn-secondary" onClick={() => setCollectingLeg(null)}>
                  Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Handoff Modal */}
      {handoffLeg && (
        <div className="modal-overlay" role="dialog" aria-modal="true" aria-label="Initiate Handoff Modal">
          <div className="modal-content">
