              <button className="btn btn-secondary btn-sm" onClick={() => setHandoffLeg(null)}>✕</button>
            </div>
            <form onSubmit={handleHandoffSubmit} aria-label="Handoff Form">
              <div className="form-group">
                <label htmlFor="handoffType">Handoff Type</label>
                <select
                  id="handoffType"
                  className="form-select"
                  value={handoffType}
                  onChange={(e) => setHandoffType(e.target.value)}
                  aria-label="Handoff Type"
                >
                  <option value="worker_to_node">Worker to Facility / Node</option>
                  <option value="worker_to_worker">Worker to Relay Courier</option>
                  <option value="node_to_lab">Node to Laboratory</option>
                </select>
              </div>

              <div className="form-group">
                <label htmlFor="targetId">Target Location or User ID</label>
                <input
                  id="targetId"
