  // Progress update modal/form
  const [progressLeg, setProgressLeg] = useState<any | null>(null);
  const [newStatus, setNewStatus] = useState('en_route_to_pickup');
  const [progressNotes, setProgressNotes] = useState('');

  // Handoff state
  const [handoffLeg, setHandoffLeg] = useState<any | null>(null);
  const [handoffType, setHandoffType] = useState('worker_to_node');
  const [targetId, setTargetId] = useState('');

  // Checkpoint state
  const [checkpointSampleId, setCheckpointSampleId] = useState<string | null>(null);
  const [checkpointContainer, setCheckpointContainer] = useState('standard_tube');
  const [checkpointTemp, setCheckpointTemp] = useState('4.0');

  const fetchWork = async () => {
    setLoading(true);
    try {
      const res = await api.listWork();
      setWork({
        pending: res.pending || [],
        inProgress: res.inProgress || [],
        completed: res.completed || [],
      });
    } catch (err: any) {
      console.error('Failed to load courier work', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchWork();
  }, []);

  const handleAccept = async (legId: string) => {
    setActionError(null);
    setActionSuccess(null);
    try {
      await api.acceptAssignment(legId);
      setActionSuccess('Transport assignment accepted!');
      fetchWork();
    } catch (err: any) {
      setActionError(err.message || 'Failed to accept assignment');
    }
