import React, { useState, useEffect } from 'react';
import { api } from '../api';
import { Location, CapacityPool } from '../types';
import { SampleDetailModal } from './SampleDetailModal';

interface LabOperatorProps {
  user: any;
  locations: Location[];
}

export const LabOperatorView: React.FC<LabOperatorProps> = ({ user, locations }) => {
  const [activeTab, setActiveTab] = useState<'work' | 'intake' | 'capacity' | 'exception'>('work');
  const [work, setWork] = useState<{ pending: any[]; inProgress: any[]; completed: any[] }>({
    pending: [],
    inProgress: [],
    completed: [],
  });
  const [capacity, setCapacity] = useState<CapacityPool[]>([]);
  const [loading, setLoading] = useState(true);
  const [actionError, setActionError] = useState<string | null>(null);
  const [actionSuccess, setActionSuccess] = useState<string | null>(null);
  const [selectedSampleId, setSelectedSampleId] = useState<string | null>(null);

  // Intake Form State
  const [intakeSampleId, setIntakeSampleId] = useState('');
  const [container, setContainer] = useState('standard_tube');
  const [temp, setTemp] = useState('4.0');
  const [isAccepted, setIsAccepted] = useState(true);
  const [intakeReason, setIntakeReason] = useState('');
  const [notes, setNotes] = useState('');

  // Exception Form State
  const [exceptionSampleId, setExceptionSampleId] = useState('');
  const [exceptionReason, setExceptionReason] = useState('Temperature excursion / Damaged container');
  const [exceptionDetails, setExceptionDetails] = useState('');

  // Capacity Edit State
  const [editingCapacityType, setEditingCapacityType] = useState<'regular' | 'cooled'>('regular');
  const [newUnits, setNewUnits] = useState('30');

  const facilityId = user?.assignedFacilityId || locations.find((l) => l.type === 'laboratory' || l.type === 'hub_laboratory')?.id || locations[0]?.id;

  const fetchWorkAndCapacity = async () => {
    setLoading(true);
    try {
      const [workRes, capRes] = await Promise.all([
        api.listWork(),
        facilityId ? api.readCapacity(facilityId) : Promise.resolve({ data: [] }),
      ]);
      setWork({
        pending: workRes.pending || [],
        inProgress: workRes.inProgress || [],
        completed: workRes.completed || [],
      });
      setCapacity(capRes.data || (Array.isArray(capRes) ? capRes : []));
    } catch (err: any) {
      console.error('Failed to load lab operator data', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchWorkAndCapacity();
  }, [facilityId]);

  const handleAccept = async (legId: string) => {
    setActionError(null);
    try {
      await api.acceptAssignment(legId);
      setActionSuccess('Lab assignment accepted!');
      fetchWorkAndCapacity();
    } catch (err: any) {
      setActionError(err.message || 'Failed to accept assignment');
    }
  };

  const handleDecline = async (legId: string) => {
    setActionError(null);
    try {
      await api.declineAssignment(legId, 'Lab operator declined');
      setActionSuccess('Assignment declined');
      fetchWorkAndCapacity();
    } catch (err: any) {
      setActionError(err.message || 'Failed to decline assignment');
    }
  };

  const handleIntakeSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionError(null);
    setActionSuccess(null);

    try {
      await api.confirmLabReceipt({
        sampleId: intakeSampleId,
        laboratoryId: facilityId,
        observedContainer: container,
        observedTemperature: parseFloat(temp),
        isAccepted,
        exceptionReason: !isAccepted ? intakeReason : undefined,
        notes,
      });
      setActionSuccess(isAccepted ? 'Sample received and journey completed!' : 'Sample marked with intake rejection exception');
      setIntakeSampleId('');
      fetchWorkAndCapacity();
    } catch (err: any) {
      setActionError(err.message || 'Failed to process lab receipt');
    }
  };

  const handleExceptionSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionError(null);
    setActionSuccess(null);

    try {
      await api.recordSampleException({
        sampleId: exceptionSampleId,
        reason: exceptionReason,
        details: exceptionDetails,
      });
      setActionSuccess('Sample exception recorded successfully');
      setExceptionSampleId('');
      setExceptionDetails('');
      fetchWorkAndCapacity();
    } catch (err: any) {
      setActionError(err.message || 'Failed to record exception');
    }
  };

  const handleCapacityUpdate = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionError(null);
    setActionSuccess(null);

    try {
      await api.configureCapacity({
        facilityId,
        capacityType: editingCapacityType,
        configuredUnits: parseInt(newUnits, 10),
      });
      setActionSuccess(`${editingCapacityType.toUpperCase()} capacity updated to ${newUnits} units`);
      fetchWorkAndCapacity();
    } catch (err: any) {
      setActionError(err.message || 'Failed to update capacity');
    }
  };

  const assignedLab = locations.find((l) => l.id === facilityId);

  return (
    <div role="region" aria-label="Laboratory Intake Portal">
      <div style={{ marginBottom: '1rem', padding: '0.75rem 1rem', background: '#f3e8ff', borderRadius: '8px', color: '#6b21a8' }}>
        <strong>Assigned Laboratory:</strong> {assignedLab ? `${assignedLab.name} (${assignedLab.code})` : 'All Laboratories'}
      </div>

      <div className="tabs-nav" role="tablist">
        <button
          className={`tab-btn ${activeTab === 'work' ? 'active' : ''}`}
          onClick={() => setActiveTab('work')}
          role="tab"
          aria-selected={activeTab === 'work'}
          aria-label="Expected Samples Tab"
        >
          Expected & In-Progress ({work.pending.length + work.inProgress.length})
        </button>
        <button
          className={`tab-btn ${activeTab === 'intake' ? 'active' : ''}`}
          onClick={() => setActiveTab('intake')}
          role="tab"
          aria-selected={activeTab === 'intake'}
          aria-label="Confirm Receipt Tab"
        >
          🔬 Confirm Receipt
        </button>
        <button
          className={`tab-btn ${activeTab === 'capacity' ? 'active' : ''}`}
          onClick={() => setActiveTab('capacity')}
          role="tab"
          aria-selected={activeTab === 'capacity'}
          aria-label="Lab Capacity Tab"
        >
          📦 Lab Capacity
        </button>
        <button
          className={`tab-btn ${activeTab === 'exception' ? 'active' : ''}`}
          onClick={() => setActiveTab('exception')}
          role="tab"
          aria-selected={activeTab === 'exception'}
          aria-label="Record Exception Tab"
        >
          ⚠️ Record Exception
        </button>
      </div>

      {actionError && (
        <div className="alert alert-danger" role="alert" aria-live="assertive">
          <span>{actionError}</span>
        </div>
      )}
      {actionSuccess && (
        <div className="alert alert-success" role="alert" aria-live="polite">
          <span>{actionSuccess}</span>
        </div>
      )}

      {activeTab === 'work' && (
        <div>
          {/* Pending Intake Offers */}
          <div className="card">
            <div className="card-header">
              <h2 className="card-title">Pending Lab Intake Offers ({work.pending.length})</h2>
              <button className="btn btn-secondary btn-sm" onClick={fetchWorkAndCapacity}>Refresh</button>
            </div>
            {work.pending.length === 0 ? (
              <p className="text-muted" style={{ fontStyle: 'italic' }}>No pending intake offers.</p>
            ) : (
              <div className="table-container">
                <table className="data-table" aria-label="Offered Intake Table">
                  <thead>
                    <tr>
                      <th>Leg #</th>
                      <th>Facility</th>
                      <th>Sample Type</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {work.pending.map((item) => (
                      <tr key={item.id}>
                        <td>Leg {item.legNumber || 1}</td>
                        <td>{item.toLocationName || 'Lab'}</td>
                        <td>{item.sampleTypeCode || 'Sample'}</td>
                        <td>
                          <div style={{ display: 'flex', gap: '0.5rem' }}>
                            <button
                              className="btn btn-success btn-sm"
                              onClick={() => handleAccept(item.id)}
                              aria-label={`Accept intake assignment ${item.id}`}
                            >
                              Accept Assignment
                            </button>
                            <button
                              className="btn btn-danger btn-sm"
                              onClick={() => handleDecline(item.id)}
                              aria-label={`Decline intake assignment ${item.id}`}
                            >
                              Decline
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>

          {/* In Progress Intake */}
          <div className="card">
            <div className="card-header">
              <h2 className="card-title">Expected Incoming Samples ({work.inProgress.length})</h2>
            </div>
            {work.inProgress.length === 0 ? (
              <p className="text-muted" style={{ fontStyle: 'italic' }}>No expected samples currently.</p>
            ) : (
              <div className="table-container">
                <table className="data-table" aria-label="Expected Samples Table">
                  <thead>
                    <tr>
                      <th>Leg #</th>
                      <th>Origin</th>
                      <th>Status</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {work.inProgress.map((item) => (
                      <tr key={item.id}>
                        <td>Leg {item.legNumber}</td>
                        <td>{item.fromLocationName || item.fromAddress}</td>
                        <td><span className="badge badge-in_progress">{item.status}</span></td>
                        <td>
                          <div style={{ display: 'flex', gap: '0.5rem' }}>
                            <button
                              className="btn btn-primary btn-sm"
                              onClick={() => {
                                setIntakeSampleId(item.sampleId || item.sample?.id);
                                setActiveTab('intake');
                              }}
                              aria-label="Process intake"
                            >
                              Process Intake
                            </button>
                            {item.sampleId && (
                              <button
                                className="btn btn-secondary btn-sm"
                                onClick={() => setSelectedSampleId(item.sampleId)}
                                aria-label="View sample"
                              >
                                View
                              </button>
                            )}
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      )}

      {activeTab === 'intake' && (
        <div className="card">
          <div className="card-header">
            <h2 className="card-title">Confirm Laboratory Receipt</h2>
          </div>
          <p className="text-muted" style={{ marginBottom: '1rem', fontSize: '0.875rem' }}>
            Inspect incoming sample container and temperature before accepting into the laboratory.
          </p>

          <form onSubmit={handleIntakeSubmit} aria-label="Confirm Lab Receipt Form" style={{ maxWidth: '600px' }}>
            <div className="form-group">
              <label htmlFor="in_sampleId">Sample ID or Tracking Number</label>
              <input
                id="in_sampleId"
                type="text"
                className="form-input"
                value={intakeSampleId}
                onChange={(e) => setIntakeSampleId(e.target.value)}
                required
                placeholder="Enter sample ID or tracking number"
                aria-label="Sample ID"
              />
            </div>

            <div className="form-row">
              <div className="form-group">
                <label htmlFor="in_container">Observed Container</label>
                <select
                  id="in_container"
                  className="form-select"
                  value={container}
                  onChange={(e) => setContainer(e.target.value)}
                  aria-label="Observed Container"
                >
                  <option value="standard_tube">Standard Tube</option>
                  <option value="amber_tube">Amber Tube</option>
                  <option value="cryovial">Cryovial</option>
                  <option value="insulated_box">Insulated Box</option>
                </select>
              </div>

              <div className="form-group">
                <label htmlFor="in_temp">Observed Temperature (°C)</label>
                <input
                  id="in_temp"
                  type="number"
                  step="0.1"
                  className="form-input"
                  value={temp}
                  onChange={(e) => setTemp(e.target.value)}
                  required
                  aria-label="Observed Temperature"
                />
              </div>
            </div>

            <div className="form-group">
              <label>Intake Acceptance</label>
              <div style={{ display: 'flex', gap: '1.5rem', marginTop: '0.25rem' }}>
                <label style={{ display: 'flex', alignItems: 'center', gap: '0.35rem', cursor: 'pointer' }}>
                  <input
                    type="radio"
                    name="isAccepted"
                    checked={isAccepted}
                    onChange={() => setIsAccepted(true)}
                  />
                  <span>Accept Normally</span>
                </label>
                <label style={{ display: 'flex', alignItems: 'center', gap: '0.35rem', cursor: 'pointer' }}>
                  <input
                    type="radio"
                    name="isAccepted"
                    checked={!isAccepted}
                    onChange={() => setIsAccepted(false)}
                  />
                  <span style={{ color: '#dc2626' }}>Reject / Exception</span>
                </label>
              </div>
            </div>

            {!isAccepted && (
              <div className="form-group">
                <label htmlFor="in_reason">Exception Reason</label>
                <input
                  id="in_reason"
                  type="text"
                  className="form-input"
                  value={intakeReason}
                  onChange={(e) => setIntakeReason(e.target.value)}
                  required={!isAccepted}
                  placeholder="e.g. Broken seal, hemolyzed, temperature breach"
                  aria-label="Exception Reason"
                />
              </div>
            )}

            <div className="form-group">
              <label htmlFor="in_notes">Intake Notes</label>
              <textarea
                id="in_notes"
                className="form-textarea"
                rows={2}
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                placeholder="Optional intake notes..."
                aria-label="Intake Notes"
              />
            </div>

            <button type="submit" className="btn btn-primary" aria-label="Confirm Receipt">
              Confirm Receipt
            </button>
          </form>
        </div>
      )}

      {activeTab === 'capacity' && (
        <div className="card">
          <div className="card-header">
            <h2 className="card-title">Laboratory Capacity ({assignedLab?.name || 'Lab'})</h2>
            <button className="btn btn-secondary btn-sm" onClick={fetchWorkAndCapacity}>Refresh</button>
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '1rem', marginBottom: '1.5rem' }}>
            {capacity.map((cap) => (
              <div key={cap.id || cap.capacityType} className="stat-card" style={{ borderLeft: `4px solid ${cap.capacityType === 'cooled' ? '#0284c7' : '#64748b'}` }}>
                <span className="stat-label">{cap.capacityType} Capacity</span>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline' }}>
                  <span className="stat-value">{cap.availableUnits}</span>
                  <span style={{ fontSize: '0.85rem', color: '#64748b' }}>/ {cap.configuredUnits} total</span>
                </div>
                <div style={{ fontSize: '0.75rem', color: '#475569', marginTop: '0.25rem' }}>
                  Reserved: <strong>{cap.reservedUnits}</strong> units
                </div>
              </div>
            ))}
          </div>

          <h3 style={{ fontSize: '1rem', fontWeight: 600, marginBottom: '0.75rem' }}>Update Laboratory Capacity</h3>
          <form onSubmit={handleCapacityUpdate} aria-label="Configure Lab Capacity Form" style={{ maxWidth: '400px' }}>
