import React, { useState, useEffect } from 'react';
import { api } from '../api';
import { Sample, Location, Journey } from '../types';
import { MapComponent } from './MapComponent';
import { SampleDetailModal } from './SampleDetailModal';

export const DispatcherDashboard: React.FC = () => {
  const [activeCategory, setActiveCategory] = useState<'samples' | 'workers' | 'nodes' | 'laboratories' | 'routes' | 'exceptions' | 'map'>('samples');
  const [opsData, setOpsData] = useState<{
    samples: Sample[];
    workers: any[];
    locations: Location[];
    routes: Journey[];
    exceptions: any[];
    disruptions: any[];
  }>({
    samples: [],
    workers: [],
    locations: [],
    routes: [],
    exceptions: [],
    disruptions: [],
  });
  const [loading, setLoading] = useState(true);
  const [actionError, setActionError] = useState<string | null>(null);
  const [actionSuccess, setActionSuccess] = useState<string | null>(null);
  const [selectedSampleId, setSelectedSampleId] = useState<string | null>(null);

  // Replan modal
  const [replanSample, setReplanSample] = useState<Sample | null>(null);
  const [replanReason, setReplanReason] = useState('Network disruption / Rebalancing');
  const [preferredLabId, setPreferredLabId] = useState('');

  // Disruption report modal
  const [showDisruptionModal, setShowDisruptionModal] = useState(false);
  const [disruptionType, setDisruptionType] = useState('node_offline');
  const [disruptionEntityId, setDisruptionEntityId] = useState('');
  const [disruptionDescription, setDisruptionDescription] = useState('');
  const [disruptionDuration, setDisruptionDuration] = useState('60');

  // Cancel request state
  const [cancelRequestId, setCancelRequestId] = useState('');
  const [cancelReason, setCancelReason] = useState('Operational override');
  const [showCancelModal, setShowCancelModal] = useState(false);

  const fetchOperationsData = async () => {
    setLoading(true);
    try {
      const res = await api.readOperationsState();
      setOpsData({
        samples: res.samples || [],
        workers: res.workers || [],
        locations: res.locations || [],
        routes: res.routes || [],
        exceptions: res.exceptions || (res.samples || []).filter((s: Sample) => s.isException),
        disruptions: res.disruptions || [],
      });
    } catch (err: any) {
      console.error('Failed to load operations state', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchOperationsData();
  }, []);

  const handleReplanSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!replanSample) return;
    setActionError(null);
    setActionSuccess(null);

    try {
      await api.replanJourney({
        sampleId: replanSample.id,
        currentPlanVersion: replanSample.activePlanVersion || 1,
        reason: replanReason,
        preferredLabId: preferredLabId || undefined,
      });
      setActionSuccess(`Journey replanned successfully for sample ${replanSample.trackingNumber}`);
      setReplanSample(null);
      fetchOperationsData();
    } catch (err: any) {
      setActionError(err.message || 'Failed to replan journey');
    }
  };

  const handleDisruptionSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionError(null);
    setActionSuccess(null);

    try {
      await api.reportDisruption({
        disruptionType,
        entityId: disruptionEntityId,
        description: disruptionDescription,
        expectedDurationMinutes: parseInt(disruptionDuration, 10),
      });
      setActionSuccess('Disruption reported. Affected routes flagged for replanning.');
      setShowDisruptionModal(false);
      setDisruptionDescription('');
      fetchOperationsData();
    } catch (err: any) {
      setActionError(err.message || 'Failed to report disruption');
    }
  };

  const handleCancelSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionError(null);
    setActionSuccess(null);

    try {
      await api.cancelRequest(cancelRequestId, cancelReason);
      setActionSuccess('Request cancelled successfully');
      setShowCancelModal(false);
      setCancelRequestId('');
      fetchOperationsData();
    } catch (err: any) {
      setActionError(err.message || 'Failed to cancel request');
    }
  };

  const nodes = opsData.locations.filter((l) => l.type !== 'laboratory');
  const labs = opsData.locations.filter((l) => l.type === 'laboratory' || l.type === 'hub_laboratory');
  const staleSamplesCount = opsData.samples.filter((s) => s.isLocationStale).length;
  const exceptionSamples = opsData.samples.filter((s) => s.isException);

  return (
    <div role="region" aria-label="Operations Dispatcher Dashboard">
      {/* Overview Stat Cards */}
      <div className="dashboard-grid">
        <div className="stat-card">
          <span className="stat-label">Active Samples</span>
          <span className="stat-value">{opsData.samples.length}</span>
        </div>
        <div className="stat-card" style={{ borderLeft: '4px solid #16a34a' }}>
          <span className="stat-label">Active Workers</span>
          <span className="stat-value">{opsData.workers.length}</span>
        </div>
        <div className="stat-card" style={{ borderLeft: '4px solid #dc2626' }}>
          <span className="stat-label">Exceptions / Stale</span>
          <span className="stat-value" style={{ color: '#dc2626' }}>
            {exceptionSamples.length} / {staleSamplesCount}
          </span>
        </div>
        <div className="stat-card" style={{ borderLeft: '4px solid #7c3aed' }}>
          <span className="stat-label">Network Nodes & Labs</span>
          <span className="stat-value">{opsData.locations.length}</span>
        </div>
      </div>

      {/* Action Toolbar */}
      <div style={{ display: 'flex', gap: '0.75rem', marginBottom: '1.25rem', flexWrap: 'wrap' }}>
        <button
          className="btn btn-primary btn-sm"
          onClick={() => setShowDisruptionModal(true)}
          aria-label="Report Disruption"
        >
          🚨 Report Network Disruption
        </button>
        <button
          className="btn btn-danger btn-sm"
          onClick={() => setShowCancelModal(true)}
          aria-label="Cancel Request"
        >
          ✕ Cancel Unfinished Request
        </button>
        <button
          className="btn btn-secondary btn-sm"
          onClick={fetchOperationsData}
          aria-label="Refresh Operations Data"
        >
          🔄 Refresh Data
        </button>
      </div>

      {actionError && (
        <div className="alert alert-danger" role="alert" aria-live="assertive">
          <span>{actionError}</span>
        </div>
      )}
      {actionSuccess && (
        <div className="alert alert-success" role="alert" aria-live="polite">
          <span>{actionSuccess}</span>
        </div>
      )}

      {/* Categories Navigation Bar */}
      <div className="tabs-nav" role="tablist" aria-label="Operations Categories">
        <button
          className={`tab-btn ${activeCategory === 'samples' ? 'active' : ''}`}
          onClick={() => setActiveCategory('samples')}
          role="tab"
          aria-selected={activeCategory === 'samples'}
          aria-label="Samples Category"
        >
          Samples ({opsData.samples.length})
        </button>
        <button
          className={`tab-btn ${activeCategory === 'workers' ? 'active' : ''}`}
          onClick={() => setActiveCategory('workers')}
          role="tab"
          aria-selected={activeCategory === 'workers'}
          aria-label="Workers Category"
        >
          Workers ({opsData.workers.length})
        </button>
        <button
          className={`tab-btn ${activeCategory === 'nodes' ? 'active' : ''}`}
          onClick={() => setActiveCategory('nodes')}
          role="tab"
          aria-selected={activeCategory === 'nodes'}
          aria-label="Collection Nodes Category"
        >
          Collection Nodes ({nodes.length})
        </button>
        <button
          className={`tab-btn ${activeCategory === 'laboratories' ? 'active' : ''}`}
          onClick={() => setActiveCategory('laboratories')}
          role="tab"
          aria-selected={activeCategory === 'laboratories'}
          aria-label="Laboratories Category"
        >
          Laboratories ({labs.length})
        </button>
        <button
          className={`tab-btn ${activeCategory === 'routes' ? 'active' : ''}`}
          onClick={() => setActiveCategory('routes')}
          role="tab"
          aria-selected={activeCategory === 'routes'}
          aria-label="Routes Category"
        >
          Routes ({opsData.routes.length})
        </button>
        <button
          className={`tab-btn ${activeCategory === 'exceptions' ? 'active' : ''}`}
          onClick={() => setActiveCategory('exceptions')}
          role="tab"
          aria-selected={activeCategory === 'exceptions'}
          aria-label="Exceptions Category"
        >
          Exceptions ({exceptionSamples.length})
        </button>
        <button
          className={`tab-btn ${activeCategory === 'map' ? 'active' : ''}`}
          onClick={() => setActiveCategory('map')}
          role="tab"
          aria-selected={activeCategory === 'map'}
          aria-label="Live Map View"
        >
          🗺️ Live Map
        </button>
      </div>

      {/* Category: Samples */}
      {activeCategory === 'samples' && (
        <div className="card">
          <div className="card-header">
            <h2 className="card-title">All Samples in Network</h2>
          </div>
          {opsData.samples.length === 0 ? (
            <p className="text-muted" style={{ fontStyle: 'italic' }}>No active samples found.</p>
          ) : (
            <div className="table-container">
              <table className="data-table" aria-label="Operations Samples Table">
                <thead>
                  <tr>
                    <th>Tracking #</th>
                    <th>Sample Type</th>
                    <th>Status</th>
                    <th>Current Holder</th>
                    <th>Location</th>
                    <th>Freshness</th>
                    <th>Deadline</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {opsData.samples.map((s) => (
                    <tr key={s.id}>
                      <td>
                        <strong>{s.trackingNumber}</strong>
                        {s.isException && (
                          <span className="badge badge-exception" style={{ marginLeft: '0.4rem' }}>
                            ⚠️ Flagged
                          </span>
                        )}
                      </td>
                      <td>{s.sampleTypeCode}</td>
                      <td><span className={`badge badge-${s.status}`}>{s.status}</span></td>
                      <td>{s.currentHolderName || 'Unassigned'}</td>
                      <td>{s.currentLocationName || (s.currentLatitude ? `${s.currentLatitude.toFixed(3)}, ${s.currentLongitude?.toFixed(3)}` : 'N/A')}</td>
                      <td>
                        {s.isLocationStale ? (
                          <span className="badge badge-stale" aria-label="Stale Location">⚠️ STALE</span>
                        ) : (
                          <span className="badge badge-received" style={{ fontSize: '0.7rem' }}>Fresh</span>
                        )}
                      </td>
                      <td>{new Date(s.deliveryDeadline).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', month: 'short', day: 'numeric' })}</td>
                      <td>
                        <div style={{ display: 'flex', gap: '0.35rem' }}>
                          <button
                            className="btn btn-secondary btn-sm"
                            onClick={() => setSelectedSampleId(s.id)}
                            aria-label={`View sample ${s.trackingNumber}`}
                          >
                            Details
                          </button>
                          {s.status !== 'received' && s.status !== 'cancelled' && (
                            <button
                              className="btn btn-primary btn-sm"
                              onClick={() => setReplanSample(s)}
                              aria-label={`Replan sample ${s.trackingNumber}`}
                            >
                              Replan
                            </button>
                          )}
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {/* Category: Workers */}
      {activeCategory === 'workers' && (
        <div className="card">
          <div className="card-header">
            <h2 className="card-title">Active Workers</h2>
          </div>
          {opsData.workers.length === 0 ? (
            <p className="text-muted" style={{ fontStyle: 'italic' }}>No workers currently active.</p>
          ) : (
            <div className="table-container">
              <table className="data-table" aria-label="Workers Table">
                <thead>
                  <tr>
                    <th>Worker Name</th>
                    <th>Role(s)</th>
                    <th>Assigned Facility</th>
                    <th>Latest Location</th>
                    <th>Location Freshness</th>
                  </tr>
                </thead>
                <tbody>
                  {opsData.workers.map((w) => (
                    <tr key={w.id}>
                      <td><strong>{w.fullName || w.username}</strong></td>
                      <td>
                        {(w.roles || []).map((r: string) => (
                          <span key={r} className="badge badge-pending" style={{ marginRight: '0.25rem' }}>{r}</span>
                        ))}
                      </td>
                      <td>{w.assignedFacilityId || 'Mobile / Field'}</td>
                      <td>
                        {w.latitude && w.longitude ? `${w.latitude.toFixed(4)}, ${w.longitude.toFixed(4)}` : 'No GPS reported'}
                      </td>
                      <td>
                        {w.isLocationStale ? (
                          <span className="badge badge-stale">⚠️ STALE</span>
                        ) : (
                          <span className="badge badge-received">Fresh</span>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {/* Category: Collection Nodes */}
      {activeCategory === 'nodes' && (
        <div className="card">
          <div className="card-header">
            <h2 className="card-title">Collection Nodes & Transfer Hubs</h2>
          </div>
          <div className="table-container">
            <table className="data-table" aria-label="Collection Nodes Table">
              <thead>
                <tr>
                  <th>Code</th>
                  <th>Name</th>
                  <th>Type</th>
                  <th>Status</th>
                  <th>Functions</th>
                  <th>Coordinates</th>
                </tr>
              </thead>
              <tbody>
                {nodes.map((n) => (
                  <tr key={n.id}>
                    <td><strong>{n.code}</strong></td>
                    <td>{n.name}</td>
                    <td>{n.type}</td>
                    <td><span className={`badge badge-${n.status === 'active' ? 'received' : 'exception'}`}>{n.status}</span></td>
                    <td>{(n.functions || []).join(', ')}</td>
                    <td>{n.latitude.toFixed(4)}, {n.longitude.toFixed(4)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Category: Laboratories */}
      {activeCategory === 'laboratories' && (
        <div className="card">
          <div className="card-header">
            <h2 className="card-title">Laboratories</h2>
          </div>
          <div className="table-container">
            <table className="data-table" aria-label="Laboratories Table">
              <thead>
                <tr>
                  <th>Code</th>
                  <th>Name</th>
                  <th>Status</th>
                  <th>Address</th>
                  <th>Coordinates</th>
                </tr>
              </thead>
              <tbody>
                {labs.map((l) => (
                  <tr key={l.id}>
                    <td><strong>{l.code}</strong></td>
                    <td>{l.name}</td>
                    <td><span className={`badge badge-${l.status === 'active' ? 'received' : 'exception'}`}>{l.status}</span></td>
                    <td>{l.address}</td>
                    <td>{l.latitude.toFixed(4)}, {l.longitude.toFixed(4)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Category: Routes */}
      {activeCategory === 'routes' && (
        <div className="card">
          <div className="card-header">
            <h2 className="card-title">Active Routes & Journeys</h2>
          </div>
          {opsData.routes.length === 0 ? (
            <p className="text-muted" style={{ fontStyle: 'italic' }}>No active journeys in transit.</p>
          ) : (
            <div className="table-container">
              <table className="data-table" aria-label="Journeys Table">
                <thead>
                  <tr>
                    <th>Journey ID</th>
                    <th>Sample Tracking #</th>
                    <th>Plan Version</th>
                    <th>Status</th>
                    <th>Total Legs</th>
                    <th>Current Leg</th>
                  </tr>
                </thead>
                <tbody>
                  {opsData.routes.map((j) => (
                    <tr key={j.id}>
                      <td><code>{j.id.slice(0, 8)}...</code></td>
                      <td><strong>{j.trackingNumber || j.sampleId.slice(0, 8)}</strong></td>
                      <td>v{j.planVersion}</td>
                      <td><span className={`badge badge-${j.status}`}>{j.status}</span></td>
                      <td>{(j.legs || []).length} legs</td>
                      <td>Leg {j.currentLegNumber || 1}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {/* Category: Exceptions */}
      {activeCategory === 'exceptions' && (
        <div className="card">
          <div className="card-header">
            <h2 className="card-title">Sample Exceptions ({exceptionSamples.length})</h2>
          </div>
          {exceptionSamples.length === 0 ? (
            <p className="text-muted" style={{ fontStyle: 'italic' }}>No active exceptions in the network.</p>
          ) : (
            <div className="table-container">
              <table className="data-table" aria-label="Exceptions Table">
                <thead>
                  <tr>
                    <th>Tracking #</th>
                    <th>Sample Type</th>
                    <th>Exception Reason</th>
                    <th>Current Holder</th>
                    <th>Flagged At</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {exceptionSamples.map((s) => (
                    <tr key={s.id} style={{ backgroundColor: '#fff1f2' }}>
                      <td><strong>{s.trackingNumber}</strong></td>
                      <td>{s.sampleTypeCode}</td>
                      <td style={{ color: '#b91c1c', fontWeight: 600 }}>{s.exceptionReason || 'Handling violation'}</td>
                      <td>{s.currentHolderName || 'Unassigned'}</td>
                      <td>{s.exceptionTimestamp ? new Date(s.exceptionTimestamp).toLocaleString() : 'N/A'}</td>
                      <td>
                        <div style={{ display: 'flex', gap: '0.35rem' }}>
                          <button
                            className="btn btn-secondary btn-sm"
                            onClick={() => setSelectedSampleId(s.id)}
                            aria-label="View details"
                          >
                            Details
                          </button>
                          <button
                            className="btn btn-primary btn-sm"
                            onClick={() => setReplanSample(s)}
                            aria-label="Replan"
                          >
                            Replan
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {/* Category: Live Map */}
      {activeCategory === 'map' && (
        <div className="card">
          <div className="card-header">
            <h2 className="card-title">Live Transport Network Map</h2>
          </div>
          <MapComponent
            locations={opsData.locations.map((l) => ({
              id: l.id,
              name: l.name,
              type: l.type,
              latitude: l.latitude,
              longitude: l.longitude,
              status: l.status,
            }))}
            workers={opsData.workers.map((w) => ({
              id: w.id,
              name: w.fullName || w.username,
              role: (w.roles || []).join(', '),
              latitude: w.latitude,
              longitude: w.longitude,
              isStale: w.isLocationStale,
            }))}
            height="550px"
          />
        </div>
      )}

      {/* Replan Modal */}
      {replanSample && (
        <div className="modal-overlay" role="dialog" aria-modal="true" aria-label="Replan Journey Modal">
          <div className="modal-content">
            <div className="card-header">
              <h2 className="card-title">Replan Journey: #{replanSample.trackingNumber}</h2>
              <button className="btn btn-secondary btn-sm" onClick={() => setReplanSample(null)}>✕</button>
            </div>
            <p className="text-muted" style={{ marginBottom: '1rem', fontSize: '0.85rem' }}>
              Replanning preserves confirmed custody, completed stops, and valid history while recalculating remaining legs.
            </p>
            <form onSubmit={handleReplanSubmit} aria-label="Replan Form">
              <div className="form-group">
                <label htmlFor="rep_reason">Reason for Replanning</label>
                <input
                  id="rep_reason"
                  type="text"
                  className="form-input"
                  value={replanReason}
                  onChange={(e) => setReplanReason(e.target.value)}
                  required
                  aria-label="Replanning Reason"
                />
              </div>

              <div className="form-group">
                <label htmlFor="rep_lab">Preferred Destination Laboratory (Optional)</label>
                <select
                  id="rep_lab"
                  className="form-select"
                  value={preferredLabId}
                  onChange={(e) => setPreferredLabId(e.target.value)}
                  aria-label="Preferred Laboratory"
                >
                  <option value="">Auto-select best accepting lab</option>
                  {labs.map((l) => (
                    <option key={l.id} value={l.id}>{l.name} ({l.code})</option>
                  ))}
                </select>
              </div>

              <div style={{ display: 'flex', gap: '1rem', marginTop: '1rem' }}>
                <button type="submit" className="btn btn-primary" aria-label="Execute Replan">
                  Execute Replan
                </button>
                <button type="button" className="btn btn-secondary" onClick={() => setReplanSample(null)}>
                  Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Disruption Modal */}
      {showDisruptionModal && (
        <div className="modal-overlay" role="dialog" aria-modal="true" aria-label="Report Disruption Modal">
          <div className="modal-content">
            <div className="card-header">
              <h2 className="card-title">Report Network Disruption</h2>
              <button className="btn btn-secondary btn-sm" onClick={() => setShowDisruptionModal(false)}>✕</button>
            </div>
            <form onSubmit={handleDisruptionSubmit} aria-label="Disruption Form">
              <div className="form-group">
                <label htmlFor="dis_type">Disruption Type</label>
                <select
                  id="dis_type"
                  className="form-select"
                  value={disruptionType}
                  onChange={(e) => setDisruptionType(e.target.value)}
                  aria-label="Disruption Type"
                >
                  <option value="node_offline">Collection Node / Hub Offline</option>
                  <option value="lab_offline">Laboratory Unavailable</option>
                  <option value="route_blocked">Transport Connection Blocked</option>
                  <option value="worker_unavailable">Worker Incapacitated / Unavailable</option>
                  <option value="capacity_exhausted">Capacity Pool Outage</option>
                </select>
              </div>

              <div className="form-group">
                <label htmlFor="dis_entityId">Affected Entity ID (Location, Worker, or Route)</label>
                <input
                  id="dis_entityId"
                  type="text"
                  className="form-input"
                  value={disruptionEntityId}
                  onChange={(e) => setDisruptionEntityId(e.target.value)}
                  required
                  placeholder="Enter ID of affected location, worker, or connection"
                  aria-label="Entity ID"
                />
              </div>

              <div className="form-group">
                <label htmlFor="dis_desc">Description</label>
                <textarea
                  id="dis_desc"
                  className="form-textarea"
                  rows={2}
                  value={disruptionDescription}
                  onChange={(e) => setDisruptionDescription(e.target.value)}
                  required
                  placeholder="Describe the disruption..."
                  aria-label="Description"
                />
              </div>

              <div className="form-group">
                <label htmlFor="dis_duration">Expected Duration (Minutes)</label>
                <input
                  id="dis_duration"
                  type="number"
                  className="form-input"
                  value={disruptionDuration}
                  onChange={(e) => setDisruptionDuration(e.target.value)}
                  required
                  aria-label="Duration Minutes"
                />
              </div>

              <div style={{ display: 'flex', gap: '1rem', marginTop: '1rem' }}>
                <button type="submit" className="btn btn-danger" aria-label="Broadcast Disruption">
                  Broadcast Disruption
                </button>
                <button type="button" className="btn btn-secondary" onClick={() => setShowDisruptionModal(false)}>
                  Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Cancel Request Modal */}
      {showCancelModal && (
        <div className="modal-overlay" role="dialog" aria-modal="true" aria-label="Cancel Request Modal">
          <div className="modal-content">
            <div className="card-header">
              <h2 className="card-title">Cancel Collection Request</h2>
              <button className="btn btn-secondary btn-sm" onClick={() => setShowCancelModal(false)}>✕</button>
            </div>
            <form onSubmit={handleCancelSubmit} aria-label="Cancel Request Form">
              <div className="form-group">
                <label htmlFor="cncl_reqId">Request ID or Tracking Number</label>
                <input
