import React, { useState, useEffect } from 'react';
import { api } from '../api';
import { AuditLog } from '../types';

export const AuditLogView: React.FC = () => {
  const [logs, setLogs] = useState<AuditLog[]>([]);
  const [loading, setLoading] = useState(false);
  const [query, setQuery] = useState('');
  const [entityType, setEntityType] = useState('');
  const [entityId, setEntityId] = useState('');
  const [fromTime, setFromTime] = useState('');
  const [toTime, setToTime] = useState('');

  const fetchLogs = async () => {
    setLoading(true);
    try {
      const res = await api.searchAuditTrail({
        query: query || undefined,
        entityType: entityType || undefined,
        entityId: entityId || undefined,
        fromTime: fromTime ? new Date(fromTime).toISOString() : undefined,
        toTime: toTime ? new Date(toTime).toISOString() : undefined,
        limit: 100,
      });
      setLogs(res.logs || (Array.isArray(res) ? res : []));
    } catch (err: any) {
      console.error('Failed to search audit logs', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchLogs();
  }, []);

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    fetchLogs();
  };

  return (
    <div role="region" aria-label="Audit Trail Portal">
      <div className="card">
        <div className="card-header">
          <h2 className="card-title">Audit Trail & Compliance Logs</h2>
          <button className="btn btn-secondary btn-sm" onClick={fetchLogs}>Refresh</button>
        </div>

        {/* Search & Filter Form */}
        <form onSubmit={handleSearchSubmit} aria-label="Audit Search Form" style={{ marginBottom: '1.5rem' }}>
          <div className="form-row">
            <div className="form-group">
              <label htmlFor="auditQuery">Search Query</label>
              <input
                id="auditQuery"
                type="text"
                className="form-input"
                placeholder="Search action, actor, notes..."
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                aria-label="Search Query"
              />
            </div>

            <div className="form-group">
              <label htmlFor="auditEntityType">Entity Type</label>
              <select
                id="auditEntityType"
                className="form-select"
                value={entityType}
                onChange={(e) => setEntityType(e.target.value)}
                aria-label="Entity Type"
              >
                <option value="">All Entity Types</option>
                <option value="sample">Sample</option>
                <option value="journey">Journey / Route</option>
                <option value="journey_leg">Journey Leg</option>
                <option value="handoff">Handoff</option>
                <option value="capacity">Capacity</option>
                <option value="user">User / Auth</option>
                <option value="location">Location</option>
                <option value="disruption">Disruption</option>
              </select>
            </div>

            <div className="form-group">
              <label htmlFor="auditEntityId">Entity ID</label>
              <input
                id="auditEntityId"
                type="text"
                className="form-input"
                placeholder="Specific entity or sample ID"
                value={entityId}
                onChange={(e) => setEntityId(e.target.value)}
                aria-label="Entity ID"
              />
            </div>
          </div>

          <div className="form-row">
            <div className="form-group">
              <label htmlFor="auditFrom">From Date/Time</label>
              <input
                id="auditFrom"
                type="datetime-local"
                className="form-input"
                value={fromTime}
                onChange={(e) => setFromTime(e.target.value)}
                aria-label="From Date"
              />
            </div>

            <div className="form-group">
              <label htmlFor="auditTo">To Date/Time</label>
              <input
                id="auditTo"
                type="datetime-local"
                className="form-input"
                value={toTime}
                onChange={(e) => setToTime(e.target.value)}
                aria-label="To Date"
              />
            </div>

            <div className="form-group" style={{ display: 'flex', alignItems: 'flex-end' }}>
              <button type="submit" className="btn btn-primary" style={{ width: '100%' }} aria-label="Search Audit Trail">
                Search Audit Trail
              </button>
            </div>
          </div>
        </form>

        {loading ? (
          <p>Searching audit trail...</p>
        ) : logs.length === 0 ? (
          <p className="text-muted" style={{ fontStyle: 'italic' }}>No audit records found matching your filters.</p>
        ) : (
          <div className="table-container">
            <table className="data-table" aria-label="Audit Logs Table">
              <thead>
                <tr>
                  <th>Timestamp</th>
                  <th>Action</th>
                  <th>Actor / Role</th>
                  <th>Entity</th>
                  <th>Outcome</th>
                  <th>Details</th>
                </tr>
              </thead>
              <tbody>
                {logs.map((log) => (
                  <tr key={log.id}>
                    <td style={{ whiteSpace: 'nowrap', fontSize: '0.8rem' }}>
                      {new Date(log.timestamp).toLocaleString()}
                    </td>
                    <td>
                      <strong>{log.action}</strong>
                    </td>
                    <td>
                      {log.actorUsername || log.actorId ? (
                        <div>
                          <div>{log.actorUsername || log.actorId}</div>
                          {log.actorRole && <span className="badge badge-pending">{log.actorRole}</span>}
                        </div>
                      ) : (
                        'System'
                      )}
                    </td>
                    <td>
                      <div><code>{log.entityType}</code></div>
                      {log.entityId && <span style={{ fontSize: '0.75rem', color: '#64748b' }}>{log.entityId}</span>}
                    </td>
                    <td>
                      <span className={`badge badge-${log.outcome === 'success' || log.outcome === 'accepted' ? 'received' : 'exception'}`}>
                        {log.outcome}
                      </span>
                    </td>
                    <td style={{ fontSize: '0.8rem', maxWidth: '300px', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                      {typeof log.details === 'object' ? JSON.stringify(log.details) : log.details || '-'}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
};

