              <form onSubmit={handleAssignRole} aria-label="Assign Role Form">
                <div className="form-group">
                  <label htmlFor="targetUserId">User ID</label>
                  <input
                    id="targetUserId"
                    type="text"
                    className="form-input"
                    value={targetUserId}
                    onChange={(e) => setTargetUserId(e.target.value)}
                    required
                    placeholder="Enter User ID"
                    aria-label="User ID"
                  />
                </div>

                <div className="form-group">
                  <label htmlFor="roleToAssign">Role</label>
                  <select
                    id="roleToAssign"
                    className="form-select"
                    value={roleToAssign}
                    onChange={(e) => setRoleToAssign(e.target.value)}
                    aria-label="Role to Assign"
                  >
                    <option value="requester">Requester</option>
                    <option value="certified_collection_professional">Certified Collection Professional</option>
                    <option value="relay_courier">Relay Courier</option>
                    <option value="node_handler">Node Handler</option>
                    <option value="laboratory_intake_operator">Laboratory Intake Operator</option>
                    <option value="dispatcher">Dispatcher</option>
                    <option value="administrator">Administrator</option>
                  </select>
                </div>

                <button type="submit" className="btn btn-primary" aria-label="Assign Role">
                  Assign Role
                </button>
              </form>
            </div>

            <div className="card">
              <div className="card-header">
                <h2 className="card-title">Assign Facility to Handler / Operator</h2>
              </div>
              <form onSubmit={handleAssignFacility} aria-label="Assign Facility Form">
                <div className="form-group">
                  <label htmlFor="facilityTargetUserId">User ID</label>
                  <input
                    id="facilityTargetUserId"
                    type="text"
                    className="form-input"
                    value={facilityTargetUserId}
                    onChange={(e) => setFacilityTargetUserId(e.target.value)}
                    required
                    placeholder="Enter User ID"
                    aria-label="Facility User ID"
                  />
                </div>

                <div className="form-group">
                  <label htmlFor="targetFacilityId">Assigned Facility</label>
                  <select
                    id="targetFacilityId"
                    className="form-select"
                    value={targetFacilityId}
                    onChange={(e) => {
                      setTargetFacilityId(e.target.value);
                      const loc = locations.find((l) => l.id === e.target.value);
                      setTargetFacilityType(loc?.type === 'laboratory' ? 'laboratory' : 'node');
                    }}
                    aria-label="Assigned Facility"
                  >
                    {locations.map((l) => (
                      <option key={l.id} value={l.id}>
                        {l.name} ({l.code}) - {l.type}
                      </option>
                    ))}
                  </select>
                </div>

                <button type="submit" className="btn btn-primary" aria-label="Assign Facility">
                  Assign Facility
                </button>
              </form>
            </div>
          </div>
        </div>
      )}

      {/* Global Capacity Tab */}
      {activeTab === 'capacity' && (
        <div className="card">
          <div className="card-header">
            <h2 className="card-title">Configure Facility / Connection Capacity</h2>
          </div>
          <form onSubmit={handleConfigureCapacity} aria-label="Global Capacity Form" style={{ maxWidth: '500px' }}>
            <div className="form-group">
              <label htmlFor="capFacility">Facility</label>
              <select
                id="capFacility"
                className="form-select"
                value={capFacilityId}
                onChange={(e) => setCapFacilityId(e.target.value)}
                aria-label="Target Facility"
              >
                {locations.map((l) => (
                  <option key={l.id} value={l.id}>
                    {l.name} ({l.code}) - {l.type}
                  </option>
                ))}
              </select>
            </div>

            <div className="form-group">
              <label htmlFor="adminCapType">Capacity Type</label>
              <select
                id="adminCapType"
                className="form-select"
                value={capType}
                onChange={(e: any) => setCapType(e.target.value)}
                aria-label="Capacity Type"
              >
                <option value="regular">Regular Capacity</option>
                <option value="cooled">Cooled Capacity</option>
              </select>
            </div>

            <div className="form-group">
              <label htmlFor="adminCapUnits">Configured Total Units</label>
              <input
                id="adminCapUnits"
                type="number"
                min="0"
                className="form-input"
                value={capUnits}
                onChange={(e) => setCapUnits(e.target.value)}
                required
                aria-label="Configured Units"
              />
            </div>

            <button type="submit" className="btn btn-primary" aria-label="Save Capacity">
              Save Capacity Configuration
            </button>
          </form>
        </div>
      )}

      {/* Lab Acceptance Tab */}
      {activeTab === 'labAcceptance' && (
        <div className="card">
          <div className="card-header">
            <h2 className="card-title">Configure Laboratory Sample Acceptance</h2>
          </div>
          <p className="text-muted" style={{ marginBottom: '1rem', fontSize: '0.875rem' }}>
            Specify which sample types each laboratory is equipped and authorized to process.
          </p>

          <form onSubmit={handleConfigureLabAcceptance} aria-label="Configure Lab Acceptance Form" style={{ maxWidth: '600px' }}>
            <div className="form-group">
              <label htmlFor="labSelector">Laboratory</label>
              <select
                id="labSelector"
                className="form-select"
                value={labId}
                onChange={(e) => setLabId(e.target.value)}
                aria-label="Select Laboratory"
              >
                {locations.filter((l) => l.type === 'laboratory' || l.type === 'hub_laboratory').map((l) => (
                  <option key={l.id} value={l.id}>
                    {l.name} ({l.code})
                  </option>
                ))}
              </select>
            </div>

            <div className="form-group">
              <label>Accepted Sample Types</label>
              <div style={{ display: 'flex', gap: '1.25rem', flexWrap: 'wrap', marginTop: '0.5rem' }}>
                {sampleTypes.map((st) => (
                  <label key={st.id || st.code} style={{ display: 'flex', alignItems: 'center', gap: '0.35rem', cursor: 'pointer' }}>
                    <input
                      type="checkbox"
                      checked={acceptedTypes.includes(st.code)}
                      onChange={(e) => {
