                        }
                      }}
                    />
                    <span><strong>{st.code}</strong> - {st.name}</span>
                  </label>
                ))}
              </div>
            </div>

            <button type="submit" className="btn btn-primary" aria-label="Save Lab Acceptance">
              Save Acceptance Configuration
            </button>
          </form>
        </div>
      )}
    </div>
  );
