import React, { useState, useEffect } from 'react';
import { api } from '../api';
import { Location, SampleType, CapacityPool } from '../types';

interface AdminViewProps {
  locations: Location[];
  sampleTypes: SampleType[];
  onRefresh: () => void;
}

export const AdminView: React.FC<AdminViewProps> = ({ locations, sampleTypes, onRefresh }) => {
  const [activeTab, setActiveTab] = useState<'locations' | 'sampleTypes' | 'users' | 'capacity' | 'labAcceptance'>('locations');
  const [actionError, setActionError] = useState<string | null>(null);
  const [actionSuccess, setActionSuccess] = useState<string | null>(null);

  // Create Location State
  const [locName, setLocName] = useState('');
  const [locCode, setLocCode] = useState('');
  const [locType, setLocType] = useState('collection_point');
  const [locAddress, setLocAddress] = useState('');
  const [locLat, setLocLat] = useState('12.9716');
  const [locLng, setLocLng] = useState('77.5946');
  const [locFunctions, setLocFunctions] = useState<string[]>(['collection']);

  // Create Sample Type State
  const [stCode, setStCode] = useState('');
  const [stName, setStName] = useState('');
  const [stContainer, setStContainer] = useState('standard_tube');
  const [stMinTemp, setStMinTemp] = useState('2.0');
  const [stMaxTemp, setStMaxTemp] = useState('8.0');
  const [stRequiresQualified, setStRequiresQualified] = useState(true);
  const [stIsTimeCritical, setStIsTimeCritical] = useState(false);

  // User Management State
  const [newUsername, setNewUsername] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [newFullName, setNewFullName] = useState('');
  const [newEmail, setNewEmail] = useState('');
  const [newRoles, setNewRoles] = useState<string[]>(['certified_collection_professional']);

  // Role Assignment State
  const [targetUserId, setTargetUserId] = useState('');
  const [roleToAssign, setRoleToAssign] = useState('relay_courier');

  // Facility Assignment State
  const [facilityTargetUserId, setFacilityTargetUserId] = useState('');
  const [targetFacilityId, setTargetFacilityId] = useState(locations[0]?.id || '');
  const [targetFacilityType, setTargetFacilityType] = useState('node');

  // Capacity Form State
  const [capFacilityId, setCapFacilityId] = useState(locations[0]?.id || '');
  const [capType, setCapType] = useState<'regular' | 'cooled'>('regular');
  const [capUnits, setCapUnits] = useState('50');

  // Lab Acceptance State
  const [labId, setLabId] = useState(locations.find((l) => l.type === 'laboratory')?.id || locations[0]?.id || '');
  const [acceptedTypes, setAcceptedTypes] = useState<string[]>(['AMBER', 'INDIGO', 'FROST', 'PULSE']);

  const handleCreateLocation = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionError(null);
    setActionSuccess(null);

    try {
      await api.createLocation({
        name: locName,
        code: locCode,
        type: locType,
        functions: locFunctions,
        address: locAddress,
        latitude: parseFloat(locLat),
        longitude: parseFloat(locLng),
      });
      setActionSuccess(`Location ${locName} created successfully!`);
      setLocName('');
      setLocCode('');
      setLocAddress('');
      onRefresh();
    } catch (err: any) {
      setActionError(err.message || 'Failed to create location');
    }
  };

  const handleToggleLocationStatus = async (locationId: string, currentStatus: string) => {
    setActionError(null);
    try {
      const nextStatus = currentStatus === 'active' ? 'inactive' : 'active';
      await api.setLocationStatus(locationId, nextStatus, 'Admin toggle');
      setActionSuccess(`Location status set to ${nextStatus}`);
      onRefresh();
    } catch (err: any) {
      setActionError(err.message || 'Failed to toggle location status');
    }
  };

  const handleCreateSampleType = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionError(null);
    setActionSuccess(null);

    try {
      await api.createSampleType({
        code: stCode.toUpperCase(),
        name: stName,
        requiredContainer: stContainer,
        minTemperatureCelsius: parseFloat(stMinTemp),
        maxTemperatureCelsius: parseFloat(stMaxTemp),
        requiresQualifiedCollector: stRequiresQualified,
        isTimeCritical: stIsTimeCritical,
      });
      setActionSuccess(`Sample type ${stCode} created successfully!`);
      setStCode('');
      setStName('');
      onRefresh();
    } catch (err: any) {
      setActionError(err.message || 'Failed to create sample type');
    }
  };

  const handleCreateUser = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionError(null);
    setActionSuccess(null);

    try {
      await api.createUser({
        username: newUsername,
        password: newPassword,
        fullName: newFullName,
        email: newEmail,
        roles: newRoles,
      });
      setActionSuccess(`User ${newUsername} created successfully!`);
      setNewUsername('');
      setNewPassword('');
      setNewFullName('');
      setNewEmail('');
    } catch (err: any) {
      setActionError(err.message || 'Failed to create user');
    }
  };

  const handleAssignRole = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionError(null);
    try {
      await api.assignUserRole(targetUserId, roleToAssign);
      setActionSuccess(`Role ${roleToAssign} assigned to user`);
    } catch (err: any) {
      setActionError(err.message || 'Failed to assign role');
    }
  };

  const handleAssignFacility = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionError(null);
    try {
      await api.assignUserFacility(facilityTargetUserId, targetFacilityId, targetFacilityType);
      setActionSuccess('Facility assigned to user');
    } catch (err: any) {
      setActionError(err.message || 'Failed to assign facility');
    }
  };

  const handleConfigureCapacity = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionError(null);
    try {
      await api.configureCapacity({
        facilityId: capFacilityId,
        capacityType: capType,
        configuredUnits: parseInt(capUnits, 10),
      });
      setActionSuccess(`${capType.toUpperCase()} capacity set to ${capUnits} units`);
    } catch (err: any) {
      setActionError(err.message || 'Failed to configure capacity');
    }
  };

  const handleConfigureLabAcceptance = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionError(null);
    try {
      await api.configureLaboratoryAcceptance({
        laboratoryId: labId,
        acceptedSampleTypeCodes: acceptedTypes,
      });
      setActionSuccess('Laboratory sample type acceptance updated successfully');
    } catch (err: any) {
      setActionError(err.message || 'Failed to configure lab acceptance');
    }
  };

  return (
    <div role="region" aria-label="Administrator Portal">
      {actionError && (
        <div className="alert alert-danger" role="alert" aria-live="assertive">
          <span>{actionError}</span>
        </div>
      )}
      {actionSuccess && (
        <div className="alert alert-success" role="alert" aria-live="polite">
          <span>{actionSuccess}</span>
        </div>
      )}

      <div className="tabs-nav" role="tablist">
        <button
          className={`tab-btn ${activeTab === 'locations' ? 'active' : ''}`}
          onClick={() => setActiveTab('locations')}
          role="tab"
          aria-selected={activeTab === 'locations'}
          aria-label="Manage Locations Tab"
        >
          📍 Locations & Functions
        </button>
        <button
          className={`tab-btn ${activeTab === 'sampleTypes' ? 'active' : ''}`}
          onClick={() => setActiveTab('sampleTypes')}
          role="tab"
          aria-selected={activeTab === 'sampleTypes'}
          aria-label="Manage Sample Types Tab"
        >
          🧪 Sample Types
        </button>
        <button
          className={`tab-btn ${activeTab === 'users' ? 'active' : ''}`}
          onClick={() => setActiveTab('users')}
          role="tab"
          aria-selected={activeTab === 'users'}
          aria-label="Manage Users Tab"
        >
          👥 Users & Certifications
        </button>
        <button
          className={`tab-btn ${activeTab === 'capacity' ? 'active' : ''}`}
          onClick={() => setActiveTab('capacity')}
          role="tab"
          aria-selected={activeTab === 'capacity'}
          aria-label="Configure Capacity Tab"
        >
          📦 Global Capacity
        </button>
        <button
          className={`tab-btn ${activeTab === 'labAcceptance' ? 'active' : ''}`}
          onClick={() => setActiveTab('labAcceptance')}
          role="tab"
          aria-selected={activeTab === 'labAcceptance'}
          aria-label="Laboratory Acceptance Tab"
        >
          🏥 Lab Acceptance
        </button>
      </div>

      {/* Locations Tab */}
      {activeTab === 'locations' && (
        <div>
          <div className="card">
            <div className="card-header">
              <h2 className="card-title">Network Locations ({locations.length})</h2>
              <button className="btn btn-secondary btn-sm" onClick={onRefresh}>Refresh</button>
            </div>
            <div className="table-container">
              <table className="data-table" aria-label="Locations Table">
                <thead>
                  <tr>
                    <th>Code</th>
                    <th>Name</th>
                    <th>Type</th>
                    <th>Functions</th>
                    <th>Status</th>
                    <th>Coordinates</th>
                    <th>Action</th>
                  </tr>
                </thead>
                <tbody>
                  {locations.map((loc) => (
                    <tr key={loc.id}>
                      <td><strong>{loc.code}</strong></td>
                      <td>{loc.name}</td>
                      <td>{loc.type}</td>
                      <td>{(loc.functions || []).join(', ')}</td>
                      <td><span className={`badge badge-${loc.status === 'active' ? 'received' : 'exception'}`}>{loc.status}</span></td>
                      <td>{loc.latitude.toFixed(4)}, {loc.longitude.toFixed(4)}</td>
                      <td>
                        <button
                          className={`btn btn-${loc.status === 'active' ? 'danger' : 'success'} btn-sm`}
                          onClick={() => handleToggleLocationStatus(loc.id, loc.status)}
                          aria-label={`Toggle status for ${loc.code}`}
                        >
                          {loc.status === 'active' ? 'Deactivate' : 'Activate'}
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          <div className="card">
            <div className="card-header">
              <h2 className="card-title">+ Create Network Location</h2>
            </div>
            <form onSubmit={handleCreateLocation} aria-label="Create Location Form">
              <div className="form-row">
                <div className="form-group">
                  <label htmlFor="locName">Location Name</label>
                  <input
                    id="locName"
                    type="text"
                    className="form-input"
                    value={locName}
                    onChange={(e) => setLocName(e.target.value)}
                    required
                    placeholder="e.g. South Bangalore Collection Hub"
                    aria-label="Location Name"
                  />
                </div>

                <div className="form-group">
                  <label htmlFor="locCode">Location Code</label>
                  <input
                    id="locCode"
                    type="text"
                    className="form-input"
                    value={locCode}
                    onChange={(e) => setLocCode(e.target.value)}
                    required
                    placeholder="e.g. BLR-HUB-02"
                    aria-label="Location Code"
                  />
                </div>

                <div className="form-group">
                  <label htmlFor="locType">Location Type</label>
                  <select
                    id="locType"
                    className="form-select"
                    value={locType}
                    onChange={(e) => setLocType(e.target.value)}
                    aria-label="Location Type"
                  >
                    <option value="collection_point">Collection Point</option>
                    <option value="transfer_point">Transfer Point</option>
                    <option value="hub">Hub</option>
                    <option value="laboratory">Laboratory</option>
                    <option value="hub_laboratory">Hub & Laboratory</option>
                  </select>
                </div>
              </div>

              <div className="form-group">
                <label htmlFor="locAddress">Address</label>
                <input
                  id="locAddress"
                  type="text"
                  className="form-input"
                  value={locAddress}
                  onChange={(e) => setLocAddress(e.target.value)}
                  required
                  placeholder="Physical street address"
                  aria-label="Location Address"
                />
              </div>

              <div className="form-row">
                <div className="form-group">
                  <label htmlFor="locLat">Latitude</label>
                  <input
                    id="locLat"
                    type="text"
                    className="form-input"
                    value={locLat}
                    onChange={(e) => setLocLat(e.target.value)}
                    required
                    aria-label="Latitude"
                  />
                </div>

                <div className="form-group">
                  <label htmlFor="locLng">Longitude</label>
                  <input
                    id="locLng"
                    type="text"
                    className="form-input"
                    value={locLng}
                    onChange={(e) => setLocLng(e.target.value)}
                    required
                    aria-label="Longitude"
                  />
                </div>
              </div>

              <button type="submit" className="btn btn-primary" aria-label="Create Location">
                Create Location
              </button>
            </form>
          </div>
        </div>
      )}

      {/* Sample Types Tab */}
      {activeTab === 'sampleTypes' && (
        <div>
          <div className="card">
            <div className="card-header">
              <h2 className="card-title">Configured Sample Types ({sampleTypes.length})</h2>
            </div>
            <div className="table-container">
              <table className="data-table" aria-label="Sample Types Table">
                <thead>
                  <tr>
                    <th>Code</th>
                    <th>Name</th>
                    <th>Container</th>
                    <th>Temp Range (°C)</th>
                    <th>Collector Qualified?</th>
                    <th>Time Critical?</th>
                  </tr>
                </thead>
                <tbody>
                  {sampleTypes.map((st) => (
                    <tr key={st.id || st.code}>
                      <td><strong>{st.code}</strong></td>
                      <td>{st.name}</td>
                      <td>{st.requiredContainer}</td>
                      <td>{st.minTemperatureCelsius}°C to {st.maxTemperatureCelsius}°C</td>
                      <td>{st.requiresQualifiedCollector ? 'Yes' : 'No'}</td>
                      <td>{st.isTimeCritical ? <span className="badge badge-exception">Pulse / Immediate</span> : 'Batchable'}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          <div className="card">
            <div className="card-header">
              <h2 className="card-title">+ Create / Update Sample Type</h2>
            </div>
            <form onSubmit={handleCreateSampleType} aria-label="Create Sample Type Form">
              <div className="form-row">
                <div className="form-group">
                  <label htmlFor="stCode">Type Code</label>
                  <input
                    id="stCode"
                    type="text"
                    className="form-input"
                    value={stCode}
                    onChange={(e) => setStCode(e.target.value)}
                    required
                    placeholder="e.g. CYTO"
                    aria-label="Sample Type Code"
                  />
                </div>

                <div className="form-group">
                  <label htmlFor="stName">Display Name</label>
                  <input
                    id="stName"
                    type="text"
                    className="form-input"
                    value={stName}
                    onChange={(e) => setStName(e.target.value)}
                    required
                    placeholder="e.g. Cytology Sample"
                    aria-label="Display Name"
                  />
                </div>

