import React, { useEffect, useRef } from 'react';
import maplibregl from 'maplibre-gl';
import * as pmtiles from 'pmtiles';

// Register PMTiles protocol once globally
let protocolAdded = false;
function initProtocol() {
  if (!protocolAdded) {
    const protocol = new pmtiles.Protocol();
    maplibregl.addProtocol('pmtiles', protocol.tile);
    protocolAdded = true;
  }
}

interface MapLocation {
  id: string;
  name: string;
  type?: string;
  latitude: number;
  longitude: number;
  status?: string;
  role?: string;
  isStale?: boolean;
}

interface MapComponentProps {
  locations?: MapLocation[];
  workers?: MapLocation[];
  routes?: any[];
  center?: [number, number];
  zoom?: number;
  height?: string;
}

export const MapComponent: React.FC<MapComponentProps> = ({
  locations = [],
  workers = [],
  routes = [],
  center = [77.5946, 12.9716],
  zoom = 11,
  height = '450px',
}) => {
  const mapContainer = useRef<HTMLDivElement>(null);
  const mapInstance = useRef<maplibregl.Map | null>(null);
  const markersRef = useRef<maplibregl.Marker[]>([]);

  useEffect(() => {
    initProtocol();

    if (!mapContainer.current) return;

    const map = new maplibregl.Map({
      container: mapContainer.current,
      style: '/map-assets/style.json',
      center: center,
      zoom: zoom,
    });

    map.addControl(new maplibregl.NavigationControl(), 'top-right');
    mapInstance.current = map;

    return () => {
      map.remove();
      mapInstance.current = null;
    };
  }, []);

  // Update markers when locations or workers change
  useEffect(() => {
    const map = mapInstance.current;
    if (!map) return;

    // Clear old markers
    markersRef.current.forEach((m) => m.remove());
    markersRef.current = [];

    // Add Location markers
    locations.forEach((loc) => {
      if (loc.latitude && loc.longitude) {
        const el = document.createElement('div');
        el.className = 'map-marker-facility';
        const isLab = loc.type === 'laboratory' || loc.type === 'hub_laboratory';
        el.style.width = '24px';
        el.style.height = '24px';
        el.style.borderRadius = '50%';
        el.style.backgroundColor = isLab ? '#7c3aed' : '#0284c7';
        el.style.border = '2px solid white';
        el.style.boxShadow = '0 2px 4px rgba(0,0,0,0.3)';
        el.style.cursor = 'pointer';

        const popup = new maplibregl.Popup({ offset: 25 }).setHTML(`
          <strong>${loc.name}</strong><br/>
          Type: ${loc.type || 'Node'}<br/>
          Status: ${loc.status || 'Active'}
        `);

        const marker = new maplibregl.Marker({ element: el })
          .setLngLat([loc.longitude, loc.latitude])
          .setPopup(popup)
          .addTo(map);

        markersRef.current.push(marker);
      }
    });

    // Add Worker markers
    workers.forEach((w) => {
      if (w.latitude && w.longitude) {
        const el = document.createElement('div');
        el.className = 'map-marker-worker';
        el.style.width = '20px';
        el.style.height = '20px';
        el.style.borderRadius = '50%';
        el.style.backgroundColor = w.isStale ? '#dc2626' : '#16a34a';
        el.style.border = '2px solid white';
        el.style.boxShadow = '0 2px 4px rgba(0,0,0,0.3)';
        el.style.cursor = 'pointer';

        const popup = new maplibregl.Popup({ offset: 25 }).setHTML(`
          <strong>${w.name}</strong><br/>
          Role: ${w.role || 'Worker'}<br/>
          ${w.isStale ? '<span style="color:red">Location is STALE</span>' : 'Location fresh'}
        `);

        const marker = new maplibregl.Marker({ element: el })
          .setLngLat([w.longitude, w.latitude])
          .setPopup(popup)
          .addTo(map);

        markersRef.current.push(marker);
      }
    });
  }, [locations, workers]);

  return (
    <div
      ref={mapContainer}
      className="map-container"
      style={{ height }}
      role="region"
      aria-label="Interactive Map"
    />
  );
};

