[?2004lconst API_BASE = '/api';

export class ApiError extends Error {
  status: number;
  data: any;

  constructor(message: string, status: number, data?: any) {
    super(message);
    this.name = 'ApiError';
    this.status = status;
    this.data = data;
  }
}

let sessionToken: string | null = localStorage.getItem('sessionToken');

export const setSessionToken = (token: string | null) => {
  sessionToken = token;
  if (token) {
    localStorage.setItem('sessionToken', token);
  } else {
    localStorage.removeItem('sessionToken');
  }
};

export const getSessionToken = () => sessionToken;

export async function apiRequest<T = any>(
  endpoint: string,
  options: RequestInit = {}
): Promise<T> {
  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
    ...(options.headers as Record<string, string>),
  };

  if (sessionToken) {
    headers['Authorization'] = `Bearer ${sessionToken}`;
  }

  const url = endpoint.startsWith('http') ? endpoint : `${API_BASE}${endpoint.startsWith('/') ? '' : '/'}${endpoint}`;

  const response = await fetch(url, {
    ...options,
    headers,
  });

  const contentType = response.headers.get('content-type');
  let data: any = null;
  if (contentType && contentType.includes('application/json')) {
    try {
      data = await response.json();
    } catch {
      data = null;
    }
  } else {
    const text = await response.text();
    try {
      data = JSON.parse(text);
    } catch {
      data = text;
    }
  }

  if (!response.ok) {
    const message = data?.message || data?.error || (typeof data === 'string' ? data : `HTTP ${response.status}`);
    throw new ApiError(message, response.status, data);
  }

  return data as T;
}

// API Methods
export const api = {
  // Auth
  login: async (username: string, password: string) => {
    const res = await apiRequest('/authenticate-user', {
      method: 'POST',
      body: JSON.stringify({ username, password }),
    });
    return res.data || res;
  },

  selectActiveRole: async (activeRole: string) => {
    const res = await apiRequest('/select-active-role', {
      method: 'POST',
      body: JSON.stringify({ activeRole }),
    });
    return res.data || res;
  },

  getBootstrap: async () => {
    const res = await apiRequest('/bootstrap-ui-state', {
      method: 'POST',
      body: JSON.stringify({}),
    });
    return res.data || res;
  },

  // Serviceability & Requests
  checkServiceability: async (payload: {
    originLatitude: number;
    originLongitude: number;
    originAddress?: string;
    sampleTypeCode: string;
    collectionWindowStart: string;
    collectionWindowEnd: string;
    deliveryDeadline: string;
  }) => {
    const res = await apiRequest('/check-serviceability', {
      method: 'POST',
      body: JSON.stringify(payload),
    });
    return res.data || res;
  },

  createRequest: async (payload: {
    originType: string;
    originLatitude: number;
    originLongitude: number;
    originAddress: string;
    sampleTypeCode: string;
    collectionWindowStart: string;
    collectionWindowEnd: string;
    deliveryDeadline: string;
    patientNotes?: string;
  }) => {
    const res = await apiRequest('/create-collection-request', {
