  },

  registerPresealedSample: async (payload: {
    trackingNumber?: string;
    originLocationId: string;
    sampleTypeCode: string;
    sealNumber: string;
    deliveryDeadline: string;
    observedContainer?: string;
    observedTemperature?: number;
